    request_token: str = Field(
        description='The request_token returned from the long running operation'
    ),
    region: str | None = Field(
        description='The AWS region that the operation should be performed in', default=None
    ),
) -> dict:
    """Get the status of a long running operation with the request token."""
    return await get_resource_request_status_impl(request_token, region or 'us-east-1')

async def check_environment_variables() -> dict:
    """Check if required environment variables are set correctly."""
    return await check_environment_variables_impl(_workflow_store)

async def analyze_canary_failures(
    canary_name: str, region: str = AWS_REGION, description: str = ''
) -> str:
    """Comprehensive canary failure analysis with deep dive into issues.

    Use this tool to:
    - Deep dive into canary failures with root cause identification
    - Analyze historical patterns and specific incident details
    - Get comprehensive artifact analysis including logs, screenshots, and HAR files
    - Receive actionable recommendations based on AWS debugging methodology
    - Correlate canary failures with Application Signals telemetry data
    - Identify performance degradation and availability issues across service dependencies

    Key Features:
    - **Failure Pattern Analysis**: Identifies recurring failure modes and temporal patterns
    - **Artifact Deep Dive**: Analyzes canary logs, screenshots, and network traces for root causes
    - **Service Correlation**: Links canary failures to upstream/downstream service issues using Application Signals
    - **Performance Insights**: Detects latency spikes, fault rates, and connection issues
    - **Actionable Remediation**: Provides specific steps based on AWS operational best practices

    Common Use Cases:
    1. **Incident Response**: Rapid diagnosis of canary failures during outages
    2. **Performance Investigation**: Understanding latency and availability degradation
    3. **Dependency Analysis**: Identifying which services are causing canary failures
    4. **Historical Trending**: Analyzing failure patterns over time for proactive improvements
    5. **Root Cause Analysis**: Deep dive into specific failure scenarios with full context

    Output Includes:
    - Severity-ranked findings with immediate action items
    - Service-level telemetry insights with trace analysis
    - Exception details and stack traces from canary artifacts
    - Network connectivity and performance metrics
    - Correlation with Application Signals audit findings
    - Historical failure patterns and recovery recommendations

    Args:
        canary_name (str): Name of the CloudWatch Synthetics canary to analyze
        region (str, optional): AWS region where the canary is deployed.
        description (str, optional): User's description of the issue they are experiencing.
            This is matched against the knowledge base to surface relevant recommendations
            even when the canary error logs alone may not contain enough context.
            Examples: "missing runs in console", "visual monitoring baseline keeps resetting",
            "CloudFormation rollback failed after runtime upgrade".

    Returns:
        dict: Comprehensive failure analysis containing:
            - Failure severity assessment and immediate recommendations
            - Detailed artifact analysis (logs, screenshots, HAR files)
            - Service dependency health and performance metrics
            - Root cause identification with specific remediation steps
            - Historical pattern analysis and trend insights
    """
    try:
        # Get recent canary runs
        response = synthetics_client.get_canary_runs(Name=canary_name, MaxResults=5)
        runs = response.get('CanaryRuns', [])

        # Get canary details
        canary_response = synthetics_client.get_canary(Name=canary_name)
        canary = canary_response['Canary']

        # Get telemetry and service insights
        try:
            telemetry_insights = await get_canary_metrics_and_service_insights(canary_name, region)
        except Exception as e:
            telemetry_insights = f'Telemetry API unavailable: {str(e)}'

        if not runs:
            return f'No run history found for {canary_name}'

        # Build analysis header
        result = f'🔍 Comprehensive Failure Analysis for {canary_name}\n'

        # Add telemetry insights if available
        if telemetry_insights and not telemetry_insights.startswith('Telemetry API unavailable'):
            result += f'\n📊 **Service and Canary Telemetry Insights**\n{telemetry_insights}\n\n'
        elif telemetry_insights:
            result += f'\n⚠️ {telemetry_insights}\n\n'

        # Get consecutive failures since last success
        consecutive_failures = []
        last_success_run = None

        for run in runs:
            if run.get('Status', {}).get('State') == RUN_STATES['FAILED']:
                consecutive_failures.append(run)
            elif run.get('Status', {}).get('State') == RUN_STATES['PASSED']:
                last_success_run = run
                break

        if not consecutive_failures:
            result += '✅ Canary is healthy - no failures since last success\n'
            if last_success_run:
                result += f'Last success: {last_success_run.get("Timeline", {}).get("Started")}\n'
            result += '\n🔍 Performing health check analysis ...\n\n'

        # Group failures by StateReason
        failure_causes = {}
        result += f'🔍 Found {len(consecutive_failures)} consecutive failures since last success\n'
        if last_success_run:
            result += f'Last success: {last_success_run.get("Timeline", {}).get("Started")}\n\n'
        else:
            result += 'No recent success run found in history\n\n'

        for failed_run in consecutive_failures:
            state_reason = failed_run.get('Status', {}).get('StateReason', 'Unknown')

            if state_reason not in failure_causes:
                failure_causes[state_reason] = []
            failure_causes[state_reason].append(failed_run)

        # Analysis section
        unique_reasons = list(failure_causes.keys())

        if not unique_reasons:
            result += '✅ No consecutive failures to analyze\n'
            result += '💡 Canary appears to be recovering or healthy\n'

            # Still run KB lookup when user provided an issue description
            if description:
                try:
                    # Cap description length to mitigate slow regex matching in KB patterns
                    capped_description = (
                        description[:500] if len(description) > 500 else description
                    )
                    kb_error_messages_healthy: list[str] = [capped_description]
                    failure_context_healthy = FailureContext(
                        error_messages=kb_error_messages_healthy,
                        runtime_version=canary.get('RuntimeVersion', ''),
                    )
                    engine_healthy = CanaryRecommendationEngine(
                        await CanaryKnowledgeBaseLoader.get_instance()
                    )
                    recommendations_healthy = engine_healthy.get_recommendations(
                        failure_context_healthy
                    )
                    if recommendations_healthy:
                        result += engine_healthy.format_recommendations(recommendations_healthy)
                except Exception as e:
                    logger.warning(f'Knowledge base recommendation failed (healthy path): {e}')

            return result

        if len(unique_reasons) == 1:
            result += f'🎯 All failures have same cause: {unique_reasons[0]}\n'
            selected_reason = unique_reasons[0]
        else:
            result += f'🎯 Multiple failure causes ({len(unique_reasons)} different issues):\n\n'
            for i, reason in enumerate(unique_reasons, 1):
                count = len(failure_causes[reason])
                result += f'{i}. **{reason}** ({count} occurrences)\n'
            result += '\n'
            selected_reason = unique_reasons[0]

        selected_failure = failure_causes[selected_reason][0]
        result += f'Analyzing most recent failure: {selected_failure.get("Id", "")[:8]}...\n\n'

        # Initialize artifact variables
        har_files = []
        screenshots = []
        logs = []
        bucket_name = ''
        # Accumulate detailed error messages from all sources for KB matching
        all_collected_error_messages: list[str] = []
        all_collected_log_patterns: list[str] = []
        s3_log_analysis: dict = {}
        cw_log_analysis: dict = {}

        # Direct S3 artifact analysis integration
        artifact_location = canary.get('ArtifactS3Location', '')
        artifacts_available = False

        if artifact_location:
            # Handle S3 location format
            if not artifact_location.startswith('s3://'):
                artifact_location = f's3://{artifact_location}' if artifact_location else ''

            if artifact_location.startswith('s3://'):
                bucket_and_path = artifact_location[5:]
                bucket_name = bucket_and_path.split('/')[0]
                base_path = (
                    '/'.join(bucket_and_path.split('/')[1:]) if '/' in bucket_and_path else ''
                )

                # If base_path is empty, construct canary path
                if not base_path:
                    base_path = f'canary/{region}/{canary_name}'

                # Check for failure artifacts using date-based path
                from datetime import datetime

                failure_time = selected_failure.get('Timeline', {}).get('Started')
                if failure_time:
                    # Handle both datetime objects and string timestamps
                    if isinstance(failure_time, str):
                        dt = parse_timestamp(failure_time)
                    else:
                        dt = failure_time  # Already a datetime object
                    date_path = dt.strftime('%Y/%m/%d')
                    failure_run_path = (
                        f'{base_path}/{date_path}/' if base_path else f'{date_path}/'
                    )
                else:
                    # Fallback to today
                    today = datetime.now().strftime('%Y/%m/%d')
                    failure_run_path = f'{base_path}/{today}/' if base_path else f'{today}/'

                try:
                    artifacts_response = s3_client.list_objects_v2(
                        Bucket=bucket_name, Prefix=failure_run_path, MaxKeys=50
                    )
                    failure_artifacts = artifacts_response.get('Contents', [])

                    if failure_artifacts:
                        artifacts_available = True

                        # Categorize artifacts
                        har_files = [
                            a
                            for a in failure_artifacts
                            if a['Key'].lower().endswith(('.har', '.har.gz', '.har.html'))
                        ]
                        screenshots = [
                            a
                            for a in failure_artifacts
                            if any(ext in a['Key'].lower() for ext in ['.png', '.jpg', '.jpeg'])
                        ]
                        logs = [
                            a
                            for a in failure_artifacts
                            if any(ext in a['Key'].lower() for ext in ['.log', '.txt'])
                            or 'log' in a['Key'].lower()
                        ]

                        if last_success_run:
                            result += '🔄 HAR COMPARISON: Failure vs Success\n'
                            result += f'Failure: {selected_failure.get("Id", "")[:8]}... ({selected_failure.get("Timeline", {}).get("Started")})\n'
                            result += f'Success: {last_success_run.get("Id", "")[:8]}... ({last_success_run.get("Timeline", {}).get("Started")})\n\n'

                            # Get success artifacts for comparison
                            success_time = last_success_run.get('Timeline', {}).get('Started')
                            if success_time:
                                if isinstance(success_time, str):
                                    success_dt = parse_timestamp(success_time)
                                else:
                                    success_dt = success_time
                                success_date_path = success_dt.strftime('%Y/%m/%d')
                                success_run_path = (
                                    f'{base_path}/{success_date_path}/'
                                    if base_path
                                    else f'{success_date_path}/'
                                )
                            else:
                                success_run_path = failure_run_path  # Use same path as fallback
                            try:
                                success_artifacts_response = s3_client.list_objects_v2(
                                    Bucket=bucket_name, Prefix=success_run_path, MaxKeys=50
                                )
                                success_artifacts = success_artifacts_response.get('Contents', [])
                                success_har_files = [
                                    a
                                    for a in success_artifacts
                                    if a['Key'].lower().endswith(('.har', '.har.gz', '.har.html'))
                                ]

                                if har_files and success_har_files:
                                    failure_har = await analyze_har_file(
                                        s3_client, bucket_name, har_files, is_failed_run=True
                                    )
                                    success_har = await analyze_har_file(
                                        s3_client,
                                        bucket_name,
                                        success_har_files,
                                        is_failed_run=False,
                                    )

                                    result += f'• Failed requests: {failure_har.get("failed_requests", 0)} vs {success_har.get("failed_requests", 0)}\n'
                                    result += f'• Total requests: {failure_har.get("total_requests", 0)} vs {success_har.get("total_requests", 0)}\n\n'

                                    if failure_har.get('request_details'):
                                        result += '🚨 FAILED REQUESTS:\n'
                                        for req in failure_har['request_details'][:3]:
                                            result += f'• {req.get("url", "Unknown")}: {req.get("status", "Unknown")} ({req.get("time", 0):.1f}ms)\n'
                            except Exception as e:
                                logger.warning(
                                    f'Failed to analyze success artifacts for HAR comparison: {str(e)}'
                                )
                        else:
                            result += (
                                '🔍 FAILURE ANALYSIS (no success run available for comparison):\n'
                            )
                            result += f'Analyzing failure artifacts for: {selected_failure.get("Id", "")[:8]}...\n\n'

                            if har_files:
                                failure_har = await analyze_har_file(
                                    s3_client, bucket_name, har_files, is_failed_run=True
                                )
                                result += '🌐 HAR ANALYSIS:\n'
                                result += (
                                    f'• Failed requests: {failure_har.get("failed_requests", 0)}\n'
                                )
                                result += (
                                    f'• Total requests: {failure_har.get("total_requests", 0)}\n\n'
                                )

                        # Screenshot analysis
                        if screenshots:
                            screenshot_analysis = await analyze_screenshots(
                                s3_client, bucket_name, screenshots, is_failed_run=True
                            )
                            if screenshot_analysis.get('insights'):
                                result += '📸 SCREENSHOT ANALYSIS:\n'
                                for insight in screenshot_analysis['insights'][:3]:
                                    result += f'• {insight}\n'
                                result += '\n'

                        # Log analysis
                        if logs:
                            s3_log_analysis = await analyze_log_files(
                                s3_client, bucket_name, logs, is_failed_run=True
                            )
                            if s3_log_analysis.get('insights'):
                                result += '📋 LOG ANALYSIS:\n'
                                for insight in s3_log_analysis['insights'][:3]:
                                    result += f'• {insight}\n'
                                    all_collected_log_patterns.append(str(insight))
                                result += '\n'
                            # Collect error messages from S3 log artifacts
                            for evt in s3_log_analysis.get('error_events', []):
                                msg = str(evt.get('message', ''))
                                if msg:
                                    all_collected_error_messages.append(msg)
                            for insight in s3_log_analysis.get('insights', []):
                                msg = str(insight)
                                if msg:
                                    all_collected_error_messages.append(msg)

                except Exception:
                    artifacts_available = False

        if not artifacts_available:
            # Fallback: CloudWatch Logs analysis
            result += '⚠️ Artifacts not available - Checking CloudWatch Logs for root cause\n'
            result += f'🎯 StateReason: {selected_reason}\n\n'

            failure_time = selected_failure.get('Timeline', {}).get('Started')
            if failure_time:
                cw_log_analysis = await analyze_canary_logs_with_time_window(
                    canary_name, failure_time, canary, window_minutes=5, region=region
                )

                if cw_log_analysis.get('status') == 'success':
                    result += '📋 CLOUDWATCH LOGS ANALYSIS (±5 min around failure):\n'
                    result += f'Time window: {cw_log_analysis["time_window"]}\n'
                    result += f'Log events found: {cw_log_analysis["total_events"]}\n\n'

                    error_logs = cw_log_analysis.get('error_events', [])
                    if error_logs:
                        result += '📋 ERROR LOGS AROUND FAILURE:\n'
                        for error in error_logs:
                            result += f'• {error["timestamp"].strftime("%H:%M:%S")}: {error["message"]}\n'
                            all_collected_error_messages.append(str(error.get('message', '')))
                    for insight in cw_log_analysis.get('insights', []):
                        all_collected_log_patterns.append(str(insight))
                else:
                    result += f'📋 {cw_log_analysis.get("insights", ["Log analysis failed"])[0]}\n'
            else:
                result += '📋 No failure timestamp available for targeted log analysis\n'

        # Always attempt CloudWatch Logs analysis for KB enrichment, even when S3 artifacts were available
        if artifacts_available:
            failure_time = selected_failure.get('Timeline', {}).get('Started')
            if failure_time:
                try:
                    cw_log_analysis = await analyze_canary_logs_with_time_window(
                        canary_name, failure_time, canary, window_minutes=5, region=region
                    )
                    if cw_log_analysis.get('status') == 'success':
                        for evt in cw_log_analysis.get('error_events', []):
                            msg = str(evt.get('message', ''))
                            if msg and msg not in all_collected_error_messages:
                                all_collected_error_messages.append(msg)
                        for insight in cw_log_analysis.get('insights', []):
                            pattern = str(insight)
                            if pattern and pattern not in all_collected_log_patterns:
                                all_collected_log_patterns.append(pattern)
                except Exception as e:
                    logger.debug(f'CloudWatch Logs enrichment for KB failed: {e}')

        # Add critical IAM checking guidance for systematic issues
        if (
            'no test result' in str(selected_reason).lower()
            or 'permission' in str(selected_reason).lower()
            or 'access denied' in str(selected_reason).lower()
        ):
            try:
                result += f"\n🔍 RUNNING COMPREHENSIVE IAM ANALYSIS (common cause of '{selected_reason}'):\n"

                # 1. Check IAM role and policies
                iam_analysis = await analyze_iam_role_and_policies(canary, iam_client, region)

                # Display IAM analysis results
                result += f'IAM Role Analysis Status: {iam_analysis["status"]}\n'
                for check_name, check_result in iam_analysis.get('checks', {}).items():
                    result += f'• {check_name}: {check_result}\n'

                # 2. ENHANCED: Check resource ARN correctness with detailed validation
                result += '\n🔍 CHECKING RESOURCE ARN CORRECTNESS:\n'
                arn_check = check_resource_arns_correct(canary, iam_client)

                if arn_check.get('correct'):
                    result += '✅ Resource ARNs: Correct\n'
                else:
                    result += f'❌ Resource ARNs: {arn_check.get("error", "Issues found")}\n'

                # Combine all IAM issues with enhanced categorization
                all_iam_issues = []
                if iam_analysis.get('issues_found'):
                    all_iam_issues.extend(
                        [f'IAM Policy: {issue}' for issue in iam_analysis['issues_found']]
                    )
                if not arn_check.get('correct') and arn_check.get('issues'):
                    all_iam_issues.extend(
                        [f'Resource ARN: {issue}' for issue in arn_check['issues']]
                    )

                if all_iam_issues:
                    result += f'\n🚨 ALL IAM ISSUES FOUND ({len(all_iam_issues)} total):\n'
                    for issue in all_iam_issues:
                        result += f'• {issue}\n'

                # Enhanced IAM recommendations with priority
                all_iam_recommendations = []
                if iam_analysis.get('recommendations'):
                    all_iam_recommendations.extend(
                        [f'Policy Fix: {rec}' for rec in iam_analysis['recommendations']]
                    )
                if not arn_check.get('correct'):
                    all_iam_recommendations.extend(
                        [
                            'PRIORITY: Review and correct S3 bucket ARN patterns in IAM policies',
                            'PRIORITY: Ensure bucket names match expected patterns (e.g., cw-syn-* for CloudWatch Synthetics)',
                            'Verify canary has access to the correct S3 bucket for artifacts storage',
                            'Check if bucket exists and is in the same region as the canary',
                        ]
                    )

                if all_iam_recommendations:
                    result += (
                        f'\n💡 ALL IAM RECOMMENDATIONS ({len(all_iam_recommendations)} total):\n'
                    )
                    for rec in all_iam_recommendations:
                        result += f'• {rec}\n'

            except Exception as iam_error:
                result += f'⚠️ IAM analysis failed: {str(iam_error)[:200]}\n\n'

        # History-based diagnosis for specific error patterns
        error_recommendations = []

        # 1. ENOSPC: no space left on device
        if any(
            re.search(pattern, selected_reason, re.IGNORECASE)
            for pattern in ['enospc', 'no space left on device']
        ):
            try:
                telemetry_data = await extract_disk_memory_usage_metrics(canary_name, region)
                if 'error' not in telemetry_data:
                    result += '\n🔍 DISK USAGE ROOT CAUSE ANALYSIS:\n'
                    result += f'• Storage: {telemetry_data.get("maxEphemeralStorageUsageInMb", 0):.1f} MB peak\n'
                    result += f'• Usage: {telemetry_data.get("maxEphemeralStorageUsagePercent", 0):.1f}% peak\n'
                else:
                    result += f'\n🔍 DISK USAGE ROOT CAUSE ANALYSIS:\n{telemetry_data["error"]}\n'
            except Exception as debug_error:
                result += f'\n⚠️ Could not generate disk usage debugging code: {str(debug_error)}\n'

        # 2. Protocol error (Target.activateTarget): Session closed / detached Frame
        elif any(
            re.search(pattern, selected_reason, re.IGNORECASE)
            for pattern in [
                'protocol error',
                'target.activatetarget',
                'session closed',
                'detached frame',
                'session already detached',
            ]
        ):
            try:
                telemetry_data = await extract_disk_memory_usage_metrics(canary_name, region)
                if 'error' not in telemetry_data:
                    result += '\n🔍 MEMORY USAGE ROOT CAUSE ANALYSIS:\n'
                    result += f'• Memory: {telemetry_data.get("maxSyntheticsMemoryUsageInMB", 0):.1f} MB peak\n'
                else:
                    result += (
                        f'\n🔍 MEMORY USAGE ROOT CAUSE ANALYSIS:\n{telemetry_data["error"]}\n'
                    )
            except Exception as debug_error:
                result += f'\n⚠️ Could not collect memory usage metrics: {str(debug_error)}\n'

        # 3. Navigation timed out / Page.captureScreenshot timed out
        elif any(
            re.search(pattern, selected_reason, re.IGNORECASE)
            for pattern in [
                'navigation timeout',
                'navigation timed out',
                'ms exceeded',
                'page.capturescreenshot timed out',
                'protocoltimeout',
                'connection timed out',
            ]
        ):
            # Navigation timeout specific analysis using existing HAR data
            if har_files and bucket_name:
                try:
                    har_timeout_analysis = await analyze_har_file(
                        s3_client, bucket_name, har_files, is_failed_run=True
                    )

                    result += '\n🔍 HAR FILE ANALYSIS FOR NAVIGATION TIMEOUT:\n'
                    if har_timeout_analysis.get('failed_requests', 0) > 0:
                        result += (
                            f'• Failed HTTP requests: {har_timeout_analysis["failed_requests"]}\n'
                        )

                    if har_timeout_analysis.get('insights'):
                        for insight in har_timeout_analysis['insights'][:5]:
                            result += f'• {insight}\n'

                    # Additional timeout-specific analysis
                    result += f'• Total requests analyzed: {har_timeout_analysis.get("total_requests", 0)}\n'
                    result += (
                        f'• Analysis status: {har_timeout_analysis.get("status", "unknown")}\n'
                    )
                    result += '\n'
                except Exception as har_error:
                    result += f'\n⚠️ HAR analysis failed: {str(har_error)[:100]}\n'
            else:
                result += '\n🔍 NAVIGATION TIMEOUT DETECTED:\n'
                result += '• No HAR files available for detailed analysis\n'
                result += '• Timeout suggests page loading issues or UI changes\n'
                result += '• Check if target elements exist and page loads completely\n\n'

        # 4. Visual variation
        elif re.search('visual variation', selected_reason, re.IGNORECASE):
            error_recommendations.extend(
                [
                    '🔧 VISUAL MONITORING ISSUE DETECTED:',
                    '• Website UI changed - not a technical failure',
                    '• Check if website legitimately updated (ads, banners, content)',
                    '• Update visual baseline with new reference screenshots',
                    '• Adjust visual difference threshold (increase from default)',
                    '• Consider excluding dynamic content areas from comparison',
                ]
            )

        if error_recommendations:
            result += '\n💡 PATTERN-BASED RECOMMENDATIONS:\n'
            for rec in error_recommendations:
                result += f'{rec}\n'
            result += '\n'

        # Add canary code if available
        try:
            code_analysis = await get_canary_code(canary, region)
            if 'error' not in code_analysis and code_analysis.get('code_content'):
                result += f'\ncanary code:\n{code_analysis["code_content"]}\n'
        except Exception as e:
            result += f'Note: Could not retrieve canary code: {str(e)}\n'

        # --- Knowledge Base Recommendations ---
        try:
            # Build environment_indicators from canary tags and category context
            kb_env_indicators: list[str] = []
            canary_tags = canary.get('Tags', {})
            if isinstance(canary_tags, dict):
                kb_env_indicators.extend(canary_tags.values())
            elif isinstance(canary_tags, list):
                for tag in canary_tags:
                    if isinstance(tag, dict):
                        kb_env_indicators.append(tag.get('Value', ''))

            # Build error_messages: StateReason + all collected detailed errors + user description
            kb_error_messages: list[str] = [selected_reason]
            if description:
                # Cap description length to mitigate slow regex matching in KB patterns
                kb_error_messages.append(
                    description[:500] if len(description) > 500 else description
                )
            for msg in all_collected_error_messages:
                if msg and msg not in kb_error_messages:
                    kb_error_messages.append(msg)

            failure_context = FailureContext(
                error_messages=kb_error_messages,
                state_reasons=[selected_reason],
                runtime_version=canary.get('RuntimeVersion', ''),
                log_patterns=all_collected_log_patterns,
                environment_indicators=kb_env_indicators,
            )
            engine = CanaryRecommendationEngine(await CanaryKnowledgeBaseLoader.get_instance())
            recommendations = engine.get_recommendations(failure_context)
            if recommendations:
                result += engine.format_recommendations(recommendations)
        except Exception as e:
            logger.warning(f'Knowledge base recommendation failed: {e}')

        result += '\n'
        return result

    except Exception as e:
        return f'❌ Error in comprehensive failure analysis: {str(e)}'

async def read_document(
    ctx: Context,
    file_path: str = Field(..., description='Path to the document file to read'),
    file_type: str = Field(
        ..., description="Type of document: 'pdf', 'docx', 'doc', 'xlsx', 'xls', 'pptx', or 'ppt'"
    ),
    timeout_seconds: int = Field(
        DEFAULT_TIMEOUT_SECONDS, description='Timeout in seconds (min: 5, max: 300)', ge=5, le=300
    ),
) -> DocumentReadResponse:
    """Extract content from various document formats (PDF, Word, Excel, PowerPoint)."""
    # Normalize file_type to lowercase
    file_type = file_type.lower()

    # Validate file_type parameter
    supported_types = {'pdf', 'docx', 'doc', 'xlsx', 'xls', 'pptx', 'ppt'}
    if file_type not in supported_types:
        return DocumentReadResponse(
            status='error',
            content='',
            file_path=file_path,
            error_message=f'Unsupported file_type: {file_type}. Supported types: {", ".join(sorted(supported_types))}',
        )

    # Handle PDF files with pdfplumber
    if file_type == 'pdf':
        return await _read_pdf_content(ctx, file_path, timeout_seconds)

    # Handle Office documents with markitdown
    elif file_type in {'docx', 'doc'}:
        return await _convert_with_markitdown(ctx, file_path, 'Word document', timeout_seconds)
    elif file_type in {'xlsx', 'xls'}:
        return await _convert_with_markitdown(ctx, file_path, 'Excel file', timeout_seconds)
    elif file_type in {'pptx', 'ppt'}:
        return await _convert_with_markitdown(ctx, file_path, 'PowerPoint file', timeout_seconds)

    # This should never be reached due to validation above, but pyright needs explicit return
    return DocumentReadResponse(
        status='error',
        content='',
        file_path=file_path,
        error_message=f'Unsupported file_type: {file_type}. This should not happen.',
    )

async def create_jump_host_cc(
    cache_cluster_id: str,
    key_name: str,
    subnet_id: Optional[str] = None,
    security_group_id: Optional[str] = None,
    instance_type: str = 't3.small',
) -> Dict[str, Any]:
    """Creates an EC2 jump host instance to access an ElastiCache cluster via SSH tunnel.

    Args:
        cache_cluster_id (str): ID of the ElastiCache cluster to connect to
        key_name (str): Name of the EC2 key pair to use for SSH access
        subnet_id (str, optional): ID of the subnet to launch the EC2 instance in (must be public).
            If not provided and cache uses default VPC, will auto-select a default subnet.
        security_group_id (str, optional): ID of the security group to assign to the EC2 instance.
            If not provided and cache uses default VPC, will use the default security group.
        instance_type (str, optional): EC2 instance type. Defaults to "t3.small"

    Returns:
        Dict[str, Any]: Dictionary containing the created EC2 instance details

    Raises:
        ValueError: If subnet is not public or VPC compatibility check fails
    """
    # Check if readonly mode is enabled
    if Context.readonly_mode():
        raise ValueError(
            'You have configured this tool in readonly mode. To make this change you will have to update your configuration.'
        )

    # Get AWS clients from connection managers
    ec2_client = EC2ConnectionManager.get_connection()
    elasticache_client = ElastiCacheConnectionManager.get_connection()

    try:
        # Validate key_name
        if not key_name:
            raise ValueError(
                'key_name is required. Use CreateKeyPair or ImportKeyPair EC2 APIs to create/import an SSH key pair.'
            )

        # Verify key pair exists
        key_pairs = ec2_client.describe_key_pairs(KeyNames=[key_name])
        if not key_pairs.get('KeyPairs'):
            return {
                'error': f"Key pair '{key_name}' not found. Use CreateKeyPair or ImportKeyPair EC2 APIs to create/import an SSH key pair."
            }

        # Get cache cluster details to find its VPC
        cache_cluster = elasticache_client.describe_cache_clusters(
            CacheClusterId=cache_cluster_id, ShowCacheNodeInfo=True
        )['CacheClusters'][0]

        cache_subnet_group = elasticache_client.describe_cache_subnet_groups(
            CacheSubnetGroupName=cache_cluster['CacheSubnetGroupName']
        )['CacheSubnetGroups'][0]
        cache_vpc_id = cache_subnet_group['VpcId']

        # Check if cache is in default VPC
        vpcs = ec2_client.describe_vpcs(VpcIds=[cache_vpc_id])['Vpcs']
        cache_vpc = vpcs[0] if vpcs else None
        is_default_vpc = cache_vpc and cache_vpc.get('IsDefault', False)

        # Auto-select subnet if not provided and cache is in default VPC
        if not subnet_id and is_default_vpc:
            # Get default subnets in the default VPC
            subnets = ec2_client.describe_subnets(
                Filters=[
                    {'Name': 'vpc-id', 'Values': [cache_vpc_id]},
                    {'Name': 'default-for-az', 'Values': ['true']},
                ]
            )['Subnets']

            if subnets:
                # Pick the first available default subnet
                subnet_id = subnets[0]['SubnetId']
            else:
                # Fallback to any public subnet in the VPC
                all_subnets = ec2_client.describe_subnets(
                    Filters=[{'Name': 'vpc-id', 'Values': [cache_vpc_id]}]
                )['Subnets']

                for subnet in all_subnets:
                    if subnet.get('MapPublicIpOnLaunch', False):
                        subnet_id = subnet['SubnetId']
                        break

        # Auto-select security group if not provided and cache is in default VPC
        if not security_group_id and is_default_vpc:
            # Get the default security group for the VPC
            security_groups = ec2_client.describe_security_groups(
                Filters=[
                    {'Name': 'vpc-id', 'Values': [cache_vpc_id]},
                    {'Name': 'group-name', 'Values': ['default']},
                ]
            )['SecurityGroups']

            if security_groups:
                security_group_id = security_groups[0]['GroupId']

        # Validate required parameters after auto-selection
        if not subnet_id:
            raise ValueError(
                'subnet_id is required. Either provide a subnet_id or ensure the cache cluster is in the default VPC with default subnets available.'
            )

        if not security_group_id:
            raise ValueError(
                'security_group_id is required. Either provide a security_group_id or ensure the cache cluster is in the default VPC.'
            )

        # Get subnet details and verify it's public
        subnet_response = ec2_client.describe_subnets(SubnetIds=[subnet_id])
        subnet = subnet_response['Subnets'][0]
        subnet_vpc_id = subnet['VpcId']

        # Check VPC compatibility
        if subnet_vpc_id != cache_vpc_id:
            raise ValueError(
                f'Subnet VPC ({subnet_vpc_id}) does not match cache cluster VPC ({cache_vpc_id})'
            )

        # Check if subnet is public by looking for route to internet gateway
        # or if it's a default subnet in the default VPC (which are automatically public)
        route_tables = ec2_client.describe_route_tables(
            Filters=[{'Name': 'association.subnet-id', 'Values': [subnet_id]}]
        )['RouteTables']

        is_public = False
        for rt in route_tables:
            for route in rt.get('Routes', []):
                if route.get('GatewayId', '').startswith('igw-'):
                    is_public = True
                    break
            if is_public:
                break

        # If no explicit route table association, check the main route table for the VPC
        if not is_public and not route_tables:
            main_route_tables = ec2_client.describe_route_tables(
                Filters=[
                    {'Name': 'vpc-id', 'Values': [subnet_vpc_id]},
                    {'Name': 'association.main', 'Values': ['true']},
                ]
            )['RouteTables']

            for rt in main_route_tables:
                for route in rt.get('Routes', []):
                    if route.get('GatewayId', '').startswith('igw-'):
                        is_public = True
                        break
                if is_public:
                    break

        # If not found via route table, check if it's a default subnet in default VPC
        if not is_public:
            # Check if this is the default VPC
            vpcs = ec2_client.describe_vpcs(VpcIds=[subnet_vpc_id])['Vpcs']
            vpc = vpcs[0] if vpcs else None

            if vpc and vpc.get('IsDefault', False):
                # In default VPC, check if this is a default subnet
                # Default subnets have MapPublicIpOnLaunch set to True
                if subnet.get('DefaultForAz', False) or subnet.get('MapPublicIpOnLaunch', False):
                    is_public = True

        if not is_public:
            raise ValueError(
                f'Subnet {subnet_id} is not public (no route to internet gateway found and not a default subnet in default VPC). '
                'The subnet must be public to allow SSH access to the jump host.'
            )

        # Use Amazon Linux 2023 AMI
        images = ec2_client.describe_images(
            Filters=[
                {'Name': 'name', 'Values': ['al2023-ami-2023.*-x86_64']},
                {'Name': 'owner-alias', 'Values': ['amazon']},
            ]
        )
        ami_id = sorted(images['Images'], key=lambda x: x['CreationDate'], reverse=True)[0][
            'ImageId'
        ]

        # Verify and update security group rules for SSH access
        security_group = ec2_client.describe_security_groups(GroupIds=[security_group_id])[
            'SecurityGroups'
        ][0]

        # Check if port 22 is already open
        has_ssh_rule = False
        for rule in security_group.get('IpPermissions', []):
            if (
                rule.get('IpProtocol') == 'tcp'
                and rule.get('FromPort') == 22
                and rule.get('ToPort') == 22
                and any(
                    ip_range.get('CidrIp') == '0.0.0.0/0' for ip_range in rule.get('IpRanges', [])
                )
            ):
                has_ssh_rule = True
                break

        # Add SSH rule if it doesn't exist
        if not has_ssh_rule:
            ec2_client.authorize_security_group_ingress(
                GroupId=security_group_id,
                IpPermissions=[
                    {
                        'IpProtocol': 'tcp',
                        'FromPort': 22,
                        'ToPort': 22,
                        'IpRanges': [
                            {'CidrIp': '0.0.0.0/0', 'Description': 'SSH access from anywhere'}
                        ],
                    }
                ],
            )

        # Launch EC2 instance
        instance = ec2_client.run_instances(
            ImageId=ami_id,
            InstanceType=instance_type,
            KeyName=key_name,
            MaxCount=1,
            MinCount=1,
            NetworkInterfaces=[
                {
                    'SubnetId': subnet_id,
                    'DeviceIndex': 0,
                    'AssociatePublicIpAddress': True,
                    'Groups': [security_group_id],
                }
            ],
            TagSpecifications=[
                {
                    'ResourceType': 'instance',
                    'Tags': [{'Key': 'Name', 'Value': f'ElastiCache-JumpHost-{cache_cluster_id}'}],
                }
            ],
        )

        # Wait for instance to be running and get its public IP
        waiter = ec2_client.get_waiter('instance_running')
        instance_id = instance['Instances'][0]['InstanceId']
        waiter.wait(InstanceIds=[instance_id])

        instance_info = ec2_client.describe_instances(InstanceIds=[instance_id])
        public_ip = instance_info['Reservations'][0]['Instances'][0]['PublicIpAddress']

        # Configure security groups using common function
        configured, vpc_id, cache_port = await _configure_security_groups(
            cache_cluster_id,
            instance_id,
            ec2_client=ec2_client,
            elasticache_client=elasticache_client,
        )

        return {
            'InstanceId': instance_id,
            'PublicIpAddress': public_ip,
            'InstanceType': instance_type,
            'SubnetId': subnet_id,
            'SecurityGroupId': security_group_id,
            'CacheClusterId': cache_cluster_id,
            'SecurityGroupsConfigured': configured,
            'CachePort': cache_port,
            'VpcId': vpc_id,
        }

    except ClientError as e:
        if e.response['Error']['Code'] == 'InvalidKeyPair.NotFound':
            return {
                'error': f"Key pair '{key_name}' not found. Use CreateKeyPair or ImportKeyPair EC2 APIs to create/import an SSH key pair."
            }
        return {'error': str(e)}
    except Exception as e:
        return {'error': str(e)}

async def create_cache_cluster(request: CreateCacheClusterRequest) -> Dict:
    """Create an Amazon ElastiCache cache cluster."""
    # Check if readonly mode is enabled
    if Context.readonly_mode():
        raise ValueError(
            'You have configured this tool in readonly mode. To make this change you will have to update your configuration.'
        )

    # Get ElastiCache client
    elasticache_client = ElastiCacheConnectionManager.get_connection()

    # Convert request model to dictionary, only including non-None values
    create_request: Dict[str, Any] = {
        'CacheClusterId': request.cache_cluster_id
    }  # Required parameter

    # Optional parameters - only include if they have a value
    if request.cache_node_type is not None:
        create_request['CacheNodeType'] = request.cache_node_type
    if request.engine is not None:
        create_request['Engine'] = request.engine
    if request.engine_version is not None:
        create_request['EngineVersion'] = request.engine_version
    if request.num_cache_nodes is not None:
        create_request['NumCacheNodes'] = request.num_cache_nodes
    if request.preferred_availability_zone is not None:
        create_request['PreferredAvailabilityZone'] = request.preferred_availability_zone
    if request.preferred_availability_zones is not None:
        create_request['PreferredAvailabilityZones'] = request.preferred_availability_zones
    if request.cache_parameter_group_name is not None:
        create_request['CacheParameterGroupName'] = request.cache_parameter_group_name
    if request.cache_subnet_group_name is not None:
        create_request['CacheSubnetGroupName'] = request.cache_subnet_group_name
    if request.cache_security_group_names is not None:
        create_request['CacheSecurityGroupNames'] = request.cache_security_group_names
    if request.security_group_ids is not None:
        create_request['SecurityGroupIds'] = request.security_group_ids
    if request.tags:
        if isinstance(request.tags, str):
            # Parse shorthand syntax: Key=string,Value=string
            tag_list = []
            try:
                pairs = [p.strip() for p in request.tags.split(',') if p.strip()]
                for pair in pairs:
                    if '=' not in pair:
                        return {
                            'error': 'Invalid tag format. Each tag must be in Key=Value format'
                        }
                    key, value = pair.split('=', 1)
                    key = key.strip()
                    value = value.strip() if value.strip() else None
                    if not key:
                        return {'error': 'Tag key cannot be empty'}
                    tag_list.append({'Key': key, 'Value': value})
                create_request['Tags'] = tag_list
            except Exception as e:
                return {
                    'error': f'Invalid tag shorthand syntax. Expected format: Key=string,Value=string. Error: {str(e)}'
                }
        elif isinstance(request.tags, dict):
            # Handle dictionary format
            tag_list = []
            for k, v in request.tags.items():
                if not k:
                    return {'error': 'Tag key cannot be empty'}
                tag_list.append({'Key': k, 'Value': v})
            create_request['Tags'] = tag_list
        elif isinstance(request.tags, list):
            # Handle list format
            for tag in request.tags:
                if not isinstance(tag, dict) or 'Key' not in tag:
                    return {'error': 'Each tag must be a dictionary with a Key'}
                if not tag['Key']:
                    return {'error': 'Tag key cannot be empty'}
            create_request['Tags'] = request.tags
    if request.snapshot_arns is not None:
        create_request['SnapshotArns'] = request.snapshot_arns
    if request.snapshot_name is not None:
        create_request['SnapshotName'] = request.snapshot_name
    if request.preferred_maintenance_window is not None:
        create_request['PreferredMaintenanceWindow'] = request.preferred_maintenance_window
    if request.port is not None:
        create_request['Port'] = request.port
    if request.notification_topic_arn is not None:
        create_request['NotificationTopicArn'] = request.notification_topic_arn
    if request.auto_minor_version_upgrade is not None:
        create_request['AutoMinorVersionUpgrade'] = request.auto_minor_version_upgrade
    if request.snapshot_retention_limit is not None:
        create_request['SnapshotRetentionLimit'] = request.snapshot_retention_limit
    if request.snapshot_window is not None:
        create_request['SnapshotWindow'] = request.snapshot_window
    if request.auth_token is not None:
        create_request['AuthToken'] = request.auth_token
    if request.outpost_mode is not None:
        create_request['OutpostMode'] = request.outpost_mode
    if request.preferred_outpost_arn is not None:
        create_request['PreferredOutpostArn'] = request.preferred_outpost_arn
    if request.preferred_outpost_arns is not None:
        create_request['PreferredOutpostArns'] = request.preferred_outpost_arns
    if request.log_delivery_configurations:
        try:
            processed_configs = process_log_delivery_configurations(
                request.log_delivery_configurations
            )
            create_request['LogDeliveryConfigurations'] = processed_configs
        except ValueError as e:
            return {'error': str(e)}

    # Create the cache cluster
    response = elasticache_client.create_cache_cluster(**create_request)
    return response

