async def list_delivery_streams(
    limit: Any = None,
    delivery_stream_type: Any = None,
    exclusive_start_delivery_stream_name: Any = None,
) -> Dict[str, Any]:
    """List your delivery streams.

    Args:
        limit: The maximum number of delivery streams to list
        delivery_stream_type: The delivery stream type. This can be one of the following values:
            DirectPut - Provider data is sent directly to the Firehose stream
            KinesisStreamAsSource - Data is sourced from an existing Kinesis stream
        exclusive_start_delivery_stream_name: The name of the delivery stream to start the list after

    Returns:
        Dict containing the list of delivery streams and whether there are more streams available
    """
    client = FirehoseConnectionManager.get_connection()

    # Build request parameters
    params: Dict[str, Any] = {}
    if limit is not None:
        params['Limit'] = limit
    if delivery_stream_type is not None:
        params['DeliveryStreamType'] = delivery_stream_type
    if exclusive_start_delivery_stream_name is not None:
        params['ExclusiveStartDeliveryStreamName'] = exclusive_start_delivery_stream_name

    # Make API call
    try:
        response = client.list_delivery_streams(**params)
        return {
            'DeliveryStreamNames': response.get('DeliveryStreamNames', []),
            'HasMoreDeliveryStreams': response.get('HasMoreDeliveryStreams', False),
        }
    except Exception as e:
        return {'error': str(e)}

async def create_jump_host_rg(
    replication_group_id: str,
    key_name: str,
    subnet_id: Optional[str] = None,
    security_group_id: Optional[str] = None,
    instance_type: str = 't3.small',
) -> Dict[str, Any]:
    """Creates an EC2 jump host instance to access an ElastiCache replication group via SSH tunnel.

    Args:
        replication_group_id (str): ID of the ElastiCache replication group to connect to
        key_name (str): Name of the EC2 key pair to use for SSH access
        subnet_id (str, optional): ID of the subnet to launch the EC2 instance in (must be public).
            If not provided and replication group uses default VPC, will auto-select a default subnet.
        security_group_id (str, optional): ID of the security group to assign to the EC2 instance.
            If not provided and replication group uses default VPC, will use the default security group.
        instance_type (str, optional): EC2 instance type. Defaults to "t3.small"

    Returns:
        Dict[str, Any]: Dictionary containing the created EC2 instance details

    Raises:
        ValueError: If subnet is not public or VPC compatibility check fails
    """
    # Check if readonly mode is enabled
    if Context.readonly_mode():
        raise ValueError(
            'You have configured this tool in readonly mode. To make this change you will have to update your configuration.'
        )

    # Get AWS clients from connection managers
    ec2_client = EC2ConnectionManager.get_connection()
    elasticache_client = ElastiCacheConnectionManager.get_connection()

    try:
        # Validate key_name
        if not key_name:
            raise ValueError(
                'key_name is required. Use CreateKeyPair or ImportKeyPair EC2 APIs to create/import an SSH key pair.'
            )

        # Verify key pair exists
        key_pairs = ec2_client.describe_key_pairs(KeyNames=[key_name])
        if not key_pairs.get('KeyPairs'):
            return {
                'error': f"Key pair '{key_name}' not found. Use CreateKeyPair or ImportKeyPair EC2 APIs to create/import an SSH key pair."
            }

        # Get replication group details
        replication_group = elasticache_client.describe_replication_groups(
            ReplicationGroupId=replication_group_id
        )['ReplicationGroups'][0]

        # Get first cluster details (MemberClusters doesn't have notion of primary cluster)
        if not replication_group['MemberClusters']:
            raise ValueError(f'No clusters found in replication group {replication_group_id}')

        first_cluster_id = replication_group['MemberClusters'][0]

        # Get VPC details from first cluster
        first_cluster = elasticache_client.describe_cache_clusters(
            CacheClusterId=first_cluster_id, ShowCacheNodeInfo=True
        )['CacheClusters'][0]

        cache_subnet_group = elasticache_client.describe_cache_subnet_groups(
            CacheSubnetGroupName=first_cluster['CacheSubnetGroupName']
        )['CacheSubnetGroups'][0]
        cache_vpc_id = cache_subnet_group['VpcId']

        # Check if replication group is in default VPC
        vpcs = ec2_client.describe_vpcs(VpcIds=[cache_vpc_id])['Vpcs']
        cache_vpc = vpcs[0] if vpcs else None
        is_default_vpc = cache_vpc and cache_vpc.get('IsDefault', False)

        # Auto-select subnet if not provided and replication group is in default VPC
        if not subnet_id and is_default_vpc:
            # Get default subnets in the default VPC
            subnets = ec2_client.describe_subnets(
                Filters=[
                    {'Name': 'vpc-id', 'Values': [cache_vpc_id]},
                    {'Name': 'default-for-az', 'Values': ['true']},
                ]
            )['Subnets']

            if subnets:
                # Pick the first available default subnet
                subnet_id = subnets[0]['SubnetId']
            else:
                # Fallback to any public subnet in the VPC
                all_subnets = ec2_client.describe_subnets(
                    Filters=[{'Name': 'vpc-id', 'Values': [cache_vpc_id]}]
                )['Subnets']

                for subnet in all_subnets:
                    if subnet.get('MapPublicIpOnLaunch', False):
                        subnet_id = subnet['SubnetId']
                        break

        # Auto-select security group if not provided and replication group is in default VPC
        if not security_group_id and is_default_vpc:
            # Get the default security group for the VPC
            security_groups = ec2_client.describe_security_groups(
                Filters=[
                    {'Name': 'vpc-id', 'Values': [cache_vpc_id]},
                    {'Name': 'group-name', 'Values': ['default']},
                ]
            )['SecurityGroups']

            if security_groups:
                security_group_id = security_groups[0]['GroupId']

        # Validate required parameters after auto-selection
        if not subnet_id:
            raise ValueError(
                'subnet_id is required. Either provide a subnet_id or ensure the replication group is in the default VPC with default subnets available.'
            )

        if not security_group_id:
            raise ValueError(
                'security_group_id is required. Either provide a security_group_id or ensure the replication group is in the default VPC.'
            )

        # Get subnet details and verify it's public
        subnet_response = ec2_client.describe_subnets(SubnetIds=[subnet_id])
        subnet = subnet_response['Subnets'][0]
        subnet_vpc_id = subnet['VpcId']

        # Check VPC compatibility
        if subnet_vpc_id != cache_vpc_id:
            raise ValueError(
                f'Subnet VPC ({subnet_vpc_id}) does not match replication group VPC ({cache_vpc_id})'
            )

        # Check if subnet is public by looking for route to internet gateway
        # or if it's a default subnet in the default VPC (which are automatically public)
        route_tables = ec2_client.describe_route_tables(
            Filters=[{'Name': 'association.subnet-id', 'Values': [subnet_id]}]
        )['RouteTables']

        is_public = False
        for rt in route_tables:
            for route in rt.get('Routes', []):
                if route.get('GatewayId', '').startswith('igw-'):
                    is_public = True
                    break
            if is_public:
                break

        # If no explicit route table association, check the main route table for the VPC
        if not is_public and not route_tables:
            main_route_tables = ec2_client.describe_route_tables(
                Filters=[
                    {'Name': 'vpc-id', 'Values': [subnet_vpc_id]},
                    {'Name': 'association.main', 'Values': ['true']},
                ]
            )['RouteTables']

            for rt in main_route_tables:
                for route in rt.get('Routes', []):
                    if route.get('GatewayId', '').startswith('igw-'):
                        is_public = True
                        break
                if is_public:
                    break

        # If not found via route table, check if it's a default subnet in default VPC
        if not is_public:
            # Check if this is the default VPC
            vpcs = ec2_client.describe_vpcs(VpcIds=[subnet_vpc_id])['Vpcs']
            vpc = vpcs[0] if vpcs else None

            if vpc and vpc.get('IsDefault', False):
                # In default VPC, check if this is a default subnet
                # Default subnets have MapPublicIpOnLaunch set to True
                if subnet.get('DefaultForAz', False) or subnet.get('MapPublicIpOnLaunch', False):
                    is_public = True

        if not is_public:
            raise ValueError(
                f'Subnet {subnet_id} is not public (no route to internet gateway found and not a default subnet in default VPC). '
                'The subnet must be public to allow SSH access to the jump host.'
            )

        # Use Amazon Linux 2023 AMI
        images = ec2_client.describe_images(
            Filters=[
                {'Name': 'name', 'Values': ['al2023-ami-2023.*-x86_64']},
                {'Name': 'owner-alias', 'Values': ['amazon']},
            ]
        )
        ami_id = sorted(images['Images'], key=lambda x: x['CreationDate'], reverse=True)[0][
            'ImageId'
        ]

        # Verify and update security group rules for SSH access
        security_group = ec2_client.describe_security_groups(GroupIds=[security_group_id])[
            'SecurityGroups'
        ][0]

        # Check if port 22 is already open
        has_ssh_rule = False
        for rule in security_group.get('IpPermissions', []):
            if (
                rule.get('IpProtocol') == 'tcp'
                and rule.get('FromPort') == 22
                and rule.get('ToPort') == 22
                and any(
                    ip_range.get('CidrIp') == '0.0.0.0/0' for ip_range in rule.get('IpRanges', [])
                )
            ):
                has_ssh_rule = True
                break

        # Add SSH rule if it doesn't exist
        if not has_ssh_rule:
            ec2_client.authorize_security_group_ingress(
                GroupId=security_group_id,
                IpPermissions=[
                    {
                        'IpProtocol': 'tcp',
                        'FromPort': 22,
                        'ToPort': 22,
                        'IpRanges': [
                            {'CidrIp': '0.0.0.0/0', 'Description': 'SSH access from anywhere'}
                        ],
                    }
                ],
            )

        # Launch EC2 instance
        instance = ec2_client.run_instances(
            ImageId=ami_id,
            InstanceType=instance_type,
            KeyName=key_name,
            MaxCount=1,
            MinCount=1,
            NetworkInterfaces=[
                {
                    'SubnetId': subnet_id,
                    'DeviceIndex': 0,
                    'AssociatePublicIpAddress': True,
                    'Groups': [security_group_id],
                }
            ],
            TagSpecifications=[
                {
                    'ResourceType': 'instance',
                    'Tags': [
                        {'Key': 'Name', 'Value': f'ElastiCache-JumpHost-{replication_group_id}'}
                    ],
                }
            ],
        )

        # Wait for instance to be running and get its public IP
        waiter = ec2_client.get_waiter('instance_running')
        instance_id = instance['Instances'][0]['InstanceId']
        waiter.wait(InstanceIds=[instance_id])

        instance_info = ec2_client.describe_instances(InstanceIds=[instance_id])
        public_ip = instance_info['Reservations'][0]['Instances'][0]['PublicIpAddress']

        # Configure security groups using common function
        configured, vpc_id, cache_port = await _configure_security_groups(
            replication_group_id,
            instance_id,
            ec2_client=ec2_client,
            elasticache_client=elasticache_client,
        )

        return {
            'InstanceId': instance_id,
            'PublicIpAddress': public_ip,
            'InstanceType': instance_type,
            'SubnetId': subnet_id,
            'SecurityGroupId': security_group_id,
            'ReplicationGroupId': replication_group_id,
            'SecurityGroupsConfigured': configured,
            'CachePort': cache_port,
            'VpcId': vpc_id,
        }

    except ClientError as e:
        if e.response['Error']['Code'] == 'InvalidKeyPair.NotFound':
            return {
                'error': f"Key pair '{key_name}' not found. Use CreateKeyPair or ImportKeyPair EC2 APIs to create/import an SSH key pair."
            }
        return {'error': str(e)}
    except Exception as e:
        return {'error': str(e)}

async def create_jump_host_serverless(
    serverless_cache_name: str,
    key_name: str,
    subnet_id: Optional[str] = None,
    security_group_id: Optional[str] = None,
    instance_type: str = 't3.small',
) -> Dict[str, Any]:
    """Creates an EC2 jump host instance to access an ElastiCache serverless cache via SSH tunnel.

    Args:
        serverless_cache_name (str): Name of the ElastiCache serverless cache to connect to
        key_name (str): Name of the EC2 key pair to use for SSH access
        subnet_id (str, optional): ID of the subnet to launch the EC2 instance in (must be public).
            If not provided and serverless cache uses default VPC, will auto-select a default subnet.
        security_group_id (str, optional): ID of the security group to assign to the EC2 instance.
            If not provided and serverless cache uses default VPC, will use the default security group.
        instance_type (str, optional): EC2 instance type. Defaults to "t3.small"

    Returns:
        Dict[str, Any]: Dictionary containing the created EC2 instance details

    Raises:
        ValueError: If subnet is not public or VPC compatibility check fails
    """
    # Check if readonly mode is enabled
    if Context.readonly_mode():
        raise ValueError(
            'You have configured this tool in readonly mode. To make this change you will have to update your configuration.'
        )

    # Get AWS clients from connection managers
    ec2_client = EC2ConnectionManager.get_connection()
    elasticache_client = ElastiCacheConnectionManager.get_connection()

    try:
        # Validate key_name
        if not key_name:
            raise ValueError(
                'key_name is required. Use CreateKeyPair or ImportKeyPair EC2 APIs to create/import an SSH key pair.'
            )

        # Verify key pair exists
        key_pairs = ec2_client.describe_key_pairs(KeyNames=[key_name])
        if not key_pairs.get('KeyPairs'):
            return {
                'error': f"Key pair '{key_name}' not found. Use CreateKeyPair or ImportKeyPair EC2 APIs to create/import an SSH key pair."
            }

        # Get serverless cache details to find its VPC
        serverless_cache = elasticache_client.describe_serverless_caches(
            ServerlessCacheName=serverless_cache_name
        )['ServerlessCaches'][0]

        # Get cache security groups
        cache_security_groups = serverless_cache['SecurityGroupIds']
        if not cache_security_groups:
            raise ValueError(
                f'No security groups found for serverless cache {serverless_cache_name}'
            )

        # Get cache VPC ID from subnet IDs
        if not serverless_cache.get('SubnetIds'):
            raise ValueError(f'No subnet IDs found for serverless cache {serverless_cache_name}')

        # Get subnet details to find VPC ID
        subnet_response = ec2_client.describe_subnets(SubnetIds=[serverless_cache['SubnetIds'][0]])
        cache_vpc_id = subnet_response['Subnets'][0]['VpcId']

        # Check if serverless cache is in default VPC
        vpcs = ec2_client.describe_vpcs(VpcIds=[cache_vpc_id])['Vpcs']
        cache_vpc = vpcs[0] if vpcs else None
        is_default_vpc = cache_vpc and cache_vpc.get('IsDefault', False)

        # Auto-select subnet if not provided and serverless cache is in default VPC
        if not subnet_id and is_default_vpc:
            # Get default subnets in the default VPC
            subnets = ec2_client.describe_subnets(
                Filters=[
                    {'Name': 'vpc-id', 'Values': [cache_vpc_id]},
                    {'Name': 'default-for-az', 'Values': ['true']},
                ]
            )['Subnets']

            if subnets:
                # Pick the first available default subnet
                subnet_id = subnets[0]['SubnetId']
            else:
                # Fallback to any public subnet in the VPC
                all_subnets = ec2_client.describe_subnets(
                    Filters=[{'Name': 'vpc-id', 'Values': [cache_vpc_id]}]
                )['Subnets']

                for subnet in all_subnets:
                    if subnet.get('MapPublicIpOnLaunch', False):
                        subnet_id = subnet['SubnetId']
                        break

        # Auto-select security group if not provided and serverless cache is in default VPC
        if not security_group_id and is_default_vpc:
            # Get the default security group for the VPC
            security_groups = ec2_client.describe_security_groups(
                Filters=[
                    {'Name': 'vpc-id', 'Values': [cache_vpc_id]},
                    {'Name': 'group-name', 'Values': ['default']},
                ]
            )['SecurityGroups']

            if security_groups:
                security_group_id = security_groups[0]['GroupId']

        # Validate required parameters after auto-selection
        if not subnet_id:
            raise ValueError(
                'subnet_id is required. Either provide a subnet_id or ensure the serverless cache is in the default VPC with default subnets available.'
            )

        if not security_group_id:
            raise ValueError(
                'security_group_id is required. Either provide a security_group_id or ensure the serverless cache is in the default VPC.'
            )

        # Get subnet details and verify it's public
        subnet_response = ec2_client.describe_subnets(SubnetIds=[subnet_id])
        subnet = subnet_response['Subnets'][0]
        subnet_vpc_id = subnet['VpcId']

        # Check VPC compatibility
        if subnet_vpc_id != cache_vpc_id:
            raise ValueError(
                f'Subnet VPC ({subnet_vpc_id}) does not match serverless cache VPC ({cache_vpc_id})'
            )

        # Check if subnet is public by looking for route to internet gateway
        # or if it's a default subnet in the default VPC (which are automatically public)
        route_tables = ec2_client.describe_route_tables(
            Filters=[{'Name': 'association.subnet-id', 'Values': [subnet_id]}]
        )['RouteTables']

        is_public = False
        for rt in route_tables:
            for route in rt.get('Routes', []):
                if route.get('GatewayId', '').startswith('igw-'):
                    is_public = True
                    break
            if is_public:
                break

        # If no explicit route table association, check the main route table for the VPC
        if not is_public and not route_tables:
            main_route_tables = ec2_client.describe_route_tables(
                Filters=[
                    {'Name': 'vpc-id', 'Values': [subnet_vpc_id]},
                    {'Name': 'association.main', 'Values': ['true']},
                ]
            )['RouteTables']

            for rt in main_route_tables:
                for route in rt.get('Routes', []):
                    if route.get('GatewayId', '').startswith('igw-'):
                        is_public = True
                        break
                if is_public:
                    break

        # If not found via route table, check if it's a default subnet in default VPC
        if not is_public:
            # Check if this is the default VPC
            vpcs = ec2_client.describe_vpcs(VpcIds=[subnet_vpc_id])['Vpcs']
            vpc = vpcs[0] if vpcs else None

            if vpc and vpc.get('IsDefault', False):
                # In default VPC, check if this is a default subnet
                # Default subnets have MapPublicIpOnLaunch set to True
                if subnet.get('DefaultForAz', False) or subnet.get('MapPublicIpOnLaunch', False):
                    is_public = True

        if not is_public:
            raise ValueError(
                f'Subnet {subnet_id} is not public (no route to internet gateway found and not a default subnet in default VPC). '
                'The subnet must be public to allow SSH access to the jump host.'
            )

        # Use Amazon Linux 2023 AMI
        images = ec2_client.describe_images(
            Filters=[
                {'Name': 'name', 'Values': ['al2023-ami-2023.*-x86_64']},
                {'Name': 'owner-alias', 'Values': ['amazon']},
            ]
        )
        ami_id = sorted(images['Images'], key=lambda x: x['CreationDate'], reverse=True)[0][
            'ImageId'
        ]

        # Verify and update security group rules for SSH access
        security_group = ec2_client.describe_security_groups(GroupIds=[security_group_id])[
            'SecurityGroups'
        ][0]

        # Check if port 22 is already open
        has_ssh_rule = False
        for rule in security_group.get('IpPermissions', []):
            if (
                rule.get('IpProtocol') == 'tcp'
                and rule.get('FromPort') == 22
                and rule.get('ToPort') == 22
                and any(
                    ip_range.get('CidrIp') == '0.0.0.0/0' for ip_range in rule.get('IpRanges', [])
                )
            ):
                has_ssh_rule = True
                break

        # Add SSH rule if it doesn't exist
        if not has_ssh_rule:
            ec2_client.authorize_security_group_ingress(
                GroupId=security_group_id,
                IpPermissions=[
                    {
                        'IpProtocol': 'tcp',
                        'FromPort': 22,
                        'ToPort': 22,
                        'IpRanges': [
                            {'CidrIp': '0.0.0.0/0', 'Description': 'SSH access from anywhere'}
                        ],
                    }
                ],
            )

        # Launch EC2 instance
        instance = ec2_client.run_instances(
            ImageId=ami_id,
            InstanceType=instance_type,
            KeyName=key_name,
            MaxCount=1,
            MinCount=1,
            NetworkInterfaces=[
                {
                    'SubnetId': subnet_id,
                    'DeviceIndex': 0,
                    'AssociatePublicIpAddress': True,
                    'Groups': [security_group_id],
                }
            ],
            TagSpecifications=[
                {
                    'ResourceType': 'instance',
                    'Tags': [
                        {'Key': 'Name', 'Value': f'ElastiCache-JumpHost-{serverless_cache_name}'}
                    ],
                }
            ],
        )

        # Wait for instance to be running and get its public IP
        waiter = ec2_client.get_waiter('instance_running')
        instance_id = instance['Instances'][0]['InstanceId']
        waiter.wait(InstanceIds=[instance_id])

        instance_info = ec2_client.describe_instances(InstanceIds=[instance_id])
        public_ip = instance_info['Reservations'][0]['Instances'][0]['PublicIpAddress']

        # Configure security groups using common function
        configured, vpc_id, cache_port = await _configure_security_groups(
            serverless_cache_name,
            instance_id,
            ec2_client=ec2_client,
            elasticache_client=elasticache_client,
        )

        return {
            'InstanceId': instance_id,
            'PublicIpAddress': public_ip,
            'InstanceType': instance_type,
            'SubnetId': subnet_id,
            'SecurityGroupId': security_group_id,
            'ServerlessCacheName': serverless_cache_name,
            'SecurityGroupsConfigured': configured,
            'CachePort': cache_port,
            'VpcId': vpc_id,
        }

    except ClientError as e:
        if e.response['Error']['Code'] == 'InvalidKeyPair.NotFound':
            return {
                'error': f"Key pair '{key_name}' not found. Use CreateKeyPair or ImportKeyPair EC2 APIs to create/import an SSH key pair."
            }
        return {'error': str(e)}
    except Exception as e:
        return {'error': str(e)}

async def finch_push_image(
    image: str = Field(
        ..., description='The full image name to push, including the repository URL and tag'
    ),
) -> Result:
    """Push a container image to a repository using finch, replacing the tag with the image hash.

    If the image URL is an ECR repository, it verifies that ECR login cred helper is configured.
    This tool  gets the image hash, creates a new tag using the hash, and pushes the image with
    the hash tag to the repository. If the image URL is an ECR repository, it verifies that
    ECR login is properly configured before proceeding with the push.

    The tool expects the image to be already built and available locally. It uses
    'finch image inspect' to get the hash, 'finch image tag' to create a new tag,
    and 'finch image push' to perform the actual push operation.

    When the server is in read-only mode (which is the default unless --enable-aws-resource-write
    is specified), this tool will return an error when pushing to ECR repositories.

    Returns:
        Result: An object containing:
            - status (str): "success" if the operation succeeded, "error" otherwise
            - message (str): A descriptive message about the result of the operation

    Example response:
        Result(status="success", message="Successfully pushed image 123456789012.dkr.ecr.us-west-2.amazonaws.com/my-repo:abcdef123456 to ECR.")

    """
    logger.info('tool-name: finch_push_image')
    logger.info(f'tool-args: image={image}')

    try:
        finch_install_status = check_finch_installation()
        if finch_install_status['status'] == 'error':
            return Result(**finch_install_status)

        is_ecr = is_ecr_repository(image)
        if is_ecr:
            # Check if AWS resource write is enabled for ECR pushes
            if not enable_aws_resource_write:
                logger.warning(
                    f'Attempt to push image to ECR "{image}" without AWS resource write enabled'
                )
                error_result = format_result(
                    'error', 'Server running in read-only mode, unable to push to ECR repository'
                )
                return Result(**error_result)

            logger.info('ECR repository detected, configuring ECR login')
            config_result, config_changed = configure_ecr()
            if config_result['status'] == 'error':
                return Result(**config_result)
            if config_changed:
                logger.info('ECR configuration changed, restarting VM')
                stop_vm(force=True)

        vm_status = ensure_vm_running()
        if vm_status['status'] == 'error':
            return Result(**vm_status)

        result = push_image(image)
        return Result(**result)
    except Exception as e:
        error_result = format_result('error', f'Error pushing image: {str(e)}')
        return Result(**error_result)

