def list_views() -> dict:
    """
    List all pre-built cost views available to your team.

    These are ready-to-run reports anyone on the team can call by name using get_view().
    Useful to paste into a Claude Project system prompt so teammates know what is available.

    Examples:
        - "What views are available?"
        - "Show me the list of shared cost reports"
    """
    return {
        "views": [
            {"id": k, "name": v["name"], "description": v["description"]}
            for k, v in _srv._VIEWS.items()
        ],
        "usage": (
            "Call get_view(view='<id>') to run any view. "
            "Some views accept extra args: by_tag needs tag_key, "
            "dod/daily_trend accept a days parameter."
        ),
        "tip": (
            "Add 'Use list_views() to show available cost reports' to your Claude Project "
            "instructions so every teammate knows what to ask for."
        ),
    }

async def get_view(
    view: str,
    tag_key: str | None = None,
    tag_value: str | None = None,
    provider: str | None = None,
    days: int | None = None,
) -> dict:
    """
    Run a pre-built cost view by name. These are standard reports your whole team can share.

    Args:
        view:      View ID from list_views(). Required.
        tag_key:   Tag key to group by (required for 'by_tag' view, e.g. 'team', 'env').
        tag_value: Optional filter to a single tag value within by_tag.
        provider:  Optional provider filter (aws, azure, gcp, datadog, etc.).
        days:      Override the default lookback window for time-series views.

    Examples:
        - "Show me the month over month view"
        - "Run the by_tag view for the team tag"
        - "Get the anomalies view for AWS"
        - "What does the top_spenders view show?"
        - "Run daily_trend for the last 7 days"

    Tip: Share these view names in your team's Slack or Claude Project so everyone
         runs the same report instead of writing queries from scratch each time.
    """
    if view not in _srv._VIEWS:
        return {
            "error": f"Unknown view '{view}'.",
            "available_views": list(_srv._VIEWS.keys()),
            "tip": "Call list_views() to see all available views with descriptions.",
        }

    meta = _srv._VIEWS[view]
    today = _srv.date.today()

    # ── mom ──────────────────────────────────────────────────────────────────
    if view == "mom":
        first_this, this_end, first_last, last_last, on_the_first = _month_pair(today)

        active = await _srv._active()
        if provider:
            active = {k: v for k, v in active.items() if k == provider}

        this_total, this_by, _  = await _srv._gather_costs(active, first_this, this_end)
        last_total, last_by, _  = await _srv._gather_costs(active, first_last, last_last)

        rows = []
        all_providers = sorted(set(list(this_by.keys()) + list(last_by.keys())))
        for p in all_providers:
            t = this_by.get(p, {}).get("total_usd", 0.0)
            l = last_by.get(p, {}).get("total_usd", 0.0)
            pct = ((t - l) / l * 100) if l else None
            rows.append({
                "provider": p,
                "this_month": _srv._fmt_usd(t),
                "last_month": _srv._fmt_usd(l),
                "change_pct": f"{pct:+.1f}%" if pct is not None else "n/a",
            })

        total_pct = ((this_total - last_total) / last_total * 100) if last_total else None
        return {
            "view": meta["name"],
            "this_month": {"period": f"{first_this} to {this_end}", "total": _srv._fmt_usd(this_total)},
            "last_month": {"period": f"{first_last} to {last_last}", "total": _srv._fmt_usd(last_total)},
            "total_change": f"{total_pct:+.1f}%" if total_pct is not None else "n/a",
            "by_provider": rows,
            # The keys stay this_month/last_month for consumers, so on the 1st say
            # plainly what they hold: the two closed months, not a $0 current one.
            **({"note": "It is the 1st, so there is no month-to-date yet. "
                        "'this_month' is the month that just closed and 'last_month' "
                        "is the one before it."} if on_the_first else {}),
        }

    # ── wow ──────────────────────────────────────────────────────────────────
    if view == "wow":
        this_start = today - _srv.timedelta(days=7)
        last_start = today - _srv.timedelta(days=14)
        last_end   = today - _srv.timedelta(days=8)

        active = await _srv._active()
        if provider:
            active = {k: v for k, v in active.items() if k == provider}

        this_total, this_by, _  = await _srv._gather_costs(active, this_start, today, granularity="DAILY")
        last_total, last_by, _  = await _srv._gather_costs(active, last_start, last_end, granularity="DAILY")

        pct = ((this_total - last_total) / last_total * 100) if last_total else None
        return {
            "view": meta["name"],
            "this_week": {"period": f"{this_start} to {today}", "total": _srv._fmt_usd(this_total)},
            "last_week": {"period": f"{last_start} to {last_end}", "total": _srv._fmt_usd(last_total)},
            "change_pct": f"{pct:+.1f}%" if pct is not None else "n/a",
            "by_provider": [
                {
                    "provider": p,
                    "this_week": _srv._fmt_usd(this_by.get(p, {}).get("total_usd", 0)),
                    "last_week": _srv._fmt_usd(last_by.get(p, {}).get("total_usd", 0)),
                }
                for p in sorted(set(list(this_by.keys()) + list(last_by.keys())))
            ],
        }

    # ── dod / daily_trend ────────────────────────────────────────────────────
    if view in ("dod", "daily_trend"):
        n = days or (14 if view == "dod" else 30)
        start = today - _srv.timedelta(days=n)

        active = await _srv._active()
        if provider:
            active = {k: v for k, v in active.items() if k == provider}

        _, _, grand_by_service = await _srv._gather_costs(active, start, today, granularity="DAILY")

        # Aggregate per-connector daily data directly
        daily: dict[str, float] = {}

        async def _one_daily(name: str, connector: _srv.Any):
            try:
                return await _srv._fetch_costs_cached(name, connector, start, today, granularity="DAILY")
            except Exception:
                return None

        for summary in await _srv.asyncio.gather(*[_one_daily(n, c) for n, c in active.items()]):
            if summary is None:
                continue
            # daily_breakdown is a dict[str, float] keyed by date string if available
            breakdown = getattr(summary, "daily_breakdown", None) or {}
            for day_str, amt in breakdown.items():
                daily[day_str] = daily.get(day_str, 0.0) + amt

        rows = [{"date": d, "spend": _srv._fmt_usd(v)} for d, v in sorted(daily.items())]
        return {
            "view": meta["name"],
            "period": f"{start} to {today}",
            "daily_spend": rows if rows else {"note": "Daily granularity not available for configured connectors."},
        }

    # ── by_service ───────────────────────────────────────────────────────────
    if view == "by_service":
        first_this, this_end, first_last, last_last, on_the_first = _month_pair(today)

        active = await _srv._active()
        if provider:
            active = {k: v for k, v in active.items() if k == provider}

        _, _, this_svc = await _srv._gather_costs(active, first_this, this_end)
        _, _, last_svc = await _srv._gather_costs(active, first_last, last_last)

        rows = []
        for svc, amt in sorted(this_svc.items(), key=lambda x: -x[1])[:20]:
            last_amt = last_svc.get(svc, 0.0)
            pct = ((amt - last_amt) / last_amt * 100) if last_amt else None
            rows.append({
                "service": svc,
                "this_month": _srv._fmt_usd(amt),
                "last_month": _srv._fmt_usd(last_amt),
                "change": f"{pct:+.1f}%" if pct is not None else "new",
            })

        return {
            "view": meta["name"],
            "period": f"{first_this} to {this_end}",
            "services": rows,
            **({"note": "It is the 1st, so there is no month-to-date yet. "
                        "'this_month' is the month that just closed and 'last_month' "
                        "is the one before it."} if on_the_first else {}),
        }

    # ── by_tag ───────────────────────────────────────────────────────────────
    if view == "by_tag":
        if not tag_key:
            return {
                "error": "tag_key is required for the by_tag view.",
                "example": "get_view(view='by_tag', tag_key='team')",
            }
        start, end = _srv._default_dates()
        active = await _srv._active()
        if provider:
            active = {k: v for k, v in active.items() if k == provider}

        tag_totals: dict[str, float] = {}

        async def _one_tags(connector: _srv.Any):
            try:
                if hasattr(connector, "get_costs_by_tag"):
                    return await connector.get_costs_by_tag(start, end, tag_key=tag_key)
            except Exception:
                pass
            return {}

        for result in await _srv.asyncio.gather(*[_one_tags(c) for c in active.values()]):
            for tag_val, amt in result.items():
                if tag_value and tag_val != tag_value:
                    continue
                tag_totals[tag_val] = tag_totals.get(tag_val, 0.0) + amt

        if not tag_totals:
            return {
                "view": meta["name"],
                "tag_key": tag_key,
                "note": (
                    f"No cost data found for tag '{tag_key}'. "
                    "Make sure resources are tagged and Cost Explorer tag activation is enabled."
                ),
            }

        all_rows = [
            {"tag_value": k, "spend": _srv._fmt_usd(v)}
            for k, v in sorted(tag_totals.items(), key=lambda x: -x[1])
        ]
        rows, omitted = _srv.fit_to_budget(all_rows)
        return {
            "view": meta["name"],
            "tag_key": tag_key,
            "period": f"{start} to {end}",
            "by_tag": rows,
            **({"by_tag_truncated": True, "hint": f"Showing {len(rows)} of {len(all_rows)} tag values by spend to stay within token budget."} if omitted else {}),
            "total": _srv._fmt_usd(sum(tag_totals.values())),
        }

    # ── by_team ──────────────────────────────────────────────────────────────
    if view == "by_team":
        start, end = _srv._default_dates()
        try:
            from ..attribution.engine import AttributionEngine
            engine = AttributionEngine()
            result = await engine.attribute(start, end)
            all_rows = [
                {"team": t, "spend": _srv._fmt_usd(v)}
                for t, v in sorted(result.items(), key=lambda x: -x[1])
            ]
            rows, omitted = _srv.fit_to_budget(all_rows)
            return {
                "view": meta["name"],
                "period": f"{start} to {end}",
                "by_team": rows,
                **({"by_team_truncated": True, "hint": f"Showing {len(rows)} of {len(all_rows)} teams by spend to stay within token budget."} if omitted else {}),
                "total": _srv._fmt_usd(sum(result.values())),
            }
        except Exception as e:
            return {"view": meta["name"], "error": str(e)}

    # ── top_spenders ─────────────────────────────────────────────────────────
    if view == "top_spenders":
        start, end = _srv._default_dates()
        active = await _srv._active()
        if provider:
            active = {k: v for k, v in active.items() if k == provider}

        _, _, grand_svc = await _srv._gather_costs(active, start, end)
        rows = [
            {"service": svc, "spend": _srv._fmt_usd(amt)}
            for svc, amt in sorted(grand_svc.items(), key=lambda x: -x[1])[:10]
        ]
        return {
            "view": meta["name"],
            "period": f"{start} to {end}",
            "top_10": rows,
        }

    # ── anomalies ────────────────────────────────────────────────────────────
    if view == "anomalies":
        return await _srv.get_anomalies(provider=provider)

    # ── rightsizing ──────────────────────────────────────────────────────────
    if view == "rightsizing":
        return await _srv.get_rightsizing_recommendations()

    # ── waste ────────────────────────────────────────────────────────────────
    if view == "waste":
        # Routed through the registered tool, the same way the rightsizing view
        # above is. This used to call `analyzers.waste.scan_waste`, which does
        # not exist: that module exposes per-detector check_* functions and no
        # aggregate. The except swallowed the ImportError into an error string,
        # so this view has answered `{"error": "cannot import name 'scan_waste'"}`
        # to every user who asked for it, and looked like a runtime hiccup.
        return await _srv.scan_waste_patterns()

    # ── saas ─────────────────────────────────────────────────────────────────
    if view == "saas":
        start, end = _srv._default_dates()
        active = await _srv._active(subset=_srv.SAAS_CONNECTORS)
        if provider:
            active = {k: v for k, v in active.items() if k == provider}

        grand_total, by_provider, _ = await _srv._gather_costs(active, start, end)
        return {
            "view": meta["name"],
            "period": f"{start} to {end}",
            "total": _srv._fmt_usd(grand_total),
            "by_provider": {
                k: _srv._fmt_usd(v.get("total_usd", 0)) for k, v in by_provider.items()
            },
        }

    return {"error": f"View '{view}' is defined but not yet implemented."}

async def what_can_nable_do(detailed: bool = False) -> str:
    """
    Show everything nable can do, tailored to what you've connected.

    Call this when the user asks "what can you do?", "what features do you have?",
    "what should I try first?", "show me what's available", or "help". Always call
    it right after a user connects their first account, so they see what just
    became possible. Pass detailed=True to also list the underlying tool names.
    Args:
        detailed: True returns the full capability list instead of the summary.

    Examples:
        - "What can nable do?"
        - "List your capabilities"

    """
    from ..demo_data import capabilities_text, is_demo
    if is_demo():
        return capabilities_text(detailed=detailed)

    connected: set[str] = set()

    # Cloud + SaaS connectors live in the class registries.
    for pool in (_srv.CLOUD_CONNECTORS, _srv.SAAS_CONNECTORS):
        for name, connector in pool.items():
            try:
                if await connector.is_configured():
                    connected.add(name)
            except Exception:
                pass

    # LLM / AI providers are module-level detectors (where AI-native accounts
    # actually spend: direct APIs, gateways, and GPU infra).
    from ..connectors.saas import (
        openai_usage, anthropic_usage, vertex_costs, openrouter, litellm, gpu_infra,
    )
    for name, check in {
        "openai": openai_usage.is_configured,
        "anthropic": anthropic_usage.is_configured,
        "vertex": vertex_costs.is_configured,
        "openrouter": openrouter.is_configured,
        "litellm": litellm.is_configured,
    }.items():
        try:
            if await check():
                connected.add(name)
        except Exception:
            pass
    for name, check in {
        "modal": gpu_infra.modal_configured,
        "together": gpu_infra.together_configured,
        "replicate": gpu_infra.replicate_configured,
    }.items():
        try:
            if check():
                connected.add(name)
        except Exception:
            pass

    from ..capabilities import has_llm as _has_llm, render_capabilities
    if _has_llm(connected):
        connected.add("llm")

    # Best-effort Kubernetes detection: a reachable kubeconfig (no agent needed).
    try:
        import os
        from pathlib import Path
        if os.environ.get("KUBECONFIG") or (Path.home() / ".kube" / "config").exists():
            connected.add("kubernetes")
    except Exception:
        pass

    try:
        plan = _srv.get_status().mode
    except Exception:
        plan = "free"
    return render_capabilities(connected, plan=plan, detailed=detailed)

async def send_digest_now() -> dict:
    """
    Send a cost digest to Slack and/or Teams right now. This install sends
    digests only when asked; sending them on a schedule is nable Cloud.

    Examples:
        - "Send the daily cost digest to Slack"
        - "Push the current cost summary to Teams"
    """
    if (err := _srv.require_pro("alerts")):
        return err
    if err := _srv.require_role("analyst"):
        return err

    from ..notifications import slack, teams
    if not slack.is_configured() and not teams.is_configured():
        return {"sent": False,
                "message": "No notification channels configured. Run 'uvx nable slack' or "
                           "'uvx nable teams' in a terminal."}
    from ..scheduler.jobs import has_snapshot_on, run_digest_now
    yesterday = _srv.date.today() - _srv.timedelta(days=1)
    if not has_snapshot_on(yesterday):
        # The digest reports yesterday from local snapshots; with none it would
        # post "$0" as if that were the bill.
        return {"sent": False,
                "message": (f"No cost data for {yesterday.isoformat()} yet, so no digest was "
                            "posted. Take a cost snapshot (take_snapshot_now), then ask again.")}
    sent = await run_digest_now()
    return {
        "sent": sent,
        "message": "Digest sent." if sent else (
            "Slack or Teams did not accept the digest. Check the webhook or token with "
            "'uvx nable slack' or 'uvx nable teams'."),
    }

def check_notification_config() -> dict:
    """
    Check which notification channels (Slack, Teams) are configured and active,
    returning each channel's status and what is missing when one is not set up.
    Use it to verify where anomaly alerts and digests will be delivered before
    relying on them.

    Examples:
        - "Is Slack configured for alerts?"
        - "Where are cost alerts being sent?"
        - "Why did no alert reach Teams?"
    """
    from ..notifications import slack, teams

    result = {
        "slack": {
            "configured": slack.is_configured(),
            "method": "webhook" if _srv.os.environ.get("SLACK_WEBHOOK_URL") else "bot_token" if _srv.os.environ.get("SLACK_BOT_TOKEN") else "none",
            "channel": _srv.os.environ.get("SLACK_CHANNEL", "#finops-alerts"),
        },
        "teams": {
            "configured": teams.is_configured(),
        },
    }
    if _scheduler_installed():
        result["delivery"] = "scheduled"
        result["schedule"] = {
            "snapshot": _srv.os.environ.get("FINOPS_SNAPSHOT_CRON", "0 1 * * * (01:00 UTC)"),
            "anomaly_check": _srv.os.environ.get("FINOPS_ANOMALY_CRON", "0 2 * * * (02:00 UTC)"),
            "daily_digest": _srv.os.environ.get("FINOPS_DIGEST_CRON", "0 9 * * * (09:00 UTC)"),
        }
    else:
        # A schedule block here read as "digests go out at 09:00" on an install
        # that runs nothing on a timer.
        from ..license import DELIVERY_NOTE
        result["delivery"] = "on_request"
        result["note"] = DELIVERY_NOTE
    return result

async def export_cost_report(
    title: str | None = None,
    sections: list[str] | None = None,
    formats: list[str] | None = None,
    start_date: str | None = None,
    end_date: str | None = None,
    open_file: bool = True,
) -> dict:
    """
    Export a cost report as HTML (printable to PDF) and/or CSV. Saved to
    ~/.finops/exports/. No Claude Desktop required to open.

    Args:
        title: Report title. Defaults to "Cloud Cost Report <period>".
        sections: Sections to include: cost_summary, services, anomalies,
                  rightsizing, savings, budgets. Default: all.
        formats: ["html", "csv"]. Default: both.
        start_date: ISO date. Defaults to 30 days ago.
        end_date: ISO date. Defaults to today.
        open_file: Open HTML in browser after export (default True).

    Examples:
        - "Export a cost report for this month"
        - "Give me a CSV export of anomalies and rightsizing"
        - "Make a weekly cost report for the team"
    """
    from datetime import date as _date, timedelta
    try:
        sd = _date.fromisoformat(start_date) if start_date else _date.today() - timedelta(days=30)
        ed = _date.fromisoformat(end_date) if end_date else _date.today()
    except ValueError:
        return {"error": "start_date and end_date must be ISO format YYYY-MM-DD."}
    period_start = sd.isoformat()
    period_end = ed.isoformat()

    if title is None:
        title = f"Cloud Cost Report, {period_start} to {period_end}"

    all_sections = ["cost_summary", "services", "anomalies", "rightsizing", "savings", "budgets"]
    wanted = set(sections or all_sections)
    fmt_list = formats or ["html", "csv"]

    collected: dict = {}

    # Gather data for each requested section (errors are non-fatal)
    if "cost_summary" in wanted:
        try:
            collected["cost_summary"] = await _srv.get_cost_summary(
                start_date=period_start, end_date=period_end
            )
        except Exception:
            pass

    if "services" in wanted:
        try:
            collected["services"] = await _srv.get_costs_by_service(
                start_date=period_start, end_date=period_end
            )
        except Exception:
            pass

    if "anomalies" in wanted:
        try:
            collected["anomalies"] = await _srv.get_anomalies(limit=50)
        except Exception:
            pass

    if "rightsizing" in wanted:
        try:
            collected["rightsizing"] = await _srv.get_rightsizing_recommendations()
        except Exception:
            pass

    if "savings" in wanted:
        try:
            from ..recommendations.savings_tracker import get_summary, list_recommendations
            summary = get_summary()
            summary["recommendations"] = list_recommendations(limit=100)
            collected["savings"] = summary
        except Exception:
            pass

    if "budgets" in wanted:
        try:
            collected["budgets"] = await _srv.list_budgets()
        except Exception:
            pass

    if not collected:
        return {
            "error": "No data available to export. Make sure at least one provider is configured.",
        }

    # Write files
    from ..reporting.exporter import write_report
    output = write_report(
        title=title,
        period_start=period_start,
        period_end=period_end,
        sections=collected,
        formats=fmt_list,
    )

    # Open HTML in browser if requested
    if open_file and "html" in output:
        from ..open_file import open_local_file
        open_local_file(output["html"])

    from ..reporting.exporter import cost_data_unread
    cost_sections = {k: collected[k] for k in ("cost_summary", "services") if k in collected}
    not_read = {k: why for k, v in cost_sections.items() if (why := cost_data_unread(v))}

    result = {
        "title": title,
        "period": f"{period_start} to {period_end}",
        "sections_included": list(collected.keys()),
        "files": output,
        "message": (
            f"Report generated with {len(collected)} section(s). "
            + (f"HTML: {output.get('html', '')}. " if "html" in output else "")
            + (f"CSVs: {output.get('csv_dir', '')}." if "csv_dir" in output else "")
        ),
    }
    if cost_sections:
        result["cost_data_read"] = len(not_read) < len(cost_sections)
    if not_read:
        result["sections_not_read"] = not_read
        if not result.get("cost_data_read", True):
            result["message"] = (
                "No cost data was read, so the report carries no spend figures. "
                f"{next(iter(not_read.values()))} This is not a finding of zero spend. "
                + result["message"])
    if "html" in output:
        result["tip"] = "Open the HTML file in your browser, then use File → Print → Save as PDF to create a PDF."

    return result

def fetch_invoice_emails() -> dict:
    """
    Fetch unread invoice emails from the configured IMAP mailbox, extract
    amounts, and store them as cost entries. Solves the billing API gap for
    vendors like PagerDuty, New Relic, and GitHub Enterprise.

    Examples:
        - "Parse our billing inbox for new invoices"
        - "How much did PagerDuty charge us this month? (after forwarding invoice)"
        - "Fetch and store any new vendor invoices"
    """
    try:
        from ..connectors.invoice.parser import fetch_and_store_invoices
        stored = fetch_and_store_invoices()
        if not stored:
            host = _srv.os.environ.get("FINOPS_INVOICE_IMAP_HOST", "")
            if not host:
                return {
                    "invoices_stored": 0,
                    "message": "No IMAP mailbox configured. Set FINOPS_INVOICE_IMAP_HOST (and FINOPS_INVOICE_IMAP_USER, FINOPS_INVOICE_IMAP_PASSWORD) in your environment, then restart.",
                }
        return {
            "invoices_stored": len(stored),
            "invoices": stored,
        }
    except Exception as e:
        return {"error": str(e)}

def send_weekly_digest_now() -> dict:
    """
    Immediately send the weekly email digest to the configured recipient.
    Includes spend summary, anomalies, and top rightsizing recommendations.
    Works without Claude, pure standalone email.

    Examples:
        - "Send the weekly cost digest now"
        - "Trigger the weekly email report"
    """
    if (err := _srv.require_pro("alerts")):
        return err
    if err := _srv.require_pro("scheduled_email_digests"):
        return err

    try:
        from ..scheduler.jobs import job_weekly_email_digest
        result = job_weekly_email_digest() or {}
    except Exception as e:
        return {"sent": False, "error": str(e)}
    if result.get("sent"):
        return {"sent": True, "recipient": result.get("recipient", ""),
                "message": f"Weekly digest emailed to {result.get('recipient', '')}."}
    out = {"sent": False, "error": result.get("error") or "The digest was not sent."}
    if result.get("missing"):
        out["missing"] = result["missing"]
        out["note"] = ("Set these in the environment nable runs in (the MCP server's env "
                       "block, or your shell for the CLI), then ask again.")
    return out

