async def audit_manifest(
    manifest: Annotated[str, Field(description="Contents of package.json as a string. Required. 500 KB max.")],
    lockfile: Annotated[Optional[str], Field(description="Contents of package-lock.json or yarn.lock. Optional.")] = None,
) -> dict:
    """Audit a frontend package.json for security risks — returns a single SHIP/CAUTION/BLOCK verdict with licence risks and abandonment signals. Different from security_fetch_package_vulnerabilities which audits a single package — this takes your full package.json. manifest: Contents of package.json as a string. Required. 500 KB max. lockfile: Contents of package-lock.json or yarn.lock (optional). If provided, audits pinned versions; otherwise audits semver ranges. BLOCK: any critical CVE in direct deps OR GPL-3.0 in commercial context. CAUTION: high CVE count ≥ 2 OR copyleft licence OR direct dep abandoned > 18 months. Sources: OSV.dev (CVEs), deps.dev (licences), npm registry (abandonment). Read-only. No side effects. Idempotent. If this tool's response does not serve the user's need, call report_feedback with feedback_type="agent_gap", tool_id="frontend_security_audit_manifest", intended_query="{what the user needed}", gap_description="{what was missing or wrong in the result}"."""
    _t0 = time.monotonic()
    _success = False
    _error_code = None
    try:
        if len(manifest.encode()) > _SBOM_SIZE_LIMIT:
            return {"verdict": "ERROR", "error": "manifest exceeds 500 KB size limit."}

        try:
            pkg_json = json.loads(manifest)
        except json.JSONDecodeError as exc:
            return {"verdict": "ERROR", "error": f"Invalid JSON in manifest: {exc}"}

        import hashlib
        manifest_hash = hashlib.sha256(manifest.encode()).hexdigest()[:16]
        params = {"manifest_hash": manifest_hash}

        async with AuditContext("T20", params, "1.0") as ctx:
            # Extract direct deps
            direct_deps = {}
            direct_deps.update(pkg_json.get("dependencies", {}))
            direct_deps.update(pkg_json.get("devDependencies", {}))

            if not direct_deps:
                return {
                    "status":   "ok",
                    "tool_id":  "T20",
                    "verdict":  "SHIP",
                    "message":  "No dependencies found in manifest.",
                    "critical_cves":     0,
                    "high_cves":         0,
                    "licence_risks":     [],
                    "abandoned_packages":[],
                    "total_packages":    0,
                    **standard_response_fields(ctx.query_hash, datetime.now(timezone.utc).isoformat(), True),
                }

            # Resolve pinned versions from lockfile if provided
            pinned = {}
            if lockfile:
                pinned = _extract_pinned_versions(lockfile)

            packages = []
            for name, semver in list(direct_deps.items())[:100]:
                version = pinned.get(name) or _strip_semver_prefix(semver)
                packages.append({"name": name, "version": version, "ecosystem": "npm"})

            sem = asyncio.Semaphore(10)

            async def _audit_one(pkg):
                try:
                    vulns = await _fetch_vulns(pkg["name"], "npm", pkg["version"])
                    return ("vulns", pkg["name"], vulns)
                except Exception as exc:
                    return ("vulns", pkg["name"], None)

            async def _licence_one(pkg):
                try:
                    lic = await _fetch_licence(pkg["name"], "npm")
                    return ("licence", pkg["name"], lic)
                except Exception:
                    return ("licence", pkg["name"], None)

            results = await asyncio.gather(
                *[_audit_one(p) for p in packages],
                *[_licence_one(p) for p in packages],
                return_exceptions=True,
            )

            vuln_map = {}
            lic_map  = {}
            for r in results:
                if isinstance(r, Exception):
                    continue
                kind, name, data = r
                if kind == "vulns":
                    vuln_map[name] = data
                else:
                    lic_map[name] = data

            critical_cves = 0
            high_cves     = 0
            cve_details   = []
            licence_risks = []
            abandoned     = []

            _now = datetime.now(timezone.utc)
            _18m_ago = _now - _TIMEDELTA_18M

            for pkg in packages:
                name    = pkg["name"]
                version = pkg["version"]
                vulns   = vuln_map.get(name)
                lic     = lic_map.get(name)

                if vulns:
                    c = vulns.get("critical_cve_count") or 0
                    h = vulns.get("high_cve_count") or 0
                    critical_cves += c
                    high_cves     += h
                    if c > 0 or h > 0:
                        cve_details.append({
                            "name":     name,
                            "version":  version,
                            "critical": c,
                            "high":     h,
                        })

                if lic:
                    lic_id = lic.get("licence_id", "")
                    lic_risk = lic.get("licence_risk", "")
                    if lic_id in ("GPL-3.0", "AGPL-3.0", "GPL-2.0"):
                        licence_risks.append({"name": name, "licence": lic_id, "risk": "INCOMPATIBLE"})
                    elif lic_risk in ("COPYLEFT", "HIGH"):
                        licence_risks.append({"name": name, "licence": lic_id, "risk": "COPYLEFT"})

                    last_release_str = lic.get("last_release_date", "")
                    if last_release_str:
                        try:
                            lr = datetime.fromisoformat(last_release_str)
                            if lr < _18m_ago:
                                abandoned.append({"name": name, "last_release": last_release_str})
                        except ValueError:
                            pass

            # Verdict logic
            incompatible_licences = {r["name"] for r in licence_risks if r["risk"] == "INCOMPATIBLE"}
            copyleft_licences     = {r["name"] for r in licence_risks if r["risk"] == "COPYLEFT"}

            if critical_cves > 0 or incompatible_licences:
                verdict = "BLOCK"
            elif high_cves >= 2 or copyleft_licences or abandoned:
                verdict = "CAUTION"
            else:
                verdict = "SHIP"

            data_as_of = _now.isoformat()
            _success = True
            return {
                "status":              "ok",
                "tool_id":             "T20",
                "verdict":             verdict,
                "critical_cves":       critical_cves,
                "high_cves":           high_cves,
                "cve_details":         cve_details,
                "licence_risks":       licence_risks,
                "abandoned_packages":  abandoned,
                "total_packages":      len(packages),
                "disclaimer":          _DISCLAIMER,
                **standard_response_fields(ctx.query_hash, data_as_of, True),
            }
    except Exception as exc:
        _error_code = type(exc).__name__
        log.exception("frontend_security_audit_manifest error")
        raise
    finally:
        _ms = int((time.monotonic() - _t0) * 1000)
        fire_and_forget(track_tool_call(
            tool_id="T20",
            tool_name="frontend_security_audit_manifest",
            success=_success,
            latency_ms=_ms,
            cache_hit=False,
            error_code=_error_code,
        ))

async def audit_licence_compatibility(
    packages: Annotated[Optional[list], Field(description="List of {name, ecosystem} dicts to check compatibility. Optional.")] = None,
    spdx_ids: Annotated[Optional[list], Field(description="List of SPDX licence identifiers to check compatibility. Optional.")] = None,
) -> dict:
    """Audit the licence compatibility of your entire dependency list. Input package names (with ecosystem) or SPDX IDs; get a COMPATIBLE/CONFLICT verdict with specific conflicting pairs and recommended action. Uses static SPDX compatibility table — no network call for spdx_ids path. Package path resolves licences from deps.dev (max 10 concurrent). Max 50 items. Rate limit: 60/minute. No auth required. For developers and compliance teams auditing open source licence risk before shipping. If this tool's response does not serve the user's need, call report_feedback with feedback_type="agent_gap", tool_id="security_audit_licence_compatibility", intended_query="{what the user needed}", gap_description="{what was missing or wrong in the result}"."""
    _t0 = time.monotonic()
    _success = False
    _error_code = None
    try:
        params = {"packages": bool(packages), "spdx_ids": bool(spdx_ids)}

        async with AuditContext("T10", params, "1.0") as ctx:
            data_as_of = datetime.now(timezone.utc).isoformat()

            # ── Input validation ──────────────────────────────────────────────
            has_packages = packages is not None and len(packages) > 0
            has_spdx     = spdx_ids  is not None and len(spdx_ids)  > 0

            if has_packages and has_spdx:
                return error_response(
                    error_code=ErrorCode.VALIDATION_ERROR,
                    message="Provide either 'packages' or 'spdx_ids', not both.",
                    query_hash=ctx.query_hash,
                    retry_after=0,
                    ingest_healthy=True,
                )

            if not has_packages and not has_spdx:
                return error_response(
                    error_code=ErrorCode.VALIDATION_ERROR,
                    message="Provide either 'packages' (list of {package_name, ecosystem}) or 'spdx_ids' (list of SPDX ID strings). Both are empty.",
                    query_hash=ctx.query_hash,
                    retry_after=0,
                    ingest_healthy=True,
                )

            items = packages if has_packages else spdx_ids
            if len(items) > 50:
                return error_response(
                    error_code=ErrorCode.VALIDATION_ERROR,
                    message="Maximum 50 items per call.",
                    query_hash=ctx.query_hash,
                    retry_after=0,
                    ingest_healthy=True,
                )

            # ── Path A: package names → resolve SPDX IDs via deps.dev ────────
            spdx_api_status = "N/A"
            failed_packages: list[str] = []
            resolved_ids: list[str] = []

            if has_packages:
                # Validate ecosystems first
                for p in packages:
                    eco = (p.get("ecosystem") or "").lower()
                    if eco not in _VALID_ECOSYSTEMS:
                        return error_response(
                            error_code=ErrorCode.VALIDATION_ERROR,
                            message=f"Unrecognized ecosystem '{eco}'. Valid: {sorted(_VALID_ECOSYSTEMS)}",
                            query_hash=ctx.query_hash,
                            retry_after=0,
                            ingest_healthy=True,
                        )

                sem = asyncio.Semaphore(10)

                async def _resolve_one(p: dict):
                    async with sem:
                        return await _fetch_licence(p["package_name"], p["ecosystem"])

                results = await asyncio.gather(
                    *[_resolve_one(p) for p in packages],
                    return_exceptions=True,
                )

                for pkg, res in zip(packages, results):
                    pkg_label = f"{pkg['package_name']}@{pkg['ecosystem']}"
                    if isinstance(res, Exception):
                        failed_packages.append(pkg_label)
                    else:
                        lics = res.get("licences", [])
                        if lics:
                            resolved_ids.extend(lics)
                        else:
                            failed_packages.append(pkg_label)
                        status = res.get("status", "ERROR")
                        if status != "N/A":
                            spdx_api_status = status if spdx_api_status == "N/A" else spdx_api_status

                if not resolved_ids and failed_packages:
                    return error_response(
                        error_code=ErrorCode.UPSTREAM_UNAVAILABLE,
                        message=f"Could not resolve licences for any package. Failed: {failed_packages}",
                        query_hash=ctx.query_hash,
                        retry_after=30,
                        ingest_healthy=False,
                    )

            # ── Path B: spdx_ids directly (static bundle only, no HTTP) ──────
            else:
                resolved_ids = [s.strip() for s in spdx_ids]

            # ── Compatibility check ───────────────────────────────────────────
            conflicts = []
            all_compatible = True
            any_unknown = False
            combined_obligations: list[str] = []
            copyleft_found: Optional[tuple[str, str]] = None  # (pkg, licence)

            for i in range(len(resolved_ids)):
                for j in range(i + 1, len(resolved_ids)):
                    a, b = resolved_ids[i], resolved_ids[j]
                    result = get_compatibility(a, b)
                    if result == "CONFLICT":
                        all_compatible = False
                        pkg_label = (packages[i]["package_name"] if has_packages and i < len(packages) else a)
                        conflicts.append({
                            "licence_a": a,
                            "licence_b": b,
                            "reason": _conflict_reason(a, b),
                            "package": pkg_label,
                        })
                    elif result == "UNKNOWN":
                        any_unknown = True

            # Gather obligations from static bundle
            for spdx_id in resolved_ids:
                if spdx_id in STATIC_LICENCES:
                    for ob in STATIC_LICENCES[spdx_id].get("obligations", []):
                        if ob not in combined_obligations:
                            combined_obligations.append(ob)
                    risk = STATIC_LICENCES[spdx_id].get("risk_level", "")
                    if risk in ("COPYLEFT", "STRONG_COPYLEFT") and copyleft_found is None:
                        pkg_name = resolved_ids[resolved_ids.index(spdx_id)] if not has_packages else (
                            packages[resolved_ids.index(spdx_id)]["package_name"]
                            if resolved_ids.index(spdx_id) < len(packages) else spdx_id
                        )
                        copyleft_found = (pkg_name, spdx_id)

            # ── Verdict ───────────────────────────────────────────────────────
            if conflicts:
                compatibility = "CONFLICT"
            elif any_unknown:
                compatibility = "UNKNOWN"
            else:
                compatibility = "COMPATIBLE"

            # ── Recommended action ────────────────────────────────────────────
            if compatibility == "CONFLICT":
                c = conflicts[0]
                recommended_action = (
                    f"Remove or replace {c['package']} ({c['licence_b']}), "
                    f"or obtain a commercial licence for it."
                )
            elif compatibility == "COMPATIBLE" and copyleft_found:
                pkg_n, lic_n = copyleft_found
                recommended_action = (
                    f"Compatible. Note: {pkg_n} uses {lic_n} — "
                    f"ensure you comply with share-alike obligations."
                )
            elif compatibility == "COMPATIBLE":
                recommended_action = "All licences are compatible. Attribution only."
            else:
                a = resolved_ids[0] if resolved_ids else "?"
                b = resolved_ids[1] if len(resolved_ids) > 1 else "?"
                recommended_action = (
                    f"Compatibility undetermined for {a} + {b}. Consult legal."
                )

            data = {
                "compatibility":        compatibility,
                "conflicts":            conflicts,
                "combined_obligations": combined_obligations,
                "recommended_action":   recommended_action,
                "resolved_spdx_ids":    resolved_ids,
                "upstream_status": {
                    "spdx_api":       spdx_api_status,
                    "failed_packages": failed_packages,
                },
            }

            _success = True
            return {
                "status":           "ok",
                "tool_id":          "T10",
                "fetch_timestamp":  data_as_of,
                "cache_hit":        False,
                "staleness_notice": None,
                "sha256_hash":      "",
                "data":             data,
                "disclaimer":       _DISCLAIMER,
                **standard_response_fields(ctx.query_hash, data_as_of, True),
            }

    except Exception as e:
        _error_code = getattr(e, "error_code", type(e).__name__)
        log.exception("audit_licence_compatibility error")
        raise
    finally:
        _ms = int((time.monotonic() - _t0) * 1000)
        fire_and_forget(track_tool_call(
            tool_id="T10",
            tool_name="audit_licence_compatibility",
            success=_success,
            latency_ms=_ms,
            cache_hit=False,
            error_code=_error_code,
        ))

async def audit_sbom_license_policy(
    sbom: Annotated[str, Field(description="CycloneDX or SPDX SBOM as JSON string. Required. 500 KB max.")],
    policy: Annotated[Optional[dict], Field(description="Policy dict with block/warn/allow arrays of SPDX licence IDs. Optional.")] = None,
) -> dict:
    """Audit a CycloneDX or SPDX SBOM against an SPDX licence policy and return a PASS/WARN/BLOCK verdict. sbom: Full SBOM as a JSON string — CycloneDX or SPDX format. Required. 500 KB max. policy: Optional dict with block/warn/allow arrays of exact SPDX licence identifiers (e.g. GPL-3.0, MIT). Defaults to block GPL-3.0 and AGPL-3.0, warn LGPL-2.1/MPL-2.0/BSD-4-Clause, allow MIT/Apache-2.0/BSD-2-Clause/BSD-3-Clause. No glob patterns — exact SPDX IDs only. Unlisted licences default to WARN. Returns verdict (PASS/WARN/BLOCK), blocked_packages, warned_packages, and the policy applied. Use security_audit_sbom_vulnerabilities for CVE auditing instead. Sources: deps.dev (Google). 1-hour cache per package. If this tool's response does not serve the user's need, call report_feedback with feedback_type="agent_gap", tool_id="security_audit_sbom_license_policy", intended_query="{what the user needed}", gap_description="{what was missing or wrong in the result}"."""
    _t0 = time.monotonic()
    _success = False
    _error_code = None
    try:
        if len(sbom.encode()) > 512_000:
            return {
                "verdict": "ERROR",
                "error": "SBOM exceeds 500 KB size limit.",
                "blocked_packages": [],
                "warned_packages": [],
            }

        effective_policy = _merge_policy(policy)
        sbom_hash = hashlib.sha256(sbom.encode()).hexdigest()[:32]
        policy_hash = hashlib.sha256(json.dumps(effective_policy, sort_keys=True).encode()).hexdigest()[:16]
        params = {"sbom_hash": sbom_hash, "policy_hash": policy_hash}

        async with AuditContext("T10", params, "1.0") as ctx:
            try:
                components, fmt = extract_components(sbom)
            except ValueError as exc:
                return {
                    "verdict": "ERROR",
                    "error": f"Invalid SBOM format — expected CycloneDX or SPDX JSON. Detail: {exc}",
                    "blocked_packages": [],
                    "warned_packages": [],
                }

            if not components:
                return {
                    "verdict": "ERROR",
                    "error": "No parseable components found in SBOM.",
                    "blocked_packages": [],
                    "warned_packages": [],
                }

            sem = asyncio.Semaphore(10)
            licence_results = await asyncio.gather(
                *[_fetch_licence_for_component(comp, sem) for comp in components],
                return_exceptions=True,
            )

            blocked = []
            warned  = []
            for comp, lic_result in zip(components, licence_results):
                if isinstance(lic_result, Exception):
                    licences = []
                else:
                    licences = lic_result if lic_result else []

                if not licences:
                    warned.append({
                        "name":    comp["name"],
                        "version": comp["version"],
                        "licence": "UNKNOWN",
                        "reason":  "Licence could not be determined — manual review required",
                    })
                    continue

                for lic in licences:
                    verdict_for_lic = _apply_policy(lic, effective_policy)
                    if verdict_for_lic == "BLOCK":
                        blocked.append({
                            "name":    comp["name"],
                            "version": comp["version"],
                            "licence": lic,
                            "reason":  f"Licence {lic} is in the block list",
                        })
                    elif verdict_for_lic == "WARN":
                        warned.append({
                            "name":    comp["name"],
                            "version": comp["version"],
                            "licence": lic,
                            "reason":  (
                                f"Licence {lic} is in the warn list"
                                if lic in effective_policy.get("warn", [])
                                else f"Licence {lic} not in policy — manual review required"
                            ),
                        })

            if blocked:
                overall = "BLOCK"
            elif warned:
                overall = "WARN"
            else:
                overall = "PASS"

            data_as_of = datetime.now(timezone.utc).isoformat()
            _success = True
            return {
                "status":          "ok",
                "tool_id":         "T10",
                "verdict":         overall,
                "sbom_format":     fmt,
                "total_components": len(components),
                "blocked_packages": blocked,
                "warned_packages":  warned,
                "policy_applied":   effective_policy,
                "disclaimer":       _DISCLAIMER,
                **standard_response_fields(ctx.query_hash, data_as_of, True),
            }

    except Exception as exc:
        _error_code = type(exc).__name__
        log.exception("audit_sbom_license_policy error")
        raise
    finally:
        _ms = int((time.monotonic() - _t0) * 1000)
        fire_and_forget(track_tool_call(
            tool_id="T10",
            tool_name="audit_sbom_license_policy",
            success=_success,
            latency_ms=_ms,
            cache_hit=False,
            error_code=_error_code,
        ))

async def fetch_cve_watch_status(
    watch_ids: Annotated[list, Field(description="List of watch IDs to check e.g. ['watch-1','watch-2']. Required.")],
) -> dict:
    """Check all specified CVE watches for new events since your last poll. Returns only watches with new events, making it efficient to run on a schedule. watch_ids: List of watch IDs to check — same IDs used when creating watches with security_fetch_cve_watch. Required. Uses a per-user cursor (last_polled timestamp) stored in Redis. First call returns events from the last 30 days. Subsequent calls return only events newer than the last poll. Sources: Redis (existing watch data written by security_fetch_cve_watch). No external API calls — instant response. If this tool's response does not serve the user's need, call report_feedback with feedback_type="agent_gap", tool_id="security_fetch_cve_watch_status", intended_query="{what the user needed}", gap_description="{what was missing or wrong in the result}"."""
    _t0 = time.monotonic()
    _success = False
    _error_code = None
    try:
        if not watch_ids:
            return {
                "status": "error",
                "error_code": "MISSING_PARAMS",
                "message": "watch_ids is required and must not be empty.",
            }

        clean_ids = [w.strip() for w in watch_ids if w and w.strip()]
        if not clean_ids:
            return {
                "status": "error",
                "error_code": "MISSING_PARAMS",
                "message": "watch_ids must contain at least one valid watch ID.",
            }

        params = {"watch_ids_hash": hashlib.sha256(json.dumps(sorted(clean_ids)).encode()).hexdigest()[:16]}

        async with AuditContext("T10", params, "1.0") as ctx:
            r = await get_redis()
            if not r:
                return {
                    "status": "error",
                    "error_code": "REDIS_UNAVAILABLE",
                    "message": "Watch status unavailable — Redis is not reachable.",
                }

            api_key_hash = api_key_var.get()
            cursor_key = f"dn:cve_watch:{api_key_hash or 'anon'}:_last_polled"
            now = datetime.now(timezone.utc)

            try:
                last_polled_str = await r.get(cursor_key)
                if last_polled_str:
                    last_polled = datetime.fromisoformat(last_polled_str)
                else:
                    last_polled = now - timedelta(days=30)
            except Exception as exc:
                log.warning("fetch_cve_watch_status: cursor read failed: %s", exc)
                last_polled = now - timedelta(days=30)

            watches_with_new = []
            total_watches = 0
            errors = []

            for wid in clean_ids:
                key = f"{_CVE_WATCH_PREFIX}{wid}"
                try:
                    watch_data = await r.hgetall(key)
                    if not watch_data:
                        continue
                    total_watches += 1
                    events_raw = watch_data.get("events", "[]")
                    try:
                        events = json.loads(events_raw) if events_raw else []
                    except json.JSONDecodeError:
                        events = []

                    new_events = []
                    for ev in events:
                        ev_date_str = ev.get("event_date", "")
                        try:
                            ev_dt = datetime.fromisoformat(ev_date_str)
                            if ev_dt > last_polled:
                                new_events.append({
                                    "cve_id":     ev.get("cve_id", ""),
                                    "event_type": ev.get("event_type", ""),
                                    "event_date": ev_date_str,
                                    "summary":    ev.get("summary", ""),
                                })
                        except (ValueError, TypeError):
                            continue

                    if new_events:
                        watches_with_new.append({
                            "watch_id":   wid,
                            "cve_ids":    json.loads(watch_data.get("cve_ids", "[]")),
                            "new_events": new_events,
                        })
                except Exception as exc:
                    log.warning("fetch_cve_watch_status: watch %s read failed: %s", wid, exc)
                    errors.append(wid)

            now_iso = now.isoformat()
            try:
                await r.set(cursor_key, now_iso, ex=90 * 24 * 3600)
            except Exception as exc:
                log.warning("fetch_cve_watch_status: cursor update failed: %s", exc)

            data_as_of = now_iso
            _success = True
            return {
                "status":               "ok",
                "tool_id":              "T10",
                "watches_with_new_events": watches_with_new,
                "total_watches_checked": total_watches,
                "last_polled":          last_polled.isoformat(),
                "polled_at":            now_iso,
                "errors":               errors,
                "disclaimer":           _DISCLAIMER,
                **standard_response_fields(ctx.query_hash, data_as_of, True),
            }

    except Exception as exc:
        _error_code = type(exc).__name__
        log.exception("fetch_cve_watch_status error")
        raise
    finally:
        _ms = int((time.monotonic() - _t0) * 1000)
        fire_and_forget(track_tool_call(
            tool_id="T10",
            tool_name="fetch_cve_watch_status",
            success=_success,
            latency_ms=_ms,
            cache_hit=False,
            error_code=_error_code,
        ))

def delimit_work_orders(
    action: Annotated[str, Field(description="One of \"list\" (default), \"show\", \"complete\".")] = "list",
    status: Annotated[str, Field(description="Filter for list — \"pending\" (default), \"completed\", \"all\".")] = "pending",
    wo_id: Annotated[str, Field(description="Work order id (required for \"show\" / \"complete\").")] = "",
    note: Annotated[str, Field(description="Completion note (used by \"complete\").")] = "",
) -> Dict[str, Any]:
    """Manage work orders — structured task artifacts for the founder (STR-177).

    When to use: to list, read, or close work orders that bridge
    strategy deliberations and interactive execution.
    When NOT to use: for ledger items (use delimit_ledger_*) or
    governance tasks (delimit_gov_new_task / run / verify).

    Sibling contrast: delimit_ledger_add tracks general work;
    delimit_gov_new_task is governance-classed; this is the founder
    work-order surface — copy-pasteable markdown artifacts.

    Side effects: action="list" / "show" are read-only. action="complete"
    writes to the work-order store via ai.work_order.complete_work_order.

    Args:
        action: One of "list" (default), "show", "complete".
        status: Filter for list — "pending" (default), "completed",
            "all".
        wo_id: Work order id (required for "show" / "complete").
        note: Completion note (used by "complete").

    Returns:
        Dict with the action result (list / markdown body / completion).
    """
    from ai.work_order import list_work_orders, complete_work_order, WORK_ORDERS_DIR

    if action == "list":
        orders = _safe_call(list_work_orders, status=status)
        return _with_next_steps("work_orders", {
            "action": "list",
            "status": status,
            "count": len(orders) if isinstance(orders, list) else 0,
            "orders": orders,
        })

    if action == "show":
        if not wo_id:
            return _with_next_steps("work_orders", {"error": "wo_id required for action=show"})
        md_path = WORK_ORDERS_DIR / f"{wo_id}.md"
        if not md_path.exists():
            return _with_next_steps("work_orders", {"error": f"{wo_id} not found"})
        return _with_next_steps("work_orders", {
            "action": "show",
            "id": wo_id,
            "content": md_path.read_text(),
        })

    if action == "complete":
        if not wo_id:
            return _with_next_steps("work_orders", {"error": "wo_id required for action=complete"})
        result = _safe_call(complete_work_order, wo_id=wo_id, note=note)
        return _with_next_steps("work_orders", result or {"error": "complete failed"})

    return _with_next_steps("work_orders", {
        "error": f"unknown action: {action!r}",
        "valid_actions": ["list", "show", "complete"],
    })

def delimit_sense(
    action: Annotated[str, Field(description="One of \"query\" (default), \"digest\", \"show\", \"promote\", \"freeze\", \"status\".")] = "query",
    since_days: Annotated[int, Field(description="Lookback window in days (query/digest). Default 1.")] = 1,
    platform: Annotated[str, Field(description="Filter source platform — \"reddit\", \"x\", \"github\", \"hn\". Empty = all.")] = "",
    limit: Annotated[int, Field(description="Max rows for query. Default 50.")] = 50,
    signal_id: Annotated[str, Field(description="SIG-XXXX id for \"show\" / \"promote\".")] = "",
    ledger: Annotated[str, Field(description="Target ledger for promote — \"ops\" (default) or \"strategy\".")] = "ops",
    priority: Annotated[str, Field(description="Priority for promoted item — \"P0\", \"P1\", \"P2\".")] = "P2",
    month: Annotated[str, Field(description="YYYY-MM string for \"freeze\".")] = "",
) -> Dict[str, Any]:
    """Review and manage the signal corpus (LED-877).

    When to use: to inspect, cluster, or explicitly promote sensed
    signals into ledger items. Signals live separately from the ledger
    so noise doesn't pollute it.
    When NOT to use: to fetch new signals (use the platform-specific
    sensors like delimit_reddit_scan / delimit_github_scan) or write
    ledger items directly (delimit_ledger_add).

    Sibling contrast: platform sensors capture; this manages the
    captured corpus and bridges it into the ledger.

    Side effects: "promote" writes a new ledger item (via the ledger
    manager). "freeze" cold-archives a month of signals. "query",
    "digest", "show", "status" are read-only against
    ~/.delimit/intel/signals/.

    Args:
        action: One of "query" (default), "digest", "show", "promote",
            "freeze", "status".
        since_days: Lookback window in days (query/digest). Default 1.
        platform: Filter source platform — "reddit", "x", "github",
            "hn". Empty = all.
        limit: Max rows for query. Default 50.
        signal_id: SIG-XXXX id for "show" / "promote".
        ledger: Target ledger for promote — "ops" (default) or "strategy".
        priority: Priority for promoted item — "P0", "P1", "P2".
        month: YYYY-MM string for "freeze".

    Returns:
        Dict with the action result (signals list, digest clusters,
        single signal, or promote/freeze receipt).
    """
    try:
        from ai.sensing import signal_store
    except ImportError as exc:
        return _with_next_steps("sense", {"error": f"signal store not available: {exc}"})

    act = (action or "query").lower().strip()

    if act == "query":
        rows = _safe_call(
            signal_store.query,
            since_days=since_days,
            platform=platform,
            limit=limit,
        )
        return _with_next_steps("sense", {
            "action": "query",
            "since_days": since_days,
            "platform": platform or "all",
            "count": len(rows) if isinstance(rows, list) else 0,
            "signals": rows,
        })

    if act == "digest":
        result = _safe_call(signal_store.digest, since_days=since_days or 7, top_n=limit or 20)
        return _with_next_steps("sense", {"action": "digest", **(result or {})})

    if act == "show":
        if not signal_id:
            return _with_next_steps("sense", {"error": "signal_id required for action=show"})
        found = _safe_call(signal_store._find_signal, signal_id=signal_id)
        if not found:
            return _with_next_steps("sense", {"error": f"signal {signal_id} not found"})
        return _with_next_steps("sense", {"action": "show", "signal": found})

    if act == "promote":
        if not signal_id:
            return _with_next_steps("sense", {"error": "signal_id required for action=promote"})
        try:
            result = signal_store.promote_to_ledger(
                signal_id=signal_id,
                ledger=ledger,
                priority=priority,
            )
        except Exception as exc:
            return _with_next_steps("sense", {"error": f"promote failed: {exc}"})
        return _with_next_steps("sense", {"action": "promote", "result": result})

    if act == "freeze":
        if not month:
            return _with_next_steps("sense", {"error": "month (YYYY-MM) required for action=freeze"})
        try:
            archive_path = signal_store.freeze_cold(month=month)
        except Exception as exc:
            return _with_next_steps("sense", {"error": f"freeze failed: {exc}"})
        return _with_next_steps("sense", {"action": "freeze", "month": month, "archive": archive_path})

    if act == "status":
        try:
            from pathlib import Path
            shards = sorted(signal_store.SIGNALS_DIR.glob("*.jsonl")) if signal_store.SIGNALS_DIR.exists() else []
            archive = sorted((signal_store.SIGNALS_DIR / "archive").glob("*.jsonl")) if (signal_store.SIGNALS_DIR / "archive").exists() else []
            hot_shards = [p.name for p in shards if not p.name.startswith("_")]
            return _with_next_steps("sense", {
                "action": "status",
                "signals_dir": str(signal_store.SIGNALS_DIR),
                "hot_shards": hot_shards,
                "hot_shard_count": len(hot_shards),
                "archive_files": [p.name for p in archive],
                "hot_window_days": signal_store.HOT_WINDOW_DAYS,
                "warm_window_days": signal_store.WARM_WINDOW_DAYS,
            })
        except Exception as exc:
            return _with_next_steps("sense", {"error": f"status failed: {exc}"})

    return _with_next_steps("sense", {
        "error": f"unknown action: {action!r}",
        "valid_actions": ["query", "digest", "show", "promote", "freeze", "status"],
    })

def delimit_security_ingest(
    tool: Annotated[str, Field(description="Scanner name — one of \"trivy\", \"semgrep\", \"npm-audit\", \"pip-audit\", \"snyk\", \"codeql\". Required.")],
    results: Annotated[str, Field(description="JSON string of scan results, or path to a JSON file. Required.")],
    repo: Annotated[str, Field(description="\"owner/repo\" identifier. Empty = auto-detect.")] = "",
    commit_sha: Annotated[str, Field(description="Git SHA the scan ran against. Empty = auto-detect.")] = "",
) -> Dict[str, Any]:
    """Ingest external security scan output and normalize into ledger findings (Pro).

    When to use: after running a scanner externally — Trivy, Semgrep,
    npm-audit, pip-audit, Snyk, CodeQL — to feed its JSON output into
    Delimit's canonical schema and gate deploys on unresolved criticals.
    When NOT to use: to run a scan from scratch (use
    delimit_security_scan) or to triage findings
    (delimit_security_deliberate).

    Sibling contrast: delimit_security_scan runs the built-in scan;
    delimit_security_deliberate triages findings; this is the bridge
    that pulls external scanner output into the same ledger.

    Side effects: gated by require_premium. Writes findings to the
    ledger (creates new items, optionally closes resolved ones).
    Computes a stable fingerprint per finding to enable diffing.

    Prerequisite: requires Delimit Pro. An unlicensed call returns
    {"error": ..., "upgrade": "https://delimit.ai/pricing"} without running.

    Args:
        tool: Scanner name — one of "trivy", "semgrep", "npm-audit",
            "pip-audit", "snyk", "codeql". Required.
        results: JSON string of scan results, or path to a JSON file.
            Required.
        repo: "owner/repo" identifier. Empty = auto-detect.
        commit_sha: Git SHA the scan ran against. Empty = auto-detect.

    Returns:
        Dict with normalized findings count, severity breakdown, ledger
        items created/closed, and a summary message.
    """
    from ai.license import require_premium
    gate = require_premium("security_ingest")
    if gate:
        return gate

    import hashlib as _hashlib

    SUPPORTED_TOOLS = ("trivy", "semgrep", "npm-audit", "pip-audit", "snyk", "codeql")
    tool_lower = tool.lower().replace(" ", "-").replace("_", "-")
    if tool_lower not in SUPPORTED_TOOLS:
        return _with_next_steps("security_ingest", {
            "error": f"Unsupported tool '{tool}'. Supported: {', '.join(SUPPORTED_TOOLS)}",
        })

    # Parse results - accept JSON string or file path
    raw_data = None
    if results.strip().startswith(("{", "[")):
        try:
            raw_data = json.loads(results)
        except json.JSONDecodeError as e:
            return _with_next_steps("security_ingest", {"error": f"Invalid JSON: {e}"})
    else:
        results_path = Path(results.strip())
        if results_path.is_file():
            try:
                raw_data = json.loads(results_path.read_text())
            except Exception as e:
                return _with_next_steps("security_ingest", {"error": f"Failed to read {results}: {e}"})
        else:
            return _with_next_steps("security_ingest", {"error": f"Not valid JSON and file not found: {results}"})

    # Auto-detect repo and commit
    if not repo:
        try:
            r = subprocess.run(["git", "remote", "get-url", "origin"], capture_output=True, text=True, timeout=5)
            if r.returncode == 0:
                url = r.stdout.strip()
                # Extract owner/repo from git URL
                for prefix in ["git@github.com:", "https://github.com/"]:
                    if url.startswith(prefix):
                        repo = url[len(prefix):].rstrip(".git")
                        break
        except Exception:
            pass

    if not commit_sha:
        try:
            r = subprocess.run(["git", "rev-parse", "HEAD"], capture_output=True, text=True, timeout=5)
            if r.returncode == 0:
                commit_sha = r.stdout.strip()[:12]
        except Exception:
            pass

    # Normalize findings based on tool format
    findings = []

    if tool_lower == "trivy":
        # Trivy JSON format: .Results[].Vulnerabilities[]
        for result_block in (raw_data if isinstance(raw_data, list) else raw_data.get("Results", [])):
            for vuln in result_block.get("Vulnerabilities", []):
                fingerprint = _hashlib.sha256(
                    f"{vuln.get('VulnerabilityID', '')}:{vuln.get('PkgName', '')}:{vuln.get('InstalledVersion', '')}".encode()
                ).hexdigest()[:16]
                findings.append({
                    "id": fingerprint,
                    "rule": vuln.get("VulnerabilityID", ""),
                    "severity": vuln.get("Severity", "UNKNOWN").lower(),
                    "package": vuln.get("PkgName", ""),
                    "version": vuln.get("InstalledVersion", ""),
                    "fixed_version": vuln.get("FixedVersion", ""),
                    "title": vuln.get("Title", vuln.get("VulnerabilityID", "")),
                    "description": vuln.get("Description", "")[:200],
                    "source_tool": "trivy",
                })

    elif tool_lower == "semgrep":
        # Semgrep JSON format: .results[]
        for r in raw_data.get("results", []):
            loc = r.get("path", "") + ":" + str(r.get("start", {}).get("line", ""))
            fingerprint = _hashlib.sha256(
                f"{r.get('check_id', '')}:{loc}".encode()
            ).hexdigest()[:16]
            sev = r.get("extra", {}).get("severity", "WARNING").lower()
            findings.append({
                "id": fingerprint,
                "rule": r.get("check_id", ""),
                "severity": sev if sev in ("error", "critical", "high", "medium", "low", "warning") else "medium",
                "file": r.get("path", ""),
                "line": r.get("start", {}).get("line"),
                "title": r.get("extra", {}).get("message", r.get("check_id", "")),
                "description": r.get("extra", {}).get("message", "")[:200],
                "source_tool": "semgrep",
            })

    elif tool_lower in ("npm-audit", "pip-audit"):
        # npm audit JSON: .vulnerabilities or .advisories
        vulns = raw_data.get("vulnerabilities", raw_data.get("advisories", raw_data))
        if isinstance(vulns, dict):
            for pkg_name, info in vulns.items():
                sev = info.get("severity", "moderate").lower()
                fingerprint = _hashlib.sha256(f"{pkg_name}:{sev}".encode()).hexdigest()[:16]
                findings.append({
                    "id": fingerprint,
                    "rule": info.get("via", [{}])[0].get("url", "") if isinstance(info.get("via"), list) else "",
                    "severity": {"critical": "critical", "high": "high", "moderate": "medium", "low": "low"}.get(sev, "medium"),
                    "package": pkg_name,
                    "version": info.get("range", ""),
                    "fixed_version": info.get("fixAvailable", {}).get("version", "") if isinstance(info.get("fixAvailable"), dict) else "",
                    "title": f"{sev.capitalize()} vulnerability in {pkg_name}",
                    "source_tool": tool_lower,
                })
        elif isinstance(vulns, list):
            # pip-audit format: list of {name, version, vulns: [{id, fix_versions}]}
            for pkg in vulns:
                for v in pkg.get("vulns", [pkg]):
                    fingerprint = _hashlib.sha256(f"{pkg.get('name', '')}:{v.get('id', '')}".encode()).hexdigest()[:16]
                    findings.append({
                        "id": fingerprint,
                        "rule": v.get("id", ""),
                        "severity": "high",
                        "package": pkg.get("name", ""),
                        "version": pkg.get("version", ""),
                        "fixed_version": ", ".join(v.get("fix_versions", [])),
                        "title": f"Vulnerability {v.get('id', '')} in {pkg.get('name', '')}",
                        "source_tool": tool_lower,
                    })

    else:
        # Generic: try to extract findings from common patterns
        if isinstance(raw_data, list):
            for item in raw_data[:100]:
                if isinstance(item, dict):
                    findings.append({
                        "id": _hashlib.sha256(json.dumps(item, sort_keys=True).encode()).hexdigest()[:16],
                        "rule": item.get("rule", item.get("id", "")),
                        "severity": item.get("severity", "medium").lower(),
                        "title": item.get("title", item.get("message", str(item)[:100])),
                        "source_tool": tool_lower,
                    })

    # Classify findings
    critical = [f for f in findings if f["severity"] in ("critical",)]
    high = [f for f in findings if f["severity"] in ("high", "error")]
    medium = [f for f in findings if f["severity"] in ("medium", "moderate", "warning")]
    low = [f for f in findings if f["severity"] in ("low", "info")]

    # LED-172: Auto-track security findings in ledger with lifecycle
    ledger_created = []
    ledger_closed = []
    try:
        from ai.ledger_manager import add_item, update_item, list_items
        existing = list_items()
        all_items = existing.get("items", [])
        if isinstance(all_items, dict):
            flat = []
            for v in all_items.values():
                if isinstance(v, list):
                    flat.extend(v)
            all_items = flat

        # Find open security items from this scanner
        open_security = {
            i.get("title", ""): i
            for i in all_items
            if isinstance(i, dict)
            and i.get("status") == "open"
            and i.get("source", "").startswith(f"security_ingest:{tool_lower}")
        }

        # Current finding titles
        current_titles = set()
        for finding in (critical + high)[:10]:
            title = f"Security: {finding['title'][:80]}"
            current_titles.add(title)
            if title not in open_security:
                entry = add_item(
                    title=title,
                    type="fix",
                    priority="P0" if finding["severity"] == "critical" else "P1",
                    description=f"Tool: {tool_lower}, Package: {finding.get('package', 'N/A')}, Fix: {finding.get('fixed_version', 'N/A')}",
                    source=f"security_ingest:{tool_lower}",
                )
                item_id = entry.get("added", {}).get("id", "")
                if item_id:
                    ledger_created.append(item_id)

        # Auto-close findings that disappeared (resolved in new scan)
        for title, item in open_security.items():
            if title not in current_titles:
                item_id = item.get("id", "")
                if item_id:
                    update_item(
                        item_id=item_id,
                        status="done",
                        note=f"Auto-resolved: finding no longer present in {tool_lower} scan (commit {commit_sha[:8] if commit_sha else 'unknown'})",
                    )
                    ledger_closed.append(item_id)
    except Exception as e:
        logger.warning("Security ingest ledger lifecycle failed: %s", e)

    return _with_next_steps("security_ingest", {
        "tool": "security_ingest",
        "scanner": tool_lower,
        "repo": repo,
        "commit": commit_sha,
        "findings": {
            "total": len(findings),
            "critical": len(critical),
            "high": len(high),
            "medium": len(medium),
            "low": len(low),
        },
        "top_findings": (critical + high + medium)[:10],
        "ledger_items_created": ledger_created,
        "ledger_items_resolved": ledger_closed,
        "message": f"Ingested {len(findings)} findings from {tool_lower}. {len(critical)} critical, {len(high)} high. {len(ledger_created)} new, {len(ledger_closed)} resolved.",
    })

def delimit_siem(action: Annotated[str, Field(description="One of \"status\" (default), \"configure\", \"test\", \"forward\".")] = "status", integration: Annotated[str, Field(description="One of \"splunk\", \"datadog\", \"eventbridge\", \"webhook\" (for configure).")] = "",
                  settings: Annotated[str, Field(description="JSON string of settings (for configure).")] = "", enabled: Annotated[str, Field(description="\"true\" or \"false\" (for configure).")] = "",
                  event: Annotated[str, Field(description="JSON string of an event (for forward / test).")] = "") -> Dict[str, Any]:
    """Manage SIEM streaming for audit-event forwarding (Splunk/Datadog/etc.).

    When to use: to inspect or configure where Delimit's audit events
    stream — Splunk, Datadog, EventBridge, generic webhooks.
    When NOT to use: for one-shot notifications (use delimit_notify) or
    inbox handling (delimit_notify_inbox).

    Sibling contrast: delimit_notify sends to humans;
    this configures structured-log streaming to SIEM endpoints.

    Side effects: action="configure" / "forward" / "test" write to the
    configured SIEM endpoints (network calls). action="status" is
    read-only.

    Args:
        action: One of "status" (default), "configure", "test", "forward".
        integration: One of "splunk", "datadog", "eventbridge", "webhook"
            (for configure).
        settings: JSON string of settings (for configure).
        enabled: "true" or "false" (for configure).
        event: JSON string of an event (for forward / test).

    Returns:
        Dict with integration status, delivery stats, or test result.
    """
    from ai.siem_streaming import configure, get_status, forward_event

    if action == "status":
        return _with_next_steps("siem", get_status())
    if action == "configure":
        parsed_settings = {}
        if settings:
            try:
                parsed_settings = json.loads(settings)
            except json.JSONDecodeError:
                return _with_next_steps("siem", {"error": "Invalid JSON in settings"})
        is_enabled = None
        if enabled:
            is_enabled = enabled.lower() in ("true", "1", "yes")
        return _with_next_steps("siem", configure(
            integration=integration,
            settings=parsed_settings if parsed_settings else None,
            enabled=is_enabled,
        ))
    if action in ("test", "forward"):
        test_event = {"type": "test", "timestamp": time.time(), "source": "siem_test"}
        if event:
            try:
                test_event = json.loads(event)
            except json.JSONDecodeError:
                pass
        return _with_next_steps("siem", forward_event(test_event))
    return _with_next_steps("siem", {"error": f"Unknown action: {action}"})

def delimit_swarm(action: Annotated[str, Field(description="See actions above.")] = "status", venture: Annotated[str, Field(description="Venture name (for register/venture/create_agent).")] = "",
                   agent_id: Annotated[str, Field(description="Agent ID (for agent/check/create_agent/approve_agent).")] = "", repo_path: Annotated[str, Field(description="Repo path, description, or reason depending on action.")] = "",
                   deploy_target: Annotated[str, Field(description="Deploy target for venture registration.")] = "", target_path: Annotated[str, Field(description="File path, tool name, or role name depending on action.")] = "",
                   access_action: Annotated[str, Field(description="Action name - for check: \"read\"/\"write\"/\"deploy\". For approve: \"deploy_production\"/\"deploy_staging\"/\"social_post\" etc.")] = "read") -> Dict[str, Any]:
    """Manage the cross-venture agent swarm (personas + namespace isolation).

    When to use: to inspect or mutate the swarm — register a venture
    with its 5 agent roles, create custom tools, hot-reload modules,
    check namespace access.
    When NOT to use: to dispatch a single task (use
    delimit_agent_dispatch) or read agent state
    (delimit_agent_status / dashboard).

    Sibling contrast: delimit_agent_dispatch is per-task;
    this manages the multi-venture / multi-persona swarm overall
    (Agent Swarm Standard v1.2).

    Side effects: action="register" / "create_tool" / "create_agent" /
    "approve_agent" / "reload" mutate state. status / venture / agent /
    list_* / check / approve / guide / rules are read-only.

    Each venture gets 5 AI agent roles (Architect, Senior Dev,
    Reviewer, QA, Ops) with namespace isolation and model binding.

    Actions:
      status: Full swarm overview (ventures, agents, health)
      register: Register a new venture with agent team
      venture: Get venture details + its agents
      agent: Get agent details
      check: Check namespace access for an agent
      approve: Check approval tier for an action
      guide: Get usage documentation
      rules: Get escalation rules
      create_tool: Create a custom MCP tool (architect/senior_dev only)
      list_tools: List custom tools per venture
      reload: Hot-reload MCP server to pick up updated modules
      create_agent: Provision a new specialist agent role (architect only)
      approve_agent: Activate a pending custom agent (founder only)
      list_agents: List all agents (built-in + custom)

    Args:
        action: See actions above.
        venture: Venture name (for register/venture/create_agent).
        agent_id: Agent ID (for agent/check/create_agent/approve_agent).
        repo_path: Repo path, description, or reason depending on action.
        deploy_target: Deploy target for venture registration.
        target_path: File path, tool name, or role name depending on action.
        access_action: Action name - for check: "read"/"write"/"deploy". For approve: "deploy_production"/"deploy_staging"/"social_post" etc.

    Returns:
        Dict whose shape depends on action — status returns swarm
        overview (ventures, agents, health); register returns the new
        venture record; venture/agent return the requested record;
        check/approve return access/approval verdicts; metric/metrics
        return recorded metrics; create_tool/create_agent/approve_agent
        return mutation results; reload returns the reload report.
        Every response also includes next_steps.
    """
    from ai.swarm import (register_venture, get_venture, get_agent,
                           check_namespace_access, get_swarm_status,
                           check_approval, get_escalation_rules, get_usage_guide)

    if action == "register":
        return _with_next_steps("swarm", _safe_call(
            register_venture, name=venture, repo_path=repo_path, deploy_target=deploy_target,
        ))
    if action == "venture":
        return _with_next_steps("swarm", _safe_call(get_venture, name=venture))
    if action == "agent":
        return _with_next_steps("swarm", _safe_call(get_agent, agent_id=agent_id))
    if action == "approve":
        return _with_next_steps("swarm", _safe_call(
            check_approval, action=access_action, venture=venture, agent_id=agent_id,
        ))
    if action == "guide":
        return _with_next_steps("swarm", _safe_call(get_usage_guide))
    if action == "rules":
        return _with_next_steps("swarm", _safe_call(get_escalation_rules))
    if action == "check":
        return _with_next_steps("swarm", _safe_call(
            check_namespace_access, agent_id=agent_id, target_path=target_path, action=access_action,
        ))
    if action == "metric":
        from ai.swarm import record_metric
        return _with_next_steps("swarm", _safe_call(
            record_metric, venture=venture, metric_type=access_action, note=target_path,
        ))
    if action == "metrics":
        from ai.swarm import get_metrics
        return _with_next_steps("swarm", _safe_call(get_metrics, venture=venture))
    if action == "docs_check":
        from ai.swarm import check_docs_freshness
        return _with_next_steps("swarm", _safe_call(
            check_docs_freshness, project_path=repo_path or ".",
        ))
    if action == "create_tool":
        from ai.swarm import create_tool
        return _with_next_steps("swarm", _safe_call(
            create_tool, name=target_path, code=repo_path, venture=venture, agent_id=agent_id,
        ))
    if action == "list_tools":
        from ai.swarm import list_custom_tools
        return _with_next_steps("swarm", _safe_call(list_custom_tools, venture=venture))
    if action == "reload":
        from ai.swarm import hot_reload
        return _with_next_steps("swarm", _safe_call(hot_reload, reason=repo_path or "manual"))
    if action == "create_agent":
        from ai.swarm import create_agent
        return _with_next_steps("swarm", _safe_call(
            create_agent,
            venture=venture,
            role_name=target_path,
            description=repo_path or "",
            default_model=agent_id or "claude-opus-4.6",
            creator_agent_id=agent_id,
        ))
    if action == "approve_agent":
        from ai.swarm import approve_agent
        return _with_next_steps("swarm", _safe_call(approve_agent, agent_id=agent_id))
    if action == "list_agents":
        from ai.swarm import list_agents
        return _with_next_steps("swarm", _safe_call(list_agents, venture=venture))
    if action == "preflight":
        from ai.swarm import preflight_check
        return _with_next_steps("swarm", _safe_call(
            preflight_check,
            action=access_action or "general",
            venture=venture,
            path=target_path or repo_path or "",
            agent_id=agent_id,
        ))
    return _with_next_steps("swarm", _safe_call(get_swarm_status))

def delimit_review(diff: Annotated[str, Field(description="Git diff or code text to review. Takes priority over file_path.")] = "", file_path: Annotated[str, Field(description="Path to file to review (reads current content if no diff).")] = "",
                    context: Annotated[str, Field(description="Additional context about the change.")] = "", pr_url: Annotated[str, Field(description="GitHub PR URL for linking the review.")] = "") -> Dict[str, Any]:
    """Run a multi-model code review on a diff or file.

    When to use: to get cross-model feedback on a code change before
    merging, optionally posted as a PR comment.
    When NOT to use: for structured cross-lens audit (use delimit_audit)
    or full multi-round debate (delimit_deliberate).

    Sibling contrast: delimit_audit is structured (security /
    correctness / governance lenses); delimit_deliberate is full
    debate; this is single-prompt multi-model review.

    Side effects: calls multiple models via ai.multi_review. May write
    a saved review record. When pr_url is provided, the review can be
    posted as a PR comment by the caller (this tool returns the comment
    body, it does not auto-post).

    Args:
        diff: Git diff or code text to review. Takes priority over
            file_path.
        file_path: Path to file to review (reads current content if no
            diff).
        context: Additional context about the change.
        pr_url: GitHub PR URL for linking the review.

    Returns:
        Dict with the consolidated review, per-model raw responses,
        and a pr_comment payload ready to post.
    """
    from ai.multi_review import generate_review_prompt, consolidate_reviews, save_review

    # Get the diff content
    if not diff and file_path:
        try:
            from subprocess import run as _run
            result = _run(
                ["git", "diff", "HEAD", "--", file_path],
                capture_output=True, text=True, timeout=10,
            )
            diff = result.stdout or Path(file_path).read_text()[:5000]
        except Exception:
            try:
                diff = Path(file_path).read_text()[:5000]
            except Exception as e:
                return {"error": f"Could not read {file_path}: {e}"}

    if not diff:
        return {"error": "Provide either diff text or file_path to review"}

    prompt = generate_review_prompt(diff, context)

    # Run through deliberation engine for multi-model feedback
    try:
        from ai.deliberation import get_models_config
        config = get_models_config()
        enabled = {k: v for k, v in config.items() if v.get("enabled")}

        if len(enabled) < 2:
            return {
                "error": "Need at least 2 AI models for multi-model review",
                "tip": "Configure models in ~/.delimit/models.json",
            }

        reviews = []
        from ai.deliberation import _call_model
        import time as _time

        for model_id, model_config in list(enabled.items())[:3]:
            start = _time.time()
            try:
                response = _call_model(model_id, model_config, prompt,
                    system_prompt="You are a senior code reviewer. Be concise and actionable.")
                duration = int((_time.time() - start) * 1000)
                reviews.append({
                    "model": model_config.get("name", model_id),
                    "content": response,
                    "duration_ms": duration,
                })
            except Exception as e:
                reviews.append({
                    "model": model_config.get("name", model_id),
                    "content": f"Review failed: {e}",
                    "duration_ms": 0,
                })

        report = consolidate_reviews(reviews)
        result = save_review(diff, report, pr_url)

        return _with_next_steps("review", {
            "status": "complete",
            "models_used": report["models_used"],
            "review_count": len(reviews),
            "pr_comment": result["pr_comment"],
            "review_id": result["review_id"],
        })

    except ImportError:
        return {"error": "Deliberation engine required for multi-model review"}

def delimit_collision_check(action: Annotated[str, Field(description="\"check\" (default), \"claim\", or \"release\".")] = "check", file_path: Annotated[str, Field(description="File to claim/release (required for claim/release).")] = "",
                             model: Annotated[str, Field(description="AI model name — \"claude\", \"codex\", \"gemini\".")] = "", task_id: Annotated[str, Field(description="Optional task id for tracking.")] = "") -> Dict[str, Any]:
    """Detect / prevent multi-model file edit collisions (LED-129).

    When to use: in cross-model workflows — claim a file before
    editing, release after committing — to prevent simultaneous
    conflicting edits between Claude / Codex / Gemini.
    When NOT to use: for single-model sessions or general filesystem
    locking outside the multi-model swarm.

    Sibling contrast: delimit_swarm tracks ventures and personas;
    this tracks per-file edit ownership.

    Side effects: action="claim" / "release" mutate the lock state.
    action="check" is read-only.

    Args:
        action: "check" (default), "claim", or "release".
        file_path: File to claim/release (required for claim/release).
        model: AI model name — "claude", "codex", "gemini".
        task_id: Optional task id for tracking.

    Returns:
        Dict with active locks (check), claim outcome, or release status.
    """
    from ai.collision_detect import claim_file, release_file, check_collisions

    if action == "claim":
        return _with_next_steps("collision", _safe_call(
            claim_file, file_path=file_path, model=model, task_id=task_id,
        ))
    if action == "release":
        return _with_next_steps("collision", _safe_call(
            release_file, file_path=file_path, model=model,
        ))
    return _with_next_steps("collision", _safe_call(check_collisions, model=model))

def delimit_help(tool_name: Annotated[str, Field(description="Tool name (e.g. \"lint\", \"gov_health\"). Empty returns the workflows overview.")] = "") -> Dict[str, Any]:
    """Get help for a Delimit tool — purpose, parameters, examples.

    When to use: when an agent or operator needs a quick reminder of
    a tool's interface, or wants the workflow overview.
    When NOT to use: for the full version/environment status (use
    delimit_version) or governance health (delimit_gov_health).

    Sibling contrast: delimit_version reports server info;
    this returns per-tool descriptions from the TOOL_HELP table.

    Side effects: read-only. Looks up an in-memory help table.

    Args:
        tool_name: Tool name (e.g. "lint", "gov_health"). Empty
            returns the workflows overview.

    Returns:
        Dict with description, params, example for the tool, or a
        workflow overview when tool_name is empty.
    """
    if not tool_name:
        total = _count_registered_tools()
        return _with_next_steps("help", {
            "message": "What problem are you solving?",
            "workflows": [
                {"name": w["name"], "pain": w["pain"], "start_with": w["steps"][0]}
                for w in STANDARD_WORKFLOWS
            ],
            "tip": "Tell me what you're trying to do - I'll suggest the right workflow.",
            "total_tools": total,
        })

    # Normalize name
    clean = tool_name.replace("delimit_", "").replace("mcp__delimit__delimit_", "")
    info = TOOL_HELP.get(clean)
    if info:
        return _with_next_steps("help", {"tool": clean, **info})
    return _with_next_steps("help", {"error": f"No help for '{tool_name}'. Try: {', '.join(TOOL_HELP.keys())}"})

def delimit_diagnose(project_path: Annotated[str, Field(description="Project to diagnose. Default \".\" (cwd).")] = ".", dry_run: Annotated[bool, Field(description="If True, preview changes without executing.")] = False, undo: Annotated[bool, Field(description="If True, revert changes from the last run.")] = False) -> Dict[str, Any]:
    """Comprehensive health check of the Delimit installation (delimit doctor).

    When to use: as the universal first-step diagnostic when something
    isn't working — covers MCP connectivity, deps, governance state,
    AI assistants, permissions, API keys, network, version, daemons,
    disk.
    When NOT to use: for repo-level health (use delimit_repo_diagnose)
    or first-run discovery (delimit_quickstart).

    Sibling contrast: delimit_repo_diagnose checks one repo;
    this checks the Delimit installation as a whole.

    Side effects: in normal mode, fixes some configuration drift
    (writes a doctor-manifest.json so later --undo can revert).
    dry_run=True is read-only and previews changes. undo=True reverts
    changes from the last doctor run using the saved manifest.

    Args:
        project_path: Project to diagnose. Default "." (cwd).
        dry_run: If True, preview changes without executing.
        undo: If True, revert changes from the last run.

    Returns:
        Dict with PASS/FAIL/SKIP per check, actionable fixes, manifest.
    """
    import sys
    import hashlib
    import urllib.request
    import urllib.error

    p_resolve = Path(project_path).resolve()
    manifest_path = p_resolve / ".delimit" / "doctor-manifest.json"

    # ── Undo mode: revert changes from last doctor run ──────────────────
    if undo:
        if not manifest_path.is_file():
            return {"status": "no_manifest", "message": "No doctor-manifest.json found. Nothing to undo."}
        try:
            manifest = json.loads(manifest_path.read_text())
        except Exception as exc:
            return {"status": "error", "message": f"Failed to read manifest: {exc}"}
        reverted = []
        skipped = []
        for entry in manifest.get("actions", []):
            target = Path(entry["path"])
            action = entry["action"]
            if action == "created":
                if target.is_file():
                    target.unlink()
                    reverted.append({"path": str(target), "action": "deleted"})
                elif target.is_dir():
                    import shutil
                    shutil.rmtree(target, ignore_errors=True)
                    reverted.append({"path": str(target), "action": "deleted_dir"})
                else:
                    skipped.append({"path": str(target), "reason": "already_gone"})
            elif action == "modified":
                # We stored original_hash but not original content — cannot restore
                skipped.append({"path": str(target), "reason": "modified_files_cannot_be_restored"})
            else:
                skipped.append({"path": str(target), "reason": f"unknown_action_{action}"})
        # Remove the manifest itself
        manifest_path.unlink(missing_ok=True)
        return {
            "status": "undo_complete",
            "reverted": reverted,
            "skipped": skipped,
            "message": f"Reverted {len(reverted)} item(s), skipped {len(skipped)}.",
        }

    # ── Dry-run mode: preview what doctor would create/modify ───────────
    if dry_run:
        planned = []
        delimit_dir = p_resolve / ".delimit"
        if not delimit_dir.is_dir():
            planned.append({"path": str(delimit_dir), "action": "create_dir", "description": ".delimit/ governance directory"})
            planned.append({"path": str(delimit_dir / "policies.yml"), "action": "create_file", "description": "Governance policy rules"})
            planned.append({"path": str(delimit_dir / "ledger"), "action": "create_dir", "description": "Operations ledger directory"})
            planned.append({"path": str(delimit_dir / "ledger" / "operations.jsonl"), "action": "create_file", "description": "Operations ledger"})
            planned.append({"path": str(delimit_dir / "evidence"), "action": "create_dir", "description": "Audit trail events directory"})
        else:
            if not (delimit_dir / "policies.yml").is_file():
                planned.append({"path": str(delimit_dir / "policies.yml"), "action": "create_file", "description": "Governance policy rules"})
            if not (delimit_dir / "ledger").is_dir():
                planned.append({"path": str(delimit_dir / "ledger"), "action": "create_dir", "description": "Operations ledger directory"})
            if not (delimit_dir / "evidence").is_dir():
                planned.append({"path": str(delimit_dir / "evidence"), "action": "create_dir", "description": "Audit trail events directory"})
        # Check for GitHub workflow creation
        github_dir = p_resolve / ".github" / "workflows"
        if github_dir.is_dir():
            wf = github_dir / "api-governance.yml"
            if not wf.is_file():
                planned.append({"path": str(wf), "action": "create_file", "description": "API governance GitHub Action workflow"})
        return {
            "status": "dry_run",
            "planned_changes": planned,
            "change_count": len(planned),
            "message": f"Doctor would create/modify {len(planned)} item(s). Run without --dry-run to apply."
                       if planned else "No changes needed.",
        }

    issues: List[Dict[str, str]] = []
    checks: Dict[str, Any] = {}
    checklist: List[Dict[str, str]] = []
    home = Path.home()

    def _record(name: str, status: str, detail: str = "", fix: str = ""):
        """Record a checklist item. status is PASS, FAIL, or SKIP."""
        entry = {"check": name, "status": status, "detail": detail}
        checklist.append(entry)
        if status == "FAIL" and fix:
            issues.append({"issue": f"{name}: {detail}", "fix": fix})

    # ── 1. MCP Server Connectivity ───────────────────────────────────────
    try:
        tool_count = _count_registered_tools()
        if tool_count > 0:
            _record("MCP Server", "PASS", f"Running, {tool_count} tools registered")
            checks["mcp_server"] = {"reachable": True, "tools": tool_count}
        else:
            _record("MCP Server", "FAIL", "Server running but 0 tools registered",
                     "Restart the MCP server -- possible import error")
            checks["mcp_server"] = {"reachable": True, "tools": 0}
    except Exception as exc:
        _record("MCP Server", "FAIL", f"Cannot query tool registry: {exc}",
                 "Restart the MCP server process")
        checks["mcp_server"] = {"reachable": False, "error": str(exc)}

    # ── 2. Python Dependencies ───────────────────────────────────────────
    checks["python"] = f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}"
    dep_results = {}
    required_deps = {
        "yaml": "pyyaml",
        "pydantic": "pydantic",
        "packaging": "packaging",
        "fastmcp": "fastmcp",
    }
    all_deps_ok = True
    for import_name, pip_name in required_deps.items():
        try:
            mod = __import__(import_name)
            ver = getattr(mod, "__version__", getattr(mod, "VERSION", "installed"))
            dep_results[import_name] = str(ver)
        except ImportError:
            dep_results[import_name] = "MISSING"
            all_deps_ok = False
    if all_deps_ok:
        _record("Python Dependencies", "PASS",
                 f"Python {checks['python']}, all {len(required_deps)} packages present")
    else:
        missing = [k for k, v in dep_results.items() if v == "MISSING"]
        _record("Python Dependencies", "FAIL",
                 f"Missing: {', '.join(missing)}",
                 f"pip install {' '.join(required_deps[m] for m in missing)}")
        for m in missing:
            issues.append({"issue": f"Missing Python package: {m}", "fix": f"pip install {required_deps[m]}"})
    checks["dependencies"] = dep_results
    # Backward compat keys
    for import_name, pip_name in required_deps.items():
        checks[f"dep_{import_name}" if import_name != "fastmcp" else "fastmcp"] = dep_results[import_name] != "MISSING"

    # ── 3. Governance State ──────────────────────────────────────────────
    p = Path(project_path).resolve()
    delimit_dir = p / ".delimit"
    policies = delimit_dir / "policies.yml"
    ledger = delimit_dir / "ledger" / "operations.jsonl"

    checks["project_path"] = str(p)
    checks["delimit_initialized"] = delimit_dir.is_dir()
    checks["policies_file"] = policies.is_file()
    checks["ledger_file"] = ledger.is_file()

    if delimit_dir.is_dir() and policies.is_file() and ledger.is_file():
        gov_parts = [".delimit/ exists", "policies.yml present", "ledger present"]
        try:
            entry_count = sum(1 for line in ledger.read_text().splitlines() if line.strip())
            gov_parts.append(f"{entry_count} ledger entries")
        except Exception:
            pass
        _record("Governance State", "PASS", "; ".join(gov_parts))
    elif not delimit_dir.is_dir():
        _record("Governance State", "FAIL", "Project not initialized",
                 "Run delimit_init(project_path='.') or say 'initialize governance for this project'")
        issues.append({
            "issue": "Project not initialized",
            "fix": "Run delimit_init(project_path='.') or say 'initialize governance for this project'",
        })
    else:
        missing_parts = []
        if not policies.is_file():
            missing_parts.append("policies.yml")
        if not ledger.is_file():
            missing_parts.append("ledger")
        _record("Governance State", "FAIL",
                 f".delimit/ exists but missing: {', '.join(missing_parts)}",
                 "Run delimit_init(project_path='.', preset='default')")
        if not policies.is_file():
            issues.append({
                "issue": "Missing policies.yml",
                "fix": "Run delimit_init(project_path='.', preset='default')",
            })

    # ── 4. AI Assistant Detection ────────────────────────────────────────
    config_sync = {}
    assistant_configs = {
        "claude_code": home / ".mcp.json",
        "codex_toml": home / ".codex" / "config.toml",
        "codex_json": home / ".codex" / "config.json",
        "cursor": home / ".cursor" / "mcp.json",
        "gemini": home / ".gemini" / "settings.json",
        "antigravity": home / ".gemini" / "antigravity-cli" / "settings.json",
    }
    for name, config_path in assistant_configs.items():
        if not config_path.exists():
            config_sync[name] = "not_installed"
            continue
        try:
            content = config_path.read_text()
            if "delimit" in content.lower():
                config_sync[name] = "configured"
            else:
                config_sync[name] = "missing_delimit"
                issues.append({
                    "issue": f"Delimit not configured in {name} ({config_path})",
                    "fix": "Run: npx delimit-cli setup",
                })
        except Exception:
            config_sync[name] = "read_error"

    configured_count = sum(1 for v in config_sync.values() if v == "configured")
    installed_count = sum(1 for v in config_sync.values() if v != "not_installed")
    checks["assistant_configs"] = config_sync
    checks["assistants_configured"] = f"{configured_count}/{installed_count}"

    if installed_count == 0:
        _record("AI Assistants", "SKIP", "No AI assistant configs found")
    elif configured_count == installed_count:
        _record("AI Assistants", "PASS",
                 f"{configured_count}/{installed_count} assistants have Delimit configured")
    else:
        unconfigured = [k for k, v in config_sync.items() if v == "missing_delimit"]
        _record("AI Assistants", "FAIL",
                 f"{configured_count}/{installed_count} configured; missing in: {', '.join(unconfigured)}",
                 "Run: npx delimit-cli setup")

    # ── 5. Permission Status ─────────────────────────────────────────────
    permission_info = {}
    claude_settings = home / ".claude.json"
    if claude_settings.exists():
        try:
            claude_data = json.loads(claude_settings.read_text())
            allowed = claude_data.get("allowedTools",
                        claude_data.get("permissions", {}).get("allow", []))
            if isinstance(allowed, list):
                delimit_allowed = [t for t in allowed if "delimit" in str(t).lower()]
                permission_info["claude_code"] = {
                    "auto_approved": len(delimit_allowed) > 0,
                    "count": len(delimit_allowed),
                }
            else:
                permission_info["claude_code"] = {"auto_approved": False, "count": 0}
        except Exception:
            permission_info["claude_code"] = {"status": "read_error"}
    project_claude = p / ".claude" / "settings.json"
    if project_claude.exists():
        try:
            pdata = json.loads(project_claude.read_text())
            proj_allowed = pdata.get("allowedTools",
                            pdata.get("permissions", {}).get("allow", []))
            if isinstance(proj_allowed, list):
                delimit_proj = [t for t in proj_allowed if "delimit" in str(t).lower()]
                permission_info["claude_code_project"] = {
                    "auto_approved": len(delimit_proj) > 0,
                    "count": len(delimit_proj),
                }
        except Exception:
            pass
    checks["permissions"] = permission_info

    if not permission_info:
        _record("Permissions", "SKIP", "No permission config files found")
    else:
        any_approved = any(
            v.get("auto_approved", False) for v in permission_info.values()
            if isinstance(v, dict)
        )
        if any_approved:
            _record("Permissions", "PASS", "Delimit tools are auto-approved")
        else:
            _record("Permissions", "FAIL",
                     "Delimit tools require manual approval on each call",
                     "Add 'mcp__delimit__*' to allowedTools in .claude.json or project settings")

    # ── 6. API Keys ──────────────────────────────────────────────────────
    environment = _detect_environment()
    api_keys = environment.get("api_keys", {})
    checks["api_keys"] = {k: "configured" for k in api_keys}

    if api_keys:
        _record("API Keys", "PASS",
                 f"{len(api_keys)} configured: {', '.join(sorted(api_keys.keys()))}")
    else:
        _record("API Keys", "SKIP",
                 "No API keys detected (set ANTHROPIC_API_KEY, OPENAI_API_KEY, etc.)")

    # ── 7. Network Connectivity ──────────────────────────────────────────
    network_checks = {}

    def _check_url(label: str, url: str) -> bool:
        try:
            req = urllib.request.Request(url, method="HEAD")
            resp = urllib.request.urlopen(req, timeout=5)
            network_checks[label] = {"reachable": True, "status": resp.status}
            return True
        except Exception as exc:
            network_checks[label] = {"reachable": False, "error": str(exc)[:120]}
            return False

    github_ok = _check_url("github_api", "https://api.github.com")
    npm_ok = _check_url("npm_registry", "https://registry.npmjs.org/delimit-cli")
    checks["network"] = network_checks

    if github_ok and npm_ok:
        _record("Network", "PASS", "GitHub API and npm registry reachable")
    elif not github_ok and not npm_ok:
        _record("Network", "FAIL", "Cannot reach GitHub API or npm registry",
                 "Check internet connection and firewall/proxy settings")
    else:
        parts = []
        if not github_ok:
            parts.append("GitHub API unreachable")
        if not npm_ok:
            parts.append("npm registry unreachable")
        _record("Network", "FAIL", "; ".join(parts),
                 "Check internet connection and firewall/proxy settings")

    # ── 8. Version Check ─────────────────────────────────────────────────
    checks["version"] = VERSION
    latest_version = None
    try:
        req = urllib.request.Request("https://registry.npmjs.org/delimit-cli/latest")
        resp = urllib.request.urlopen(req, timeout=5)
        npm_data = json.loads(resp.read().decode())
        latest_version = npm_data.get("version")
        checks["latest_npm_version"] = latest_version
        if latest_version and latest_version != VERSION:
            _record("Version", "FAIL",
                     f"Running {VERSION}, latest npm is {latest_version}",
                     f"npm update -g delimit-cli (or npx delimit-cli@{latest_version})")
        elif latest_version:
            _record("Version", "PASS", f"Running {VERSION} (latest)")
        else:
            _record("Version", "SKIP", f"Running {VERSION}, could not parse latest from npm")
    except Exception:
        _record("Version", "SKIP", f"Running {VERSION}, npm check unavailable")
        checks["latest_npm_version"] = None

    # ── 9. Daemon Status ─────────────────────────────────────────────────
    daemon_info = {}

    # Inbox daemon
    try:
        from ai.inbox_daemon import get_daemon_status as _inbox_status
        inbox_st = _inbox_status()
        running = inbox_st.get("running", inbox_st.get("status") == "running")
        daemon_info["inbox"] = {"running": bool(running)}
    except Exception:
        daemon_info["inbox"] = {"running": False, "note": "module_unavailable"}

    # Social daemon
    try:
        from ai.social_daemon import get_status as _social_status
        social_st = _social_status()
        running = social_st.get("running", social_st.get("status") == "running")
        daemon_info["social"] = {"running": bool(running)}
    except Exception:
        daemon_info["social"] = {"running": False, "note": "module_unavailable"}

    # Autonomous daemon
    try:
        from ai.daemon import get_daemon_status as _gen_status
        gen_st = _gen_status()
        running = gen_st.get("running", gen_st.get("status") == "running")
        daemon_info["autonomous"] = {"running": bool(running)}
    except Exception:
        daemon_info["autonomous"] = {"running": False, "note": "module_unavailable"}

    checks["daemons"] = daemon_info
    running_daemons = [k for k, v in daemon_info.items() if v.get("running")]
    stopped_daemons = [k for k, v in daemon_info.items() if not v.get("running")]

    if running_daemons:
        detail = f"Running: {', '.join(running_daemons)}"
        if stopped_daemons:
            detail += f"; stopped: {', '.join(stopped_daemons)}"
        _record("Daemons", "PASS", detail)
    else:
        _record("Daemons", "SKIP",
                 "No daemons running (start with delimit_inbox_daemon or delimit_daemon_run)")

    # ── 10. Disk Usage ───────────────────────────────────────────────────
    delimit_home = home / ".delimit"
    if delimit_home.exists():
        try:
            total_bytes = 0
            file_count = 0
            for f in delimit_home.rglob("*"):
                if f.is_file():
                    try:
                        total_bytes += f.stat().st_size
                        file_count += 1
                    except OSError:
                        pass
            if total_bytes < 1024:
                size_str = f"{total_bytes} B"
            elif total_bytes < 1024 * 1024:
                size_str = f"{total_bytes / 1024:.1f} KB"
            elif total_bytes < 1024 * 1024 * 1024:
                size_str = f"{total_bytes / (1024 * 1024):.1f} MB"
            else:
                size_str = f"{total_bytes / (1024 * 1024 * 1024):.2f} GB"

            checks["disk"] = {
                "path": str(delimit_home),
                "size_bytes": total_bytes,
                "size_human": size_str,
                "file_count": file_count,
            }
            if total_bytes > 500 * 1024 * 1024:
                _record("Disk Usage", "FAIL",
                         f"~/.delimit/ is {size_str} ({file_count} files) -- consider cleanup",
                         "Remove old ledger entries or run: du -sh ~/.delimit/*/")
            else:
                _record("Disk Usage", "PASS",
                         f"~/.delimit/ is {size_str} ({file_count} files)")
        except Exception as exc:
            _record("Disk Usage", "SKIP", f"Could not measure: {exc}")
            checks["disk"] = {"error": str(exc)}
    else:
        _record("Disk Usage", "SKIP", "~/.delimit/ does not exist")
        checks["disk"] = {"path": str(delimit_home), "exists": False}

    # ── MCP Security Warnings (LED-192) ──────────────────────────────────
    mcp_warnings = []
    mcp_config_path = home / ".mcp.json"
    if mcp_config_path.exists():
        try:
            mcp_data = json.loads(mcp_config_path.read_text())
            for server_name, server_cfg in mcp_data.get("mcpServers", {}).items():
                cmd = server_cfg.get("command", "")
                args = server_cfg.get("args", [])
                if "curl" in cmd or "wget" in cmd:
                    mcp_warnings.append(f"{server_name}: command uses curl/wget (potential remote code execution)")
                if any("--no-sandbox" in str(a) for a in args):
                    mcp_warnings.append(f"{server_name}: uses --no-sandbox flag")
                if server_cfg.get("env", {}).get("NODE_TLS_REJECT_UNAUTHORIZED") == "0":
                    mcp_warnings.append(f"{server_name}: TLS verification disabled")
        except Exception:
            pass
    if mcp_warnings:
        checks["mcp_warnings"] = mcp_warnings
        for w in mcp_warnings:
            issues.append({"issue": f"MCP security: {w}", "fix": "Review server configuration"})

    # ── Build Summary ────────────────────────────────────────────────────
    pass_count = sum(1 for c in checklist if c["status"] == "PASS")
    fail_count = sum(1 for c in checklist if c["status"] == "FAIL")
    skip_count = sum(1 for c in checklist if c["status"] == "SKIP")
    total_count = len(checklist)

    status = "healthy" if fail_count == 0 else "issues_found"
    result = {
        "status": status,
        "summary": f"{pass_count}/{total_count} checks passed, {fail_count} failed, {skip_count} skipped",
        "checklist": checklist,
        "checks": checks,
        "issues": issues,
        "issue_count": len(issues),
        "tip": "If everything looks good but tools aren't working, try restarting your AI assistant."
               " Run delimit_diagnose again after making fixes.",
    }
    # Dynamic next_steps
    diagnose_next = []
    if not delimit_dir.is_dir():
        diagnose_next.append({"tool": "delimit_init", "reason": "Initialize governance for this project", "suggested_args": {"preset": "default"}, "is_premium": False})
    if any(v == "missing_delimit" for v in config_sync.values()):
        diagnose_next.append({"tool": "delimit_quickstart", "reason": "Re-run setup to configure missing assistants", "is_premium": False})
    if fail_count > 0:
        diagnose_next.append({"tool": "delimit_help", "reason": "Get help on specific tools", "suggested_args": {"tool_name": "diagnose"}, "is_premium": False})
    result["next_steps"] = diagnose_next
    return result

def delimit_models(
    action: Annotated[str, Field(description="One of \"list\" (default), \"detect\", \"add\", \"remove\".")] = "list",
    provider: Annotated[str, Field(description="Provider name for add/remove. One of \"grok\", \"gemini\", \"openai\", \"anthropic\", \"codex\". Required for add/remove.")] = "",
    api_key: Annotated[str, Field(description="API key value. Required for action=\"add\".")] = "",
    model_name: Annotated[str, Field(description="Optional model override (e.g. \"gpt-4o\", \"claude-sonnet-4-5\"). Falls back to provider default.")] = "",
) -> Dict[str, Any]:
    """View and configure AI models for multi-model deliberation (Pro).

    When to use: to inventory configured providers, auto-detect new
    keys, or register/remove a provider for delimit_deliberate.
    When NOT to use: to actually run a deliberation (use
    delimit_deliberate) or to inspect deliberation history.

    Sibling contrast: delimit_deliberate runs the panel; this manages
    which models the panel can call.

    Side effects: gated by require_premium. action="add" / "remove"
    write provider config; "list" / "detect" are read-only.

    Prerequisite: requires Delimit Pro. An unlicensed call returns
    {"error": ..., "upgrade": "https://delimit.ai/pricing"} without running.

    Args:
        action: One of "list" (default), "detect", "add", "remove".
        provider: Provider name for add/remove. One of "grok",
            "gemini", "openai", "anthropic", "codex". Required for
            add/remove.
        api_key: API key value. Required for action="add".
        model_name: Optional model override (e.g. "gpt-4o",
            "claude-sonnet-4-5"). Falls back to provider default.

    Returns:
        Dict with the action result (provider list, detection summary,
        or add/remove confirmation).
    """
    from ai.license import require_premium
    gate = require_premium("models")
    if gate:
        return gate
    from ai.deliberation import configure_models, get_models_config, MODELS_CONFIG, DEFAULT_MODELS
    import json as _json

    if action == "list":
        return configure_models()

    if action == "detect":
        # Auto-detect from env vars and save
        config = get_models_config()
        detected = []
        env_map = {
            "grok": "XAI_API_KEY",
            "gemini": "GOOGLE_APPLICATION_CREDENTIALS",
            "openai": "OPENAI_API_KEY",
            "anthropic": "ANTHROPIC_API_KEY",
        }
        for pid, env_key in env_map.items():
            if os.environ.get(env_key) and pid not in config:
                defaults = DEFAULT_MODELS.get(pid, {})
                config[pid] = {**defaults, "enabled": True}
                if "api_key" in defaults:
                    config[pid]["api_key"] = os.environ[env_key]
                detected.append(pid)
        # Check codex CLI
        import shutil
        if shutil.which("codex") and "codex" not in config:
            config["codex"] = {**DEFAULT_MODELS.get("codex", {}), "enabled": True}
            detected.append("codex")

        if detected:
            MODELS_CONFIG.parent.mkdir(parents=True, exist_ok=True)
            MODELS_CONFIG.write_text(_json.dumps(config, indent=2))
            return {"action": "detect", "detected": detected, "total_models": len(config), "config_path": str(MODELS_CONFIG)}
        return {"action": "detect", "detected": [], "note": "No new API keys found in environment."}

    if action == "add":
        if not provider:
            return {"error": "Specify provider: grok, gemini, openai, anthropic, or codex"}

        config = {}
        if MODELS_CONFIG.exists():
            try:
                config = _json.loads(MODELS_CONFIG.read_text())
            except Exception:
                pass

        # Provider templates
        templates = {
            "grok": {"name": "Grok", "api_url": "https://api.x.ai/v1/chat/completions", "model": model_name or "grok-4-0709", "env_key": "XAI_API_KEY"},
            "openai": {"name": "OpenAI", "api_url": "https://api.openai.com/v1/chat/completions", "model": model_name or "gpt-4o", "env_key": "OPENAI_API_KEY", "prefer_cli": True},
            "anthropic": {"name": "Claude", "api_url": "https://api.anthropic.com/v1/messages", "model": model_name or "claude-sonnet-4-5-20250514", "env_key": "ANTHROPIC_API_KEY", "format": "anthropic"},
            "gemini": {"name": "Gemini", "api_url": "https://us-central1-aiplatform.googleapis.com/v1/projects/{project}/locations/us-central1/publishers/google/models/gemini-2.5-flash:generateContent", "model": model_name or "gemini-2.5-flash", "format": "vertex_ai"},
        }

        if provider not in templates:
            return {"error": f"Unknown provider '{provider}'. Supported: {', '.join(templates.keys())}"}

        entry = {**templates[provider], "enabled": True}
        if api_key:
            entry["api_key"] = api_key

        config[provider] = entry
        MODELS_CONFIG.parent.mkdir(parents=True, exist_ok=True)
        MODELS_CONFIG.write_text(_json.dumps(config, indent=2))
        return {"action": "add", "provider": provider, "model": entry.get("model"), "config_path": str(MODELS_CONFIG)}

    if action == "remove":
        if not provider:
            return {"error": "Specify provider to remove"}
        config = {}
        if MODELS_CONFIG.exists():
            try:
                config = _json.loads(MODELS_CONFIG.read_text())
            except Exception:
                pass
        if provider in config:
            del config[provider]
            MODELS_CONFIG.write_text(_json.dumps(config, indent=2))
            return {"action": "remove", "provider": provider, "remaining": list(config.keys())}
        return {"action": "remove", "provider": provider, "note": "Provider not found in config"}

    return {"error": f"Unknown action '{action}'. Use: list, detect, add, remove"}

def delimit_scan(project_path: Annotated[str, Field(description="Path to the project to scan. Default \".\" (cwd).")] = ".") -> Dict[str, Any]:
    """Scan a project and report what Delimit can do for it.

    When to use: as a first-run discovery on a new project — finds
    OpenAPI specs, checks for security issues, detects frameworks,
    suggests what to track.
    When NOT to use: to initialize governance (use delimit_init) or
    run the 60-second quickstart (delimit_quickstart).

    Sibling contrast: delimit_quickstart is a guided first-run flow;
    delimit_init creates the governance scaffolding; this is read-only
    discovery.

    Side effects: read-only scan via filesystem globs. Does not write
    to project files.

    Args:
        project_path: Path to the project to scan. Default "." (cwd).

    Returns:
        Dict with findings (specs, security, frameworks), suggestions,
        next_steps.
    """
    import glob as _glob
    p = Path(project_path).resolve()
    findings = []
    suggestions = []

    # 1. Find OpenAPI specs
    spec_patterns = ["**/openapi.yaml", "**/openapi.yml", "**/openapi.json",
                     "**/swagger.yaml", "**/swagger.yml", "**/swagger.json",
                     "**/*api*.yaml", "**/*api*.yml"]
    specs_found = []
    for pattern in spec_patterns:
        for match in p.glob(pattern):
            rel = str(match.relative_to(p))
            if "node_modules" not in rel and ".next" not in rel and "venv" not in rel:
                specs_found.append(rel)
    specs_found = list(set(specs_found))[:10]

    if specs_found:
        findings.append({"type": "openapi_specs", "count": len(specs_found), "files": specs_found})
        suggestions.append({"action": "lint", "detail": f"Run delimit_lint on {specs_found[0]} to check for issues"})
        suggestions.append({"action": "github_action", "detail": "Add the Delimit GitHub Action to catch breaking changes on PRs"})
    else:
        # Check for framework that could generate a spec
        framework = None
        if (p / "requirements.txt").exists() or (p / "pyproject.toml").exists():
            for py_file in p.rglob("*.py"):
                if "node_modules" in str(py_file):
                    continue
                try:
                    content = py_file.read_text(errors="ignore")[:2000]
                    if "FastAPI" in content or "fastapi" in content:
                        framework = "FastAPI"
                        break
                except Exception:
                    pass
        if (p / "package.json").exists():
            try:
                pkg = json.loads((p / "package.json").read_text())
                deps = {**pkg.get("dependencies", {}), **pkg.get("devDependencies", {})}
                if "@nestjs/core" in deps:
                    framework = "NestJS"
                elif "express" in deps:
                    framework = "Express"
            except Exception:
                pass

        if framework:
            findings.append({"type": "framework_detected", "framework": framework, "has_spec": False})
            suggestions.append({"action": "zero_spec", "detail": f"Run delimit_zero_spec to extract an OpenAPI spec from your {framework} code"})
        else:
            findings.append({"type": "no_api_detected", "note": "No OpenAPI spec or supported framework found"})

    # 2. Check for security patterns (quick scan)
    security_issues = []
    for pattern_name, pattern_glob, check in [
        ("env_file_in_git", ".env", lambda f: True),
        ("hardcoded_key", "**/*.py", lambda f: "API_KEY" in f.read_text(errors="ignore")[:5000] and "os.environ" not in f.read_text(errors="ignore")[:5000]),
        ("hardcoded_key_js", "**/*.js", lambda f: "apiKey" in f.read_text(errors="ignore")[:5000] and "process.env" not in f.read_text(errors="ignore")[:5000]),
    ]:
        try:
            for match in p.glob(pattern_glob):
                rel = str(match.relative_to(p))
                if "node_modules" in rel or ".next" in rel or "venv" in rel or "__pycache__" in rel:
                    continue
                if check(match):
                    security_issues.append({"issue": pattern_name, "file": rel})
                    break  # One per pattern is enough
        except Exception:
            pass

    if security_issues:
        findings.append({"type": "security_concerns", "count": len(security_issues), "issues": security_issues})
        suggestions.append({"action": "security_audit", "detail": "Run delimit_security_audit for a full scan"})

    # 3. Check git status
    try:
        import subprocess
        result = subprocess.run(["git", "log", "--oneline", "-1"], capture_output=True, text=True, timeout=5, cwd=str(p))
        if result.returncode == 0:
            findings.append({"type": "git_repo", "latest_commit": result.stdout.strip()})
    except Exception:
        pass

    # 4. Check for existing tests
    test_files = list(p.glob("**/test_*.py")) + list(p.glob("**/*.test.js")) + list(p.glob("**/*.test.ts")) + list(p.glob("**/*.spec.js"))
    test_files = [f for f in test_files if "node_modules" not in str(f)]
    if test_files:
        findings.append({"type": "tests_found", "count": len(test_files)})
        suggestions.append({"action": "test_coverage", "detail": "Run delimit_test_smoke to verify tests pass and measure coverage"})

    # 5. Check ledger
    from ai.ledger_manager import list_items
    ledger = list_items(project_path=str(p))
    open_items = [i for i in ledger.get("items", []) if isinstance(i, dict) and i.get("status") == "open"]
    if open_items:
        findings.append({"type": "ledger_active", "open_items": len(open_items), "top": [i.get("title", "") for i in open_items[:3]]})
    else:
        suggestions.append({"action": "ledger", "detail": "Say 'add to ledger: [task]' to start tracking work across sessions"})

    # 6. Check deliberation models
    from ai.deliberation import get_models_config
    models = get_models_config()
    enabled = [v.get("name", k) for k, v in models.items() if v.get("enabled")]
    if len(enabled) >= 2:
        findings.append({"type": "deliberation_ready", "models": enabled})
    elif len(enabled) == 1:
        suggestions.append({"action": "models", "detail": f"Add 1 more AI model for multi-model deliberation (have {enabled[0]})"})
    else:
        suggestions.append({"action": "models", "detail": "Configure AI models for deliberation: say 'configure delimit models'"})

    return _with_next_steps("scan", {
        "project": str(p),
        "findings": findings,
        "suggestions": suggestions,
        "summary": f"Found {len(findings)} things, {len(suggestions)} suggestions",
    })

def delimit_quickstart(project_path: Annotated[str, Field(description="Project path to quickstart. Default \".\" (cwd).")] = ".") -> Dict[str, Any]:
    """60-second guided quickstart for a new install.

    When to use: immediately after installing Delimit, as the
    minimum-effort path to prove value — combines init + scan +
    environment detection.
    When NOT to use: for activation/license confirmation (use
    delimit_activate) or full diagnostics (delimit_diagnose).

    Sibling contrast: delimit_init only writes scaffolding;
    delimit_scan only inspects; delimit_activate is post-license;
    this is the unified first-run flow.

    Side effects: triggers init (writes .delimit/) and runs scan
    (read-only). Detects environment in passing.

    Args:
        project_path: Project path to quickstart. Default "." (cwd).

    Returns:
        Dict with steps_completed, environment, suggestions, next_steps.
    """
    steps_completed = []
    p = Path(project_path).resolve()

    # Step 1: Auto-detect environment
    environment = _detect_environment()
    steps_completed.append({
        "step": 1,
        "name": "Environment Detection",
        "result": {
            "api_keys": len(environment["api_keys"]),
            "clis": list(environment["clis"].keys()),
            "security_tools": list(environment["security_tools"].keys()),
        },
    })

    # Step 2: Initialize governance (idempotent)
    init_result = delimit_init.fn(project_path=str(p)) if hasattr(delimit_init, "fn") else delimit_init(project_path=str(p))
    steps_completed.append({
        "step": 2,
        "name": "Governance Init",
        "status": init_result.get("status", "unknown"),
    })

    # Step 3: Scan project
    scan_result = delimit_scan.fn(project_path=str(p)) if hasattr(delimit_scan, "fn") else delimit_scan(project_path=str(p))
    steps_completed.append({
        "step": 3,
        "name": "Project Scan",
        "findings": len(scan_result.get("findings", [])),
        "suggestions": len(scan_result.get("suggestions", [])),
    })

    # Step 4: Check governance health
    from ai.governance import govern
    gov_health = {"status": "healthy"}
    try:
        delimit_dir = p / ".delimit"
        gov_health["initialized"] = delimit_dir.is_dir()
        gov_health["policies"] = (delimit_dir / "policies.yml").is_file()
        gov_health["ledger"] = (delimit_dir / "ledger").is_dir()
    except Exception:
        pass
    steps_completed.append({
        "step": 4,
        "name": "Governance Health",
        "result": gov_health,
    })

    # Step 5: Check deliberation readiness
    deliberation_ready = False
    enabled_models = []
    try:
        from ai.deliberation import get_models_config
        models = get_models_config()
        enabled_models = [v.get("name", k) for k, v in models.items() if v.get("enabled")]
        deliberation_ready = len(enabled_models) >= 2
    except Exception:
        pass
    steps_completed.append({
        "step": 5,
        "name": "Deliberation",
        "ready": deliberation_ready,
        "models": enabled_models,
    })

    # Step 6: First Governance Run -- show value with bundled example specs
    demo_result: Dict[str, Any] = {"skipped": False}
    examples_dir = Path(__file__).resolve().parent.parent / "examples"
    petstore_v1 = examples_dir / "petstore-v1.yaml"
    petstore_v2 = examples_dir / "petstore-v2.yaml"
    if petstore_v1.is_file() and petstore_v2.is_file():
        from backends.gateway_core import run_lint as _qs_run_lint, run_spec_health as _qs_run_spec_health

        # 6a: Lint petstore v1 vs v2 to show breaking change detection
        try:
            lint_demo = _qs_run_lint(
                old_spec=str(petstore_v1),
                new_spec=str(petstore_v2),
            )
            breaking_count = len(lint_demo.get("breaking", lint_demo.get("violations", [])))
            total_changes = lint_demo.get("total_changes", 0)
            demo_result["lint"] = {
                "breaking_changes": breaking_count,
                "total_changes": total_changes,
                "status": lint_demo.get("status", "unknown"),
                "sample_violations": [
                    v.get("message", v.get("type", "unknown"))
                    for v in lint_demo.get("breaking", lint_demo.get("violations", []))[:3]
                ],
            }
        except Exception as e:
            demo_result["lint"] = {"error": str(e)}

        # 6b: Spec health score on petstore v1
        try:
            health_demo = _qs_run_spec_health(spec_path=str(petstore_v1))
            demo_result["spec_health"] = {
                "score": health_demo.get("score", health_demo.get("overall_score")),
                "grade": health_demo.get("grade", health_demo.get("letter_grade")),
                "dimensions": {
                    k: v for k, v in health_demo.get("dimensions", {}).items()
                } if health_demo.get("dimensions") else {},
                "recommendations_count": len(health_demo.get("recommendations", [])),
            }
        except Exception as e:
            demo_result["spec_health"] = {"error": str(e)}
    else:
        demo_result["skipped"] = True
        demo_result["reason"] = "Example specs not found"

    steps_completed.append({
        "step": 6,
        "name": "First Governance Run (Demo)",
        "result": demo_result,
    })

    # Step 7: Project Spec Discovery -- check if this project has OpenAPI specs
    project_specs: List[str] = []
    project_lint_result: Optional[Dict[str, Any]] = None
    spec_patterns = [
        "**/openapi.yaml", "**/openapi.yml", "**/openapi.json",
        "**/swagger.yaml", "**/swagger.yml", "**/swagger.json",
    ]
    for pattern in spec_patterns:
        for match in p.glob(pattern):
            rel = str(match.relative_to(p))
            if "node_modules" not in rel and ".next" not in rel and "venv" not in rel:
                project_specs.append(str(match))
    project_specs = list(set(project_specs))[:5]

    if project_specs:
        # Run spec_health on the first discovered spec
        try:
            from backends.gateway_core import run_spec_health as _qs_health
            proj_health = _qs_health(spec_path=project_specs[0])
            project_lint_result = {
                "spec": project_specs[0],
                "score": proj_health.get("score", proj_health.get("overall_score")),
                "grade": proj_health.get("grade", proj_health.get("letter_grade")),
            }
        except Exception as e:
            project_lint_result = {"spec": project_specs[0], "error": str(e)}

    steps_completed.append({
        "step": 7,
        "name": "Project Spec Discovery",
        "specs_found": len(project_specs),
        "spec_files": project_specs,
        "health_result": project_lint_result,
    })

    # Build suggested next actions based on findings
    next_actions = []
    if project_specs:
        next_actions.append(f"Run `delimit_spec_health` on {project_specs[0]} to see your full quality report")
        if len(project_specs) > 1:
            next_actions.append(f"You have {len(project_specs)} OpenAPI specs -- run `delimit_lint` to compare versions")
        next_actions.append("Add the Delimit GitHub Action to catch breaking changes on every PR")
    else:
        if scan_result.get("findings"):
            for f in scan_result["findings"]:
                if f.get("type") == "openapi_specs":
                    next_actions.append("Run `delimit_lint` on your OpenAPI spec to check for breaking changes")
                if f.get("type") == "security_concerns":
                    next_actions.append("Run `delimit_security_scan` to audit for vulnerabilities")
                if f.get("type") == "tests_found":
                    next_actions.append("Run `delimit_test_smoke` to verify tests pass")

    if not deliberation_ready:
        next_actions.append("Add more AI models for multi-model deliberation: say 'configure delimit models'")

    next_actions.append("Say 'add to ledger: [task]' to start tracking work across sessions")
    next_actions.append("Say 'deliberate [question]' to get AI consensus on a decision")

    # Build the "wow moment" summary
    wow_moment: Dict[str, Any] = {}
    lint_data = demo_result.get("lint", {})
    health_data = demo_result.get("spec_health", {})
    if lint_data and not lint_data.get("error"):
        wow_moment["breaking_changes_caught"] = lint_data.get("breaking_changes", 0)
        wow_moment["total_api_changes"] = lint_data.get("total_changes", 0)
        wow_moment["sample_catches"] = lint_data.get("sample_violations", [])
    if health_data and not health_data.get("error"):
        wow_moment["spec_health_grade"] = health_data.get("grade")
        wow_moment["spec_health_score"] = health_data.get("score")
    wow_moment["governance_gates"] = [
        "Breaking change detection (CI/CD)",
        "Spec health scoring (quality)",
        "Policy enforcement (custom rules)",
        "Semver classification (automated)",
        "Contract ledger (audit trail)",
    ]
    if project_specs:
        wow_moment["your_project"] = {
            "specs_found": len(project_specs),
            "ready_to_govern": True,
        }
        if project_lint_result and not project_lint_result.get("error"):
            wow_moment["your_project"]["health_grade"] = project_lint_result.get("grade")
            wow_moment["your_project"]["health_score"] = project_lint_result.get("score")

    bc = wow_moment.get("breaking_changes_caught", 0)
    grade = wow_moment.get("spec_health_grade", "N/A")
    msg_parts = [
        f"Quickstart complete! {len(steps_completed)} steps run.",
        f"Demo: {bc} breaking changes caught, spec health grade: {grade}.",
        f"5 governance gates ready.",
    ]
    if project_specs:
        msg_parts.append(f"Found {len(project_specs)} OpenAPI spec(s) in your project -- ready to govern.")

    return _with_next_steps("quickstart", {
        "tool": "quickstart",
        "status": "complete",
        "project": str(p),
        "steps": steps_completed,
        "wow_moment": wow_moment,
        "environment": environment,
        "scan_findings": scan_result.get("findings", []),
        "scan_suggestions": scan_result.get("suggestions", []),
        "next_actions": next_actions,
        "message": " ".join(msg_parts),
    })

def delimit_tracker_sync(
    repo: Annotated[str, Field(description="\"owner/repo\" GitHub repo. Empty = auto-detect from git remote.")] = "",
    labels: Annotated[str, Field(description="Comma-separated label filter (e.g. \"bug,priority:high\").")] = "",
    limit: Annotated[int, Field(description="Max issues to sync. Default 10.")] = 10,
) -> Dict[str, Any]:
    """Pull open GitHub issues into the Delimit ledger as context (LED-188).

    When to use: to enrich the ledger with external issue context
    from a GitHub repo so cross-references work.
    When NOT to use: to write back to GitHub (this is read-only) or
    to monitor a single issue (delimit_sensor_github_issue).

    Sibling contrast: delimit_sensor_github_issue watches one issue;
    this syncs many into the ledger as context.

    Side effects: read-only on GitHub (network calls via gh CLI).
    Writes context entries into the ledger but does not push back to
    GitHub.

    Args:
        repo: "owner/repo" GitHub repo. Empty = auto-detect from git
            remote.
        labels: Comma-separated label filter (e.g. "bug,priority:high").
        limit: Max issues to sync. Default 10.

    Returns:
        Dict with sync result (issues fetched, ledger entries written).
    """
    import re as _re

    # Auto-detect repo from git remote
    if not repo:
        try:
            r = subprocess.run(["git", "remote", "get-url", "origin"], capture_output=True, text=True, timeout=5)
            if r.returncode == 0:
                url = r.stdout.strip()
                for prefix in ["git@github.com:", "https://github.com/"]:
                    if url.startswith(prefix):
                        repo = url[len(prefix):].rstrip(".git")
                        break
        except Exception:
            pass

    if not repo or not _re.match(r'^[\w.-]+/[\w.-]+$', repo):
        return _with_next_steps("tracker_sync", {"error": f"Invalid or missing repo: {repo}. Use owner/repo format."})

    # Fetch open issues via gh CLI
    try:
        label_filter = ""
        if labels:
            label_filter = f"&labels={labels}"
        cmd = ["gh", "api", f"repos/{repo}/issues?state=open&per_page={limit}{label_filter}",
               "--jq", '[.[] | {number, title, labels: [.labels[].name], assignee: .assignee.login, created_at, updated_at, html_url}]']
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
        if result.returncode != 0:
            return _with_next_steps("tracker_sync", {"error": f"gh api failed: {result.stderr.strip()[:200]}"})

        issues = json.loads(result.stdout) if result.stdout.strip() else []
    except Exception as e:
        return _with_next_steps("tracker_sync", {"error": f"Failed to fetch issues: {e}"})

    # Map to ledger-compatible format (read-only context, not actual ledger items)
    synced = []
    for issue in issues[:limit]:
        synced.append({
            "source": f"github:{repo}#{issue['number']}",
            "title": issue.get("title", ""),
            "labels": issue.get("labels", []),
            "assignee": issue.get("assignee"),
            "url": issue.get("html_url", ""),
            "updated_at": issue.get("updated_at", ""),
        })

    return _with_next_steps("tracker_sync", {
        "tool": "tracker_sync",
        "repo": repo,
        "issues_synced": len(synced),
        "issues": synced,
        "message": f"Pulled {len(synced)} open issues from {repo}. Use these as context for governance decisions.",
    })

def delimit_webhook_manage(
    action: Annotated[str, Field(description="One of \"list\" (default), \"add\", \"remove\", \"test\".")] = "list",
    url: Annotated[str, Field(description="Webhook URL (Slack, Discord, or any HTTP endpoint). Required for add / remove / test (test uses all configured if not specified).")] = "",
    events: Annotated[str, Field(description="Comma-separated event filter — \"all\" (default), \"blocked\", \"critical\", \"security\".")] = "all",
) -> Dict[str, Any]:
    """Manage webhook notifications for governance events.

    When to use: to register a Slack/Discord/HTTP webhook to receive
    governance alerts (deploy blocked, security finding, consensus).
    When NOT to use: for SIEM-class structured streaming (use
    delimit_siem) or one-shot notifications (delimit_notify).

    Sibling contrast: delimit_siem streams structured audit events;
    this routes governance alerts to chat / HTTP endpoints.

    Side effects: action="add" / "remove" mutate
    ~/.delimit/webhooks.json. action="test" sends a test notification
    to the configured webhooks. action="list" is read-only.

    Args:
        action: One of "list" (default), "add", "remove", "test".
        url: Webhook URL (Slack, Discord, or any HTTP endpoint).
            Required for add / remove / test (test uses all configured
            if not specified).
        events: Comma-separated event filter — "all" (default),
            "blocked", "critical", "security".

    Returns:
        Dict with the webhook list / add/remove confirmation / test
        delivery result.
    """
    webhooks_file = Path.home() / ".delimit" / "webhooks.json"

    def _load():
        if webhooks_file.exists():
            try:
                return json.loads(webhooks_file.read_text())
            except Exception:
                pass
        return []

    def _save(hooks):
        webhooks_file.parent.mkdir(parents=True, exist_ok=True)
        webhooks_file.write_text(json.dumps(hooks, indent=2))

    if action == "list":
        hooks = _load()
        return _with_next_steps("webhook_manage", {
            "webhooks": [{"url": h["url"][:50] + "...", "events": h.get("events", ["all"])} for h in hooks],
            "count": len(hooks),
        })

    if action == "add":
        if not url:
            return _with_next_steps("webhook_manage", {"error": "URL required. Provide a Slack or Discord webhook URL."})
        hooks = _load()
        event_list = [e.strip() for e in events.split(",") if e.strip()]
        hooks.append({"url": url, "events": event_list})
        _save(hooks)
        return _with_next_steps("webhook_manage", {
            "status": "added",
            "url": url[:50] + "...",
            "events": event_list,
            "total": len(hooks),
        })

    if action == "remove":
        if not url:
            return _with_next_steps("webhook_manage", {"error": "URL required to remove."})
        hooks = _load()
        before = len(hooks)
        hooks = [h for h in hooks if h.get("url") != url]
        _save(hooks)
        return _with_next_steps("webhook_manage", {
            "status": "removed" if len(hooks) < before else "not_found",
            "remaining": len(hooks),
        })

    if action == "test":
        hooks = _load()
        if not hooks:
            return _with_next_steps("webhook_manage", {"error": "No webhooks configured. Add one first."})
        test_event = {
            "ts": datetime.now(timezone.utc).isoformat(),
            "type": "test",
            "tool": "webhook_test",
            "status": "blocked",
            "risk_level": "critical",
            "venture": "test",
        }
        _fire_webhook(test_event)
        return _with_next_steps("webhook_manage", {
            "status": "test_sent",
            "webhooks_count": len(hooks),
            "message": "Test notification sent to all configured webhooks.",
        })

    return _with_next_steps("webhook_manage", {"error": f"Unknown action '{action}'. Use: list, add, remove, test."})

def delimit_x_fetch(id_or_url: Annotated[str, Field(description="Single status id (\"2048825010371039648\") OR a full x.com / twitter.com URL — id is extracted automatically. Mutually exclusive with `ids`.")] = "", ids: Annotated[str, Field(description="Comma-separated list of status ids OR URLs for a batch fetch. Each is normalized to a status id and fetched independently.")] = "") -> Dict[str, Any]:
    """Fetch tweets from X by id or URL via twttr241 RapidAPI (LED-825).

    When to use: to surgically fetch one or many tweets by id/URL,
    sharing the cached path with delimit_social_target so repeats
    are free.
    When NOT to use: to scan for new content (use delimit_social_target)
    or fetch a Reddit thread (delimit_reddit_fetch_thread).

    Sibling contrast: delimit_social_target scans for opportunities;
    delimit_reddit_fetch_thread is the Reddit equivalent;
    this is the X (Twitter) single/batch fetcher.

    Side effects: read-only network call via twttr241 (RapidAPI).
    Inherits the LRU + SQLite cache + budget gate from the
    social-target scanner — repeated reads are free. No writes.

    Args:
        id_or_url: Single status id ("2048825010371039648") OR a full
            x.com / twitter.com URL — id is extracted automatically.
            Mutually exclusive with `ids`.
        ids: Comma-separated list of status ids OR URLs for a batch
            fetch. Each is normalized to a status id and fetched
            independently.

    Returns:
        Single-fetch shape: {id, text, author, author_name, created_at,
            metrics: {favorite_count, retweet_count, reply_count,
            quote_count, bookmark_count, view_count}, url, from_cache}
        Batch shape: {tweets: [<single-shape>, ...], count}
        Errors: {error: <reason>}

    Why this exists: WebFetch hits 402 on x.com (auth-walled), and going
    around to tweepy + the X API direct creds skips the cache + budget
    gate. This tool is the cheap, cached, governable read path.
    """
    from ai.social_target import fetch_tweet_by_id, fetch_tweets_by_ids, extract_status_id

    if ids:
        # Batch mode — accept commas, newlines, or whitespace as separators
        raw = [r.strip() for r in ids.replace("\n", ",").split(",") if r.strip()]
        normalized: List[str] = []
        for item in raw:
            sid = extract_status_id(item)
            if sid:
                normalized.append(sid)
        if not normalized:
            return _with_next_steps("x_fetch", {"error": "no valid ids/URLs in `ids`"})
        results = fetch_tweets_by_ids(normalized)
        return _with_next_steps("x_fetch", {"tweets": results, "count": len(results)})

    if not id_or_url:
        return _with_next_steps("x_fetch", {"error": "provide either id_or_url or ids"})

    sid = extract_status_id(id_or_url)
    if not sid:
        return _with_next_steps("x_fetch", {"error": f"could not parse status id from {id_or_url!r}"})
    return _with_next_steps("x_fetch", fetch_tweet_by_id(sid))

def delimit_social_approve(action: Annotated[str, Field(description="\"list\" (default), \"approve\", or \"reject\".")] = "list", draft_id: Annotated[str, Field(description="Required for approve / reject. Returned by delimit_social_post(draft=True).")] = "") -> Dict[str, Any]:
    """Manage social media drafts — list, approve, reject (Pro).

    When to use: to clear the social drafts queue created by
    delimit_social_post(draft=True).
    When NOT to use: to draft (use delimit_social_post(draft=True)) or
    inspect history (delimit_social_history).

    Sibling contrast: delimit_social_post creates the draft;
    this lists / approves / rejects them.

    Side effects: action="approve" actually posts via the social
    backend (network write). action="reject" discards. action="list"
    is read-only.

    Args:
        action: "list" (default), "approve", or "reject".
        draft_id: Required for approve / reject. Returned by
            delimit_social_post(draft=True).

    Returns:
        Dict with drafts list / post result / discard confirmation.
    """
    _g = _pro_gate_graced("social_approve")
    if _g:
        return _g
    from ai.social import list_drafts, approve_draft, reject_draft

    if action == "list":
        pending = list_drafts("pending")
        return _with_next_steps("social_approve", {
            "drafts": pending,
            "count": len(pending),
        })
    elif action == "approve":
        if not draft_id:
            return {"error": "draft_id is required for approve action"}
        result = approve_draft(draft_id)
        return _with_next_steps("social_approve", result)
    elif action == "reject":
        if not draft_id:
            return {"error": "draft_id is required for reject action"}
        result = reject_draft(draft_id)
        return _with_next_steps("social_approve", result)
    else:
        return {"error": f"Unknown action: {action}. Supported: list, approve, reject"}

def delimit_social_target_config(
    action: Annotated[str, Field(description="\"status\" (default), \"detect\", \"update\", \"add_subreddits\".")] = "status",
    platform: Annotated[str, Field(description="Platform key — \"x\", \"reddit\", \"github\", \"hn\", \"devto\", \"namepros\".")] = "",
    enabled: Annotated[bool, Field(description="Enable/disable on update. Default True.")] = True,
    provider: Annotated[str, Field(description="Provider name — \"twttr241\", \"xai\", \"proxy\", \"gh_cli\", etc., for update.")] = "",
    subreddits: Annotated[str, Field(description="Comma-separated subreddits for add_subreddits.")] = "",
) -> Dict[str, Any]:
    """Configure social target scanning platforms.

    When to use: to inspect / update which platforms the social-target
    scanner uses, or to add subreddits a venture should scan.
    When NOT to use: to run a scan (use delimit_social_target) or
    drafts (delimit_social_generate).

    Sibling contrast: delimit_social_target runs scans;
    this configures which platforms to scan.

    Side effects: action="update" / "add_subreddits" write to the
    target config. action="status" / "detect" are read-only.

    Args:
        action: "status" (default), "detect", "update", "add_subreddits".
        platform: Platform key — "x", "reddit", "github", "hn",
            "devto", "namepros".
        enabled: Enable/disable on update. Default True.
        provider: Provider name — "twttr241", "xai", "proxy", "gh_cli",
            etc., for update.
        subreddits: Comma-separated subreddits for add_subreddits.

    Returns:
        Dict with the action result.
    """
    from ai.social_target import (
        get_config_status, _detect_available_platforms,
        update_platform_config, add_subreddits as add_subs,
    )

    if action == "status":
        return get_config_status()
    elif action == "detect":
        detection = _detect_available_platforms()
        return {"platforms": detection}
    elif action == "update":
        if not platform:
            return {"error": "Platform name is required for update action"}
        return update_platform_config(platform, enabled=enabled, provider=provider or None)
    elif action == "add_subreddits":
        if not platform or not subreddits:
            return {"error": "Platform (as venture name) and subreddits are required"}
        sub_list = [s.strip() for s in subreddits.split(",") if s.strip()]
        return add_subs(platform, sub_list)
    return {"error": f"Unknown action: {action}. Supported: status, detect, update, add_subreddits"}

def delimit_vendor_news_scan(dry_run: Annotated[bool, Field(description="If True, sensor-only (no drafter, no queue). Default False.")] = False) -> Dict[str, Any]:
    """Scan watchlisted vendor accounts and auto-draft riffs (Pro) (LED-1253).

    When to use: for ad-hoc execution of the vendor-news sensor
    (the cron is the normal autonomous path).
    When NOT to use: for a single tweet (use delimit_vendor_news_draft)
    or subsystem health (delimit_vendor_news_health).

    Sibling contrast: delimit_vendor_news_draft is one tweet;
    delimit_vendor_news_health is health rollup;
    this is the full sensor + drafter pass.

    Side effects: gated by require_premium. Wraps
    ai.vendor_news.sensor.scan_vendor_news + draft_vendor_riff.
    dry_run=True polls (cache-friendly) but skips JSONL log write
    AND skips the drafter entirely (no queue, no rate-cap consumption).

    Args:
        dry_run: If True, sensor-only (no drafter, no queue).
            Default False.

    Returns:
        Dict with stats, triggered, queued, rejected, rate_capped,
        errors — same shape as the cron summary.
    """
    gate = _pro_gate_graced("vendor_news_scan")
    if gate:
        return gate

    try:
        from ai.vendor_news import scan_vendor_news, draft_vendor_riff
    except Exception as exc:
        return _with_next_steps("vendor_news_scan", {
            "error": "vendor_news_unavailable",
            "message": f"could not import ai.vendor_news: {exc}",
        })

    try:
        scan = scan_vendor_news(dry_run=dry_run)
    except Exception as exc:
        return _with_next_steps("vendor_news_scan", {
            "error": "scan_failed",
            "message": str(exc),
        })

    triggered = scan.get("triggered") or []
    stats = scan.get("stats") or {}

    queued = 0
    rejected = 0
    rate_capped = 0
    drafter_errors: List[Dict[str, Any]] = []
    drafts: List[Dict[str, Any]] = []

    if not dry_run:
        for tw in triggered:
            try:
                res = draft_vendor_riff(tw)
            except Exception as exc:
                drafter_errors.append({"id": tw.get("id"), "error": str(exc)})
                continue
            decision = res.get("decision")
            reason = res.get("reason", "")
            drafts.append({
                "source_id": tw.get("id"),
                "vendor": tw.get("vendor"),
                "decision": decision,
                "reason": reason,
            })
            if decision == "queue":
                queued += 1
            elif reason == "rate_capped":
                rate_capped += 1
            else:
                rejected += 1

    result = {
        "stats": stats,
        "triggered": [
            {
                "id": t.get("id"),
                "vendor": t.get("vendor"),
                "url": t.get("url"),
                "trigger_reason": t.get("trigger_reason"),
                "metrics": t.get("metrics"),
            }
            for t in triggered
        ],
        "queued": queued,
        "rejected": rejected,
        "rate_capped": rate_capped,
        "errors": list(scan.get("errors") or []) + drafter_errors,
        "drafts": drafts,
        "dry_run": bool(dry_run),
    }
    return _with_next_steps("vendor_news_scan", result)

def delimit_vendor_news_health() -> Dict[str, Any]:
    """Health check for the vendor-news riff system (LED-1253).

    When to use: to answer "is the cron firing? are drafts landing?
    what's getting rejected?" without grepping logs.
    When NOT to use: to draft a riff (use delimit_vendor_news_draft) or
    inspect the broader social daemon (delimit_social_daemon).

    Sibling contrast: delimit_vendor_news_draft writes one riff;
    delimit_social_daemon controls the broader sensing daemon;
    this is the vendor-news subsystem health.

    Side effects: read-only. Greps crontab for the cron entry, reads
    sensor JSONL log, tweet queue, rejected log, watchlist file.

    Args:
        None.

    Returns:
        Dict with cron_installed, last_run_ts, sensor stats, 24h
        queued/rejected entries, watchlist count, budget snapshot.
    """
    from ai.vendor_news.sensor import SENSOR_LOG_PATH, WATCHLIST_PATH, load_watchlist
    from ai.vendor_news.drafter import TWEET_QUEUE_PATH, REJECTED_LOG_PATH

    out: Dict[str, Any] = {
        "cron_installed": False,
        "last_run_ts": None,
        "last_run_stats": None,
        "recent_queued_count_24h": 0,
        "recent_rejected_count_24h": 0,
        "recent_rejection_reasons_24h": {},
        "watchlist_account_count": 0,
        "daily_budget_used_estimate": 0,
    }

    # 1) crontab check
    try:
        proc = subprocess.run(
            ["crontab", "-l"],
            capture_output=True, text=True, timeout=5,
        )
        if proc.returncode == 0 and "vendor_news_cron.py" in (proc.stdout or ""):
            out["cron_installed"] = True
    except (FileNotFoundError, subprocess.SubprocessError, OSError):
        # crontab binary missing (containers, CI) — cron_installed stays False
        out["cron_installed"] = False

    cutoff = datetime.now(timezone.utc) - timedelta(hours=24)

    # 2) sensor log: last run + 24h budget estimate
    try:
        if SENSOR_LOG_PATH.exists():
            last_line = None
            budget_used = 0
            with open(SENSOR_LOG_PATH, "r", encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        entry = json.loads(line)
                    except (json.JSONDecodeError, ValueError):
                        continue
                    last_line = entry
                    ts_raw = entry.get("ts")
                    try:
                        ts_norm = ts_raw[:-1] + "+00:00" if ts_raw and ts_raw.endswith("Z") else ts_raw
                        ts = datetime.fromisoformat(ts_norm) if ts_norm else None
                    except (ValueError, TypeError):
                        ts = None
                    if ts is not None:
                        if ts.tzinfo is None:
                            ts = ts.replace(tzinfo=timezone.utc)
                        if ts >= cutoff:
                            budget_used += int(entry.get("live_calls") or 0)
            if last_line:
                out["last_run_ts"] = last_line.get("ts")
                out["last_run_stats"] = {
                    k: v for k, v in last_line.items()
                    if k not in ("triggered_ids", "error_handles")
                }
            out["daily_budget_used_estimate"] = budget_used
    except OSError:
        pass

    # 3) tweet_queue.json: 24h queued vendor_news_riff entries
    try:
        if TWEET_QUEUE_PATH.exists():
            data = json.loads(TWEET_QUEUE_PATH.read_text(encoding="utf-8"))
            if isinstance(data, list):
                count = 0
                for entry in data:
                    if not isinstance(entry, dict):
                        continue
                    if entry.get("priority") != "P0":
                        continue
                    if entry.get("category") != "vendor_news_riff":
                        continue
                    added_raw = entry.get("added_at")
                    try:
                        added_norm = (
                            added_raw[:-1] + "+00:00"
                            if added_raw and added_raw.endswith("Z")
                            else added_raw
                        )
                        added = datetime.fromisoformat(added_norm) if added_norm else None
                    except (ValueError, TypeError):
                        added = None
                    if added is None:
                        continue
                    if added.tzinfo is None:
                        added = added.replace(tzinfo=timezone.utc)
                    if added >= cutoff:
                        count += 1
                out["recent_queued_count_24h"] = count
    except (OSError, json.JSONDecodeError, ValueError):
        pass

    # 4) rejected JSONL: 24h count + reason histogram
    try:
        if REJECTED_LOG_PATH.exists():
            count = 0
            reasons: Dict[str, int] = {}
            with open(REJECTED_LOG_PATH, "r", encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        entry = json.loads(line)
                    except (json.JSONDecodeError, ValueError):
                        continue
                    ts_raw = entry.get("ts")
                    try:
                        ts_norm = (
                            ts_raw[:-1] + "+00:00"
                            if ts_raw and ts_raw.endswith("Z")
                            else ts_raw
                        )
                        ts = datetime.fromisoformat(ts_norm) if ts_norm else None
                    except (ValueError, TypeError):
                        ts = None
                    if ts is None:
                        continue
                    if ts.tzinfo is None:
                        ts = ts.replace(tzinfo=timezone.utc)
                    if ts < cutoff:
                        continue
                    count += 1
                    reason = entry.get("reason") or "unknown"
                    reasons[reason] = reasons.get(reason, 0) + 1
            out["recent_rejected_count_24h"] = count
            out["recent_rejection_reasons_24h"] = reasons
    except OSError:
        pass

    # 5) watchlist account count
    try:
        cfg = load_watchlist()
        accounts = cfg.get("accounts") or []
        out["watchlist_account_count"] = len(accounts)
    except Exception:
        pass

    return _with_next_steps("vendor_news_health", out)

def delimit_vendor_news_draft(tweet_id: Annotated[str, Field(description="Source X tweet id (numeric string) or full x.com URL. Required.")] = "", dry_run: Annotated[bool, Field(description="If True, suppress queue insertion. Default False.")] = False) -> Dict[str, Any]:
    """Draft a brand-voice Delimit-POV riff for a specific X tweet (Pro) (LED-1253).

    When to use: when an operator/sensor surfaces a vendor-news tweet
    that warrants a Delimit-POV riff for the autonomous content queue.
    When NOT to use: to fetch the tweet without drafting (use
    delimit_x_fetch) or for general social drafting
    (delimit_social_generate).

    Sibling contrast: delimit_x_fetch fetches; delimit_vendor_news_health
    inspects subsystem health; this drafts a riff into the queue.

    Side effects: gated by require_premium. Runs the riff drafter
    end-to-end: rate cap, source-fit pre-filter, generator, capability
    validator, fit floor, queue insert. dry_run=True suppresses the
    queue insert but still runs validators (and still consults the 24h
    per-vendor rate cap to avoid log noise).

    Args:
        tweet_id: Source X tweet id (numeric string) or full x.com URL.
            Required.
        dry_run: If True, suppress queue insertion. Default False.

    Returns:
        Dict with the drafted riff text, validator outcomes, queue
        insertion id (or skipped indicator), next_steps.
    """
    gate = _pro_gate_graced("vendor_news_draft")
    if gate:
        return gate

    raw = (tweet_id or "").strip()
    if not raw:
        return _with_next_steps("vendor_news_draft", {
            "error": "missing_tweet_id",
            "message": "tweet_id is required (status id or x.com URL)",
        })

    # Normalize id (accept URL or bare id)
    try:
        from ai.social_target import extract_status_id, fetch_tweet_by_id
    except Exception as exc:
        return _with_next_steps("vendor_news_draft", {
            "error": "social_target_unavailable",
            "message": str(exc),
        })

    sid = extract_status_id(raw)
    if not sid:
        return _with_next_steps("vendor_news_draft", {
            "error": "invalid_tweet_id",
            "message": f"could not parse status id from {raw!r}",
        })

    fetched = fetch_tweet_by_id(sid)
    if not isinstance(fetched, dict) or fetched.get("error"):
        return _with_next_steps("vendor_news_draft", {
            "error": "fetch_failed",
            "message": (fetched or {}).get("error", "unknown fetch error"),
            "tweet_id": sid,
        })

    # Map watchlist vendor metadata onto the source author. Falls back
    # gracefully if the tweet author isn't in the watchlist (e.g.
    # founder is testing a one-off riff against an off-watchlist post).
    try:
        from ai.vendor_news.sensor import load_watchlist
        from ai.vendor_news import draft_vendor_riff
    except Exception as exc:
        return _with_next_steps("vendor_news_draft", {
            "error": "vendor_news_unavailable",
            "message": str(exc),
        })

    author = (fetched.get("author") or "").lstrip("@")
    vendor_name = ""
    products: List[str] = []
    try:
        cfg = load_watchlist()
        for acc in cfg.get("accounts") or []:
            if (acc.get("handle") or "").lstrip("@").lower() == author.lower():
                vendor_name = acc.get("vendor", "") or author
                products = list(acc.get("products") or [])
                break
    except Exception:
        pass
    if not vendor_name:
        vendor_name = author or "unknown"

    triggered = {
        "id": fetched.get("id") or sid,
        "text": fetched.get("text") or "",
        "author": author,
        "url": fetched.get("url") or f"https://x.com/i/status/{sid}",
        "created_at": fetched.get("created_at") or "",
        "metrics": fetched.get("metrics") or {},
        "vendor": vendor_name,
        "products": products,
        "trigger_reason": "manual_draft",
    }

    # On dry_run, route the queue write to a temp path so the real
    # tweet queue is untouched. Drafter still runs validator + fit gates.
    queue_path_override = None
    if dry_run:
        try:
            import tempfile as _tempfile
            tmp = _tempfile.NamedTemporaryFile(
                mode="w", suffix=".json", prefix="vendor_news_dry_",
                delete=False, encoding="utf-8",
            )
            tmp.write("[]")
            tmp.close()
            queue_path_override = Path(tmp.name)
        except Exception:
            queue_path_override = None

    try:
        if queue_path_override is not None:
            res = draft_vendor_riff(triggered, queue_path=queue_path_override)
        else:
            res = draft_vendor_riff(triggered)
    except Exception as exc:
        return _with_next_steps("vendor_news_draft", {
            "error": "drafter_failed",
            "message": str(exc),
            "tweet_id": sid,
        })

    out = {
        "decision": res.get("decision"),
        "text": res.get("text"),
        "reason": res.get("reason"),
        "queue_entry": res.get("queue_entry") if not dry_run else None,
        "validator_result": res.get("validator_result"),
        "fit_result": res.get("fit_result"),
        "source": {
            "id": triggered["id"],
            "author": author,
            "vendor": vendor_name,
            "url": triggered["url"],
        },
        "dry_run": bool(dry_run),
    }
    return _with_next_steps("vendor_news_draft", out)

def delimit_content_publish(content_type: Annotated[str, Field(description="\"tweet\" (default) to post next queued tweet, \"youtube\" to generate + upload the next video, or \"report\" to STAGE (compose, not post) distribution for the next report.")] = "tweet") -> Dict[str, Any]:
    """Manually trigger a content publish (tweet, YouTube video, or report) (Pro).

    When to use: to fire off the next queued tweet or video on demand, or to
    STAGE distribution of the next mature report across owned broadcast
    surfaces (README / GitHub Release note / minimal X mirror).
    When NOT to use: to inspect the queue (use
    delimit_content_schedule) or modify it (delimit_content_queue).

    Sibling contrast: delimit_content_schedule reads;
    delimit_content_queue mutates queue;
    this performs a single publish step.

    Side effects: for tweet, posts the next queued tweet; for youtube,
    generates and uploads. For "report" (LED-3729) it is COMPOSE + STAGE
    ONLY — it writes composed distribution artifacts to a local staging
    queue and posts NOTHING to X and creates NO live GitHub Release.

    Args:
        content_type: "tweet" (default) to post next queued tweet,
            "youtube" to generate + upload the next video, or "report"
            to stage distribution for the next report (no live send).

    Returns:
        Dict with publish (or, for report, staging) result.
    """
    g = _pro_gate_graced("content_publish")
    if g:
        return g
    if content_type == "tweet":
        from ai.content_engine import post_next_tweet
        return _with_next_steps("content_publish", post_next_tweet())
    elif content_type == "youtube":
        from ai.content_engine import populate_video_queue, process_next_video
        populate_video_queue()
        return _with_next_steps("content_publish", process_next_video())
    elif content_type == "report":
        # LED-3729: STAGE ONLY — composes distribution artifacts for the next
        # report; does not post to X or create a Release.
        from ai.content_engine import stage_next_report_distribution
        return _with_next_steps("content_publish", stage_next_report_distribution())
    else:
        return {"error": f"Unknown content_type: {content_type}", "supported": ["tweet", "youtube", "report"]}

def delimit_content_queue(action: Annotated[str, Field(description="\"status\" (default), \"seed\", \"add\", or \"add_report\".")] = "status", items: Annotated[str, Field(description="For \"add\" — newline-separated tweet texts. For \"add_report\" — one or more report slugs (newline- or comma-separated).")] = "") -> Dict[str, Any]:
    """Manage the tweet, video, and report content queues.

    When to use: to view, seed, or add to the autonomous content
    queues that delimit_content_publish drains, or to STAGE a report
    for distribution (LED-3729).
    When NOT to use: to publish (use delimit_content_publish) or read
    upcoming schedule (delimit_content_schedule).

    Sibling contrast: delimit_content_publish drains;
    delimit_content_schedule reads; this mutates the queue.

    Side effects: action="seed" populates queue with defaults;
    action="add" appends tweet items; action="add_report" composes and
    STAGES report-distribution artifacts (README block / Release note /
    minimal X mirror) — compose-only, posts NOTHING. action="status" is
    read-only and now also reports the staged reports-distribution queue.

    Args:
        action: "status" (default), "seed", "add", or "add_report".
        items: For "add" — newline-separated tweet texts. For
            "add_report" — report slugs (newline- or comma-separated).

    Returns:
        Dict with queue state and next_steps. Returns
        {error: "..."} for "add"/"add_report" with empty items.
    """
    if action == "status":
        from ai.content_engine import (
            get_tweet_queue_status, get_content_schedule,
            get_report_distribution_status,
        )
        return _with_next_steps("content_queue", {
            "tweets": get_tweet_queue_status(),
            "schedule": get_content_schedule(),
            "reports": get_report_distribution_status(),
        })
    elif action == "seed":
        from ai.content_engine import seed_tweet_queue, populate_video_queue
        return _with_next_steps("content_queue", {
            "tweets": seed_tweet_queue(),
            "videos": populate_video_queue(),
        })
    elif action == "add":
        from ai.content_engine import add_tweets_to_queue
        tweet_list = [t.strip() for t in items.split("\n") if t.strip()]
        if not tweet_list:
            return {"error": "Provide tweet texts in 'items' parameter, separated by newlines"}
        return _with_next_steps("content_queue", add_tweets_to_queue(tweet_list))
    elif action == "add_report":
        # LED-3729: STAGE report distribution (compose-only, no live send).
        from ai.content_engine import enqueue_report_distribution
        slugs = [s.strip() for s in items.replace(",", "\n").split("\n") if s.strip()]
        if not slugs:
            return {"error": "Provide report slug(s) in 'items' (newline- or comma-separated)"}
        staged = [enqueue_report_distribution(slug) for slug in slugs]
        return _with_next_steps("content_queue", {"staged": staged})
    else:
        return {"error": f"Unknown action: {action}", "supported": ["status", "seed", "add", "add_report"]}

def delimit_build_loop(action: Annotated[str, Field(description="\"init\" to start a session, \"run\" (default) to execute one iteration.")] = "run", session_id: Annotated[str, Field(description="Optional session id to continue.")] = "", loop_type: Annotated[str, Field(description="\"cycle\", \"build\" (default), \"social\", or \"deploy\".")] = "build",
                       cycle_mode: Annotated[str, Field(description="For loop_type=\"cycle\" — \"sense\" (think+strategy), \"execute\" (build+deploy), or \"full\" (all). Default \"full\".")] = "full") -> Dict[str, Any]:
    """Execute one iteration of a governed continuous loop (LED-239).

    When to use: to advance the autonomous build / social / deploy
    loop one step, either interactively or from a daemon.
    When NOT to use: for status only (use delimit_loop_status) or to
    configure (delimit_loop_config).

    Sibling contrast: delimit_loop_status reads;
    delimit_loop_config sets policy; this drives one iteration.

    Side effects: depends on loop_type. cycle/build dispatches swarm
    work; social drafts replies; deploy runs gates and publishes.
    All loops write to the loop_engine's session record.

    Loop types:
    - cycle (recommended): unified think -> build -> deploy in one call.
    - build: picks feat/fix/task items from ledger, dispatches via swarm.
    - social (think): scans Reddit/X/HN, drafts replies.
    - deploy: runs deploy gates, publishes, verifies.

    Args:
        action: "init" to start a session, "run" (default) to execute
            one iteration.
        session_id: Optional session id to continue.
        loop_type: "cycle", "build" (default), "social", or "deploy".
        cycle_mode: For loop_type="cycle" — "sense" (think+strategy),
            "execute" (build+deploy), or "full" (all). Default "full".

    Returns:
        Dict with iteration outcome, session_id, next_steps.
    """
    from ai.loop_engine import (
        create_governed_session, run_governed_iteration,
        run_social_iteration, run_full_cycle,
    )

    if action == "init":
        return _with_next_steps("build_loop", create_governed_session(loop_type=loop_type))
    else:
        if not session_id:
            session_id = create_governed_session(loop_type=loop_type)["session_id"]
        if loop_type == "cycle":
            return _with_next_steps("build_loop", run_full_cycle(session_id, cycle_mode=cycle_mode))
        elif loop_type == "social" or session_id.startswith("social-"):
            return _with_next_steps("build_loop", run_social_iteration(session_id))
        else:
            return _with_next_steps("build_loop", run_governed_iteration(session_id))

def delimit_build_loop_daemon(
    action: Annotated[str, Field(description="\"start\", \"stop\", or \"status\" (default).")] = "status",
    session_id: Annotated[str, Field(description="Session to run. Required for all actions.")] = "",
    interval_seconds: Annotated[int, Field(description="Tick interval. Default 900 (15 min). Used on start.")] = 900,
    loop_type: Annotated[str, Field(description="\"build\" (default), \"social\", or \"deploy\". Used on start.")] = "build",
) -> Dict[str, Any]:
    """Background auto-pull daemon for governed build/social/deploy loops (Pro).

    When to use: to spawn a long-running daemon that ticks the
    governed loop every N seconds — the orchestrating Claude session
    tails ~/.delimit/logs/loop_daemon_<session_id>.jsonl for triage.
    When NOT to use: for one-shot iteration (use delimit_build_loop)
    or to read loop metrics (delimit_loop_status).

    Sibling contrast: delimit_build_loop is one iteration;
    this is the long-running daemon.

    Side effects: action="start" spawns a daemon thread that calls
    run_governed_iteration / run_social_iteration on a cadence.
    action="stop" halts. Each tick logs returned task_id to a JSONL.
    Respects delimit_loop_config safeguards (cost_cap, error_threshold,
    max_iterations, status=paused/stopped) via loop_status before each
    tick. Gated by require_premium.

    Args:
        action: "start", "stop", or "status" (default).
        session_id: Session to run. Required for all actions.
        interval_seconds: Tick interval. Default 900 (15 min). Used on
            start.
        loop_type: "build" (default), "social", or "deploy". Used on
            start.

    Returns:
        Dict with daemon state / start/stop confirmation.
    """
    gate = _pro_gate_graced("build_loop_daemon")
    if gate:
        return gate
    from ai import loop_daemon
    if not session_id:
        return {"error": "session_id is required"}
    if action == "start":
        return _with_next_steps("build_loop_daemon", loop_daemon.start(session_id, interval_seconds, loop_type))
    elif action == "stop":
        return _with_next_steps("build_loop_daemon", loop_daemon.stop(session_id))
    elif action == "status":
        return _with_next_steps("build_loop_daemon", loop_daemon.status(session_id))
    else:
        return {"error": f"unknown action: {action}. Expected start, stop, or status."}

def delimit_daemon_classify(item_id: Annotated[str, Field(description="Specific ledger item id to classify. Empty = pick the next automatable item from the open ledger.")] = "") -> Dict[str, Any]:
    """Classify a ledger item's risk tier and suggested automation tool.

    When to use: to preview what the autonomous daemon would do with
    a given ledger item (or the next automatable one).
    When NOT to use: to actually run an iteration (use
    delimit_daemon_run) or check daemon health (delimit_daemon_status).

    Sibling contrast: delimit_daemon_status reads health;
    delimit_daemon_run executes; this previews the classification.

    Side effects: read-only. Calls ai.daemon.classify_item /
    get_next_automatable_item / get_open_ledger_items.

    Args:
        item_id: Specific ledger item id to classify. Empty = pick the
            next automatable item from the open ledger.

    Returns:
        Dict with the item_id, risk tier, suggested tool, title.
        Returns {error: "..."} if item_id was given but not found.
    """
    from ai.daemon import classify_item, get_next_automatable_item, get_open_ledger_items

    if item_id:
        # Find specific item in open ledger items
        for item in get_open_ledger_items():
            if item.get("id") == item_id:
                risk, tool = classify_item(item)
                return _with_next_steps("daemon_classify", {
                    "item_id": item_id,
                    "risk": risk,
                    "tool": tool,
                    "title": item.get("title", ""),
                })
        return {"error": f"Item {item_id} not found"}
    else:
        item = get_next_automatable_item()
        if item:
            return _with_next_steps("daemon_classify", {
                "item_id": item.get("id"),
                "risk": item.get("_risk"),
                "tool": item.get("_suggested_tool"),
                "title": item.get("title", ""),
            })
        return {"status": "no_automatable_items"}

def delimit_inbox_daemon(action: Annotated[str, Field(description="\"start\" (begin polling), \"stop\" (halt polling), \"status\" (default — show daemon state).")] = "status") -> Dict[str, Any]:
    """Control the inbox polling daemon for email governance (Pro).

    When to use: at session start (per orchestrator session ritual) to
    ensure the daemon is up; or to stop/inspect it.
    When NOT to use: to read inbound items (use delimit_notify_inbox)
    or send notifications (delimit_notify).

    Sibling contrast: delimit_notify_inbox reads; this controls the
    daemon process that fills the inbox.

    Side effects: action="start" / "stop" mutate daemon process state.
    The daemon polls pro@delimit.ai every 5 minutes, classifies
    emails, forwards owner-action items, and handles draft approvals
    via email replies. Auto-posting is disabled — approved drafts are
    emailed for manual posting. Backing module is gateway-only and
    surfaces a graceful "not_available" payload when called from the
    npm bundle.

    Args:
        action: "start" (begin polling), "stop" (halt polling),
            "status" (default — show daemon state).

    Returns:
        Dict with daemon status, last poll, failures, next_steps.
    """
    g = _pro_gate_graced("inbox_daemon")
    if g:
        return g
    try:
        from ai.inbox_daemon import start_daemon, stop_daemon, get_daemon_status
    except (ImportError, ModuleNotFoundError):
        # LED-1261: backing module is gateway-only (excluded from npm bundle).
        # Customers calling this get a graceful message instead of a raw traceback.
        return _with_next_steps("inbox_daemon", {
            "status": "not_available",
            "error": "delimit_inbox_daemon is an internal Delimit feature not shipped in the npm bundle.",
            "hint": "Pro customers interested in inbox automation can contact pro@delimit.ai.",
        })

    if action == "start":
        return _with_next_steps("inbox_daemon", start_daemon())
    elif action == "stop":
        return _with_next_steps("inbox_daemon", stop_daemon())
    else:
        return _with_next_steps("inbox_daemon", get_daemon_status())

