def delimit_config_export(project_path: Annotated[str, Field(description="Path to project root. Default \".\" (cwd).")] = ".") -> Dict[str, Any]:
    """Export the current governance config as a shareable JSON bundle.

    When to use: to package a project's delimit.yml + GitHub Action
    workflow into a portable JSON config for sharing or import.
    When NOT to use: to read live policy (use delimit_gov_policy) or
    initialize a new project (delimit_init).

    Sibling contrast: delimit_config_import is the round-trip
    counterpart; this exports.

    Side effects: read-only on the project. Sanitizes project_path
    via _sanitize_path. Returns the bundle in the response — no file
    write.

    Args:
        project_path: Path to project root. Default "." (cwd).

    Returns:
        Dict with the JSON config bundle and next_steps.
    """
    span = _next_span_id()
    try:
        root = _sanitize_path(project_path, "project_path")

        bundle: Dict[str, Any] = {
            "delimit_config_version": 1,
            "created_at": datetime.now(timezone.utc).isoformat(),
            "project": root.name,
            "policies": None,
            "workflow": None,
        }

        # Find policy file
        candidates = [
            root / "delimit.yml",
            root / ".delimit.yml",
            root / ".delimit" / "policies.yml",
        ]
        for p in candidates:
            if p.is_file():
                bundle["policies"] = {
                    "path": str(p.relative_to(root)),
                    "content": p.read_text(encoding="utf-8"),
                }
                break

        if not bundle["policies"]:
            return _with_next_steps("config_export", {
                "error": "no_config",
                "message": f"No governance config found in {root}. Run delimit_init first.",
                "span_id": span,
            })

        # GitHub Action workflow
        wf = root / ".github" / "workflows" / "api-governance.yml"
        if wf.is_file():
            bundle["workflow"] = {
                "path": ".github/workflows/api-governance.yml",
                "content": wf.read_text(encoding="utf-8"),
            }

        import base64
        encoded = base64.b64encode(json.dumps(bundle).encode()).decode()
        share_url = f"https://delimit.ai/import?config={encoded}"

        return _with_next_steps("config_export", {
            "config": bundle,
            "share_url": share_url,
            "span_id": span,
        })
    except Exception as e:
        logger.error("config_export error: %s\n%s", e, traceback.format_exc())
        return {"error": "config_export_failed", "message": str(e), "span_id": span}

def delimit_notify_routing(
    action: Annotated[str, Field(description="One of \"status\" (default), \"configure\", \"test\".")] = "status",
    config: Annotated[str, Field(description="JSON string with routing config for action=\"configure\". Example shape: {\"routing\": {\"critical\": {...}, ...}}.")] = "",
    webhook_url: Annotated[str, Field(description="Webhook URL used by action=\"test\".")] = "",
    email_to: Annotated[str, Field(description="Email recipient used by action=\"test\".")] = "",
    from_account: Annotated[str, Field(description="Sender account key for the test email.")] = "",
) -> Dict[str, Any]:
    """Manage impact-based notification routing (LED-233).

    When to use: to inspect or update the rules that route change
    alerts to email / webhook / digest by severity.
    When NOT to use: to read the inbox (use delimit_notify_inbox) or
    fire a single notification (use delimit_notify).

    Sibling contrast: delimit_notify sends; delimit_notify_inbox reads
    inbound; this configures routing rules between them.

    Side effects: action="configure" writes via
    ai.notify.save_routing_config; action="test" sends test
    notifications to the configured channels. action="status" is
    read-only.

    Args:
        action: One of "status" (default), "configure", "test".
        config: JSON string with routing config for action="configure".
            Example shape: {"routing": {"critical": {...}, ...}}.
        webhook_url: Webhook URL used by action="test".
        email_to: Email recipient used by action="test".
        from_account: Sender account key for the test email.

    Returns:
        Dict with current/updated config or test delivery results.
    """
    from ai.notify import (
        load_routing_config,
        save_routing_config,
        route_by_impact,
        DEFAULT_ROUTING_CONFIG,
    )

    if action == "status":
        current = load_routing_config()
        return _with_next_steps("notify_routing", {
            "action": "status",
            "config": current,
            "config_file": str(Path.home() / ".delimit" / "notify_routing.yaml"),
            "using_defaults": current == DEFAULT_ROUTING_CONFIG,
        })

    elif action == "configure":
        if not config:
            return _with_next_steps("notify_routing", {
                "error": "config parameter required for action='configure'.",
                "usage": 'Pass a JSON string with routing rules, e.g. {"routing": {"critical": {"channels": ["email"]}}}',
            })
        try:
            parsed = json.loads(config) if isinstance(config, str) else config
        except json.JSONDecodeError as e:
            return _with_next_steps("notify_routing", {
                "error": f"Invalid JSON in config: {e}",
            })
        result = save_routing_config(parsed)
        return _with_next_steps("notify_routing", {
            "action": "configure",
            **result,
        })

    elif action == "test":
        # Generate synthetic changes at each severity level
        test_changes = [
            {"type": "endpoint_removed", "path": "/test/critical", "message": "Test critical: endpoint removed", "is_breaking": True},
            {"type": "parameter_added", "path": "/test/warning", "message": "Test warning: optional parameter added", "is_breaking": False},
            {"type": "description_changed", "path": "/test/info", "message": "Test info: description updated", "severity": "info"},
        ]
        result = route_by_impact(
            test_changes,
            webhook_url=webhook_url,
            email_to=email_to,
            from_account=from_account,
            dry_run=not (webhook_url or email_to),
        )
        return _with_next_steps("notify_routing", {
            "action": "test",
            **result,
        })

    else:
        return _with_next_steps("notify_routing", {
            "error": f"Unknown action: {action}. Supported: status, configure, test.",
        })

def delimit_notify_inbox(action: Annotated[str, Field(description="\"status\" (default), \"poll\", or \"history\".")] = "status", limit: Annotated[int, Field(description="Number of messages to check (default 10).")] = 10,
                         process: Annotated[bool, Field(description="With action=\"poll\", forward owner-action emails when True (default), dry-run only when False.")] = True) -> Dict[str, Any]:
    """Check inbound email inbox, classify, and route (Pro).

    When to use: to poll the operator inbox and classify which emails
    require owner action (forwarded) vs which can stay queued.
    When NOT to use: to send notifications (use delimit_notify) or
    control the polling daemon (delimit_inbox_daemon).

    Sibling contrast: delimit_inbox_daemon controls the long-running
    daemon; this is a one-shot poll. delimit_notify is the outbound
    counterpart.

    Side effects: action="poll" with process=True forwards owner-action
    emails (network writes). action="poll" with process=False is
    dry-run. action="status" / "history" are read-only.

    Args:
        action: "status" (default), "poll", or "history".
        limit: Number of messages to check (default 10).
        process: With action="poll", forward owner-action emails when
            True (default), dry-run only when False.

    Returns:
        Dict with inbox state / poll result / routing history.
    """
    g = _pro_gate_graced("notify_inbox")
    if g:
        return g
    from ai.notify import poll_inbox, get_inbox_status

    if action == "poll":
        return _with_next_steps("notify_inbox", _safe_call(
            poll_inbox, limit=limit, process=process,
        ))
    elif action == "history":
        from ai.notify import INBOX_ROUTING_FILE
        import json as _json
        history = []
        try:
            if INBOX_ROUTING_FILE.exists():
                with open(INBOX_ROUTING_FILE, "r") as f:
                    lines = f.readlines()
                for line in lines[-limit:]:
                    try:
                        history.append(_json.loads(line.strip()))
                    except _json.JSONDecodeError:
                        continue
        except OSError:
            pass
        return {"routing_history": history, "count": len(history)}
    else:  # status
        return _with_next_steps("notify_inbox", _safe_call(
            get_inbox_status, limit=limit,
        ))

def delimit_toolcard_cache(
    action: Annotated[str, Field(description="One of \"status\" (default), \"register\", \"delta\", \"clear\", \"estimate\", \"flush\", \"usage\" (durable tool utilization + dormancy report).")] = "status",
    tool_schemas: Annotated[Optional[str], Field(description="JSON array of tool schema objects (for register/ estimate).")] = None,
    tool_names: Annotated[Optional[str], Field(description="Comma-separated tool names (for delta).")] = None,
) -> Dict[str, Any]:
    """Manage the tool-schema cache to reduce per-session token waste.

    When to use: when an MCP client repeatedly dumps full tool
    definitions and you want to send only diffs across sessions.
    When NOT to use: as a runtime tool dispatcher — this is a cache
    side-channel, not a tool-call surface.

    Sibling contrast: this caches tool schemas;
    delimit_help describes individual tools at runtime.

    Side effects: action="register" /
    "clear" / "flush" mutate the cache; "status" / "delta" /
    "estimate" are read-only.

    Args:
        action: One of "status" (default), "register", "delta",
            "clear", "estimate", "flush", "usage". "usage" returns the
            durable tool-utilization + dormancy report (per-tool call
            counts, last_seen, and registry tools never called).
        tool_schemas: JSON array of tool schema objects (for register/
            estimate).
        tool_names: Comma-separated tool names (for delta).

    Returns:
        Dict with the action result (stats, delta names, estimate,
        usage/dormancy summary, etc).
    """
    from ai.toolcard_cache import get_cache
    cache = get_cache()

    if action == "status":
        r = cache.get_stats()
    elif action == "register":
        if not tool_schemas:
            return _with_next_steps("toolcard_cache", {
                "error": "missing_param",
                "message": "register action requires tool_schemas (JSON array of tool schema objects)"
            })
        try:
            schemas = json.loads(tool_schemas)
        except json.JSONDecodeError as e:
            return _with_next_steps("toolcard_cache", {
                "error": "invalid_json", "message": str(e)
            })
        r = cache.register_tools(schemas)
    elif action == "delta":
        names = [n.strip() for n in (tool_names or "").split(",") if n.strip()]
        r = cache.get_delta(names)
    elif action == "clear":
        r = cache.clear()
    elif action == "estimate":
        if not tool_schemas:
            return _with_next_steps("toolcard_cache", {
                "error": "missing_param",
                "message": "estimate action requires tool_schemas (JSON array of tool schema objects)"
            })
        try:
            schemas = json.loads(tool_schemas)
        except json.JSONDecodeError as e:
            return _with_next_steps("toolcard_cache", {
                "error": "invalid_json", "message": str(e)
            })
        r = cache.estimate_savings(schemas)
    elif action == "flush":
        r = cache.flush_session()
    elif action == "usage":
        # Durable tool utilization / dormancy report. record_call now persists
        # every call to ~/.delimit/tool_usage.jsonl; usage_summary aggregates
        # counts + last_seen and, given the registered-tool list, flags tools
        # never called as `dormant`. Mechanizes the dormant-tool audit.
        registry = None
        try:
            tm = getattr(mcp, "_tool_manager", None)
            if tm is not None:
                if hasattr(tm, "list_tools"):
                    registry = [getattr(t, "name", None) or t.get("name") for t in tm.list_tools()]
                elif hasattr(tm, "_tools"):
                    registry = list(tm._tools.keys())
            if registry:
                registry = sorted(n for n in registry if n)
        except Exception:
            registry = None
        r = cache.usage_summary(registry=registry)
    else:
        r = {"error": "unknown_action", "message": f"Unknown action: {action}. Use: status, register, delta, clear, estimate, flush, usage"}

    return _with_next_steps("toolcard_cache", r)

