            "2021-22": ("Nikola Jokic", "1610612743"), "2020-21": ("Nikola Jokic", "1610612743"),
            "2019-20": ("Giannis Antetokounmpo", "1610612749"), "2018-19": ("Giannis Antetokounmpo", "1610612749"),
