def get_action_details(action: str, action_type: str = "") -> dict:
        """
        Get complete action details including goal, result, and feedback structures.

        Args:
            action (str): The action name (e.g., '/turtle1/rotate_absolute')
            action_type (str): The action type (e.g., 'turtlesim/action/RotateAbsolute').
                Required. Call without action_type to get the available types back
                in the error (they are also listed by the interfaces service, not
                by get_actions(), which returns action *names*).

        Returns:
            dict: Contains complete action definition with goal, result, and feedback structures.
        """
        if not action or not action.strip():
            return {"error": "Action name cannot be empty"}

        with ws_manager:
            # Fetch the available action interfaces. We need them to suggest a
            # type when none was given, and to validate a supplied type before
            # querying its details: asking rosapi for the goal/result/feedback
            # of a non-existent type crashes the ROS 2 rosapi node, taking down
            # all rosapi services.
            interfaces_response = ws_manager.request(
                {
                    "op": "call_service",
                    "service": rosapi_service("interfaces"),
                    "type": rosapi_type("Interfaces"),
                    "args": {},
                    "id": f"get_interfaces_for_{action.replace('/', '_')}",
                }
            )
            interfaces_error = _check_response(interfaces_response)
            iface_values = _safe_get_values(interfaces_response)
            available = (
                [i for i in iface_values.get("interfaces", []) if "/action/" in i]
                if iface_values is not None
                else []
            )

            if not action_type or not action_type.strip():
                return {
                    "error": f"action_type is required for {action}",
                    "action": action,
                    "available_action_types": available,
                }

            # If the interfaces list is unavailable we cannot validate the type,
            # and we must not fall through to the detail services (a bad type
            # crashes rosapi). Report that distinctly from a genuine "not found".
            if interfaces_error:
                return {
                    "error": (
                        f"Cannot validate action_type for {action}: "
                        "the action interfaces service is unavailable"
                    ),
                    "action": action,
                    "action_type": action_type,
                }

            if action_type not in available:
                return {
                    "error": f"Action type '{action_type}' not found",
                    "action": action,
                    "action_type": action_type,
                    "available_action_types": available,
                }

            # Fetch goal, result, and feedback structures
            parts = {
                part: _fetch_action_part(ws_manager, action_type, part) for part in _ACTION_PARTS
            }

        if not any(parts.values()):
            return {
                "error": f"Action type {action_type} found but has no definition",
                "action": action,
                "action_type": action_type,
            }

        return {"action": action, "action_type": action_type, **parts}

def get_action_status(action_name: str) -> dict:
        """
        Get action status for a specific action name. Works only with ROS 2.

        Args:
            action_name (str): The action name (e.g., '/turtle1/rotate_absolute')

        Returns:
            dict: Contains action status information including active goals and their status.
        """
        if not action_name or not action_name.strip():
            return {"error": "Action name cannot be empty"}

        if not action_name.startswith("/"):
            action_name = f"/{action_name}"

        status_topic = f"{action_name}/_action/status"
        status_msg_type = "action_msgs/msg/GoalStatusArray"

        status_map = {
            0: "STATUS_UNKNOWN",
            1: "STATUS_ACCEPTED",
            2: "STATUS_EXECUTING",
            3: "STATUS_CANCELING",
            4: "STATUS_SUCCEEDED",
            5: "STATUS_CANCELED",
            6: "STATUS_ABORTED",
        }

        try:
            with ws_manager:
                send_error = ws_manager.send(
                    {
                        "op": "subscribe",
                        "topic": status_topic,
                        "type": status_msg_type,
                        "id": f"get_action_status_{action_name.replace('/', '_')}",
                    }
                )
                if send_error:
                    return {
                        "error": f"Failed to subscribe to status topic: {send_error}",
                        "action_name": action_name,
                    }

                response = ws_manager.receive(timeout=3.0)

                # Unsubscribe regardless of result
                ws_manager.send({"op": "unsubscribe", "topic": status_topic})

                if not response:
                    # An idle action server may not publish status; that is not
                    # an error, just no goals in flight.
                    return {
                        "action_name": action_name,
                        "active_goals": [],
                        "goal_count": 0,
                        "note": "No status published; the action is idle or not running",
                    }

                response_data = json.loads(response)

                if response_data.get("op") == "status" and response_data.get("level") == "error":
                    return {
                        "error": f"Action status error: {response_data.get('msg', 'Unknown error')}",
                        "action_name": action_name,
                    }

                if "msg" not in response_data or "status_list" not in response_data.get("msg", {}):
                    return {
                        "action_name": action_name,
                        "active_goals": [],
                        "goal_count": 0,
                    }

                active_goals = []
                for item in response_data["msg"]["status_list"]:
                    goal_info = item.get("goal_info", {})
                    status = item.get("status", -1)
                    stamp = goal_info.get("stamp", {})
                    active_goals.append(
                        {
                            "goal_id": goal_info.get("goal_id", {}).get("uuid", "unknown"),
                            "status": status,
                            "status_text": status_map.get(status, "UNKNOWN"),
                            "timestamp": f"{stamp.get('sec', 0)}.{stamp.get('nanosec', 0)}",
                        }
                    )

                return {
                    "action_name": action_name,
                    "active_goals": active_goals,
                    "goal_count": len(active_goals),
                }

        except json.JSONDecodeError as e:
            return {"error": f"Failed to parse status response: {e}"}
        except Exception as e:
            return {"error": f"Failed to get action status: {e}", "action_name": action_name}

async def send_action_goal(
        action_name: str,
        action_type: str,
        goal: dict,
        timeout: float = None,  # type: ignore[assignment]  # See issue #140
        ctx: Context = None,  # type: ignore[assignment]  # See issue #140
    ) -> dict:
        """
        Send a goal to a ROS action server. Works only with ROS 2.

        Args:
            action_name (str): The name of the action to call (e.g., '/turtle1/rotate_absolute')
            action_type (str): The type of the action (e.g., 'turtlesim/action/RotateAbsolute')
            goal (dict): The goal message to send
            timeout (float): Timeout for action completion in seconds. If None, uses ws_manager.default_timeout.

        Returns:
            dict: Contains action response including goal_id, status, and result.
        """
        if not action_name or not action_name.strip():
            return {"error": "Action name cannot be empty"}
        if not action_type or not action_type.strip():
            return {"error": "Action type cannot be empty"}
        if not goal:
            return {"error": "Goal cannot be empty"}

        if not action_name.startswith("/"):
            action_name = f"/{action_name}"

        if timeout is None:
            timeout = ws_manager.default_timeout

        goal_id = f"goal_{int(time.time() * 1000)}_{uuid.uuid4().hex[:8]}"

        message = {
            "op": "send_action_goal",
            "id": goal_id,
            "action": action_name,
            "action_type": action_type,
            "args": goal,
            "feedback": True,
        }

        with ws_manager:
            send_error = ws_manager.send(message)
            if send_error:
                return {
                    "error": f"Failed to send action goal: {send_error}",
                    "action": action_name,
                    "success": False,
                }

            start_time = time.time()
            last_feedback = None
            feedback_count = 0

            while time.time() - start_time < timeout:
                remaining = timeout - (time.time() - start_time)
                response = ws_manager.receive(remaining)

                if not response:
                    continue

                try:
                    msg_data = json.loads(response)
                except json.JSONDecodeError:
                    continue

                if msg_data.get("op") == "action_result":
                    if ctx:
                        try:
                            await ctx.report_progress(
                                progress=feedback_count, total=None, message="Action completed"
                            )
                        except Exception:
                            pass
                    return {
                        "action": action_name,
                        "action_type": action_type,
                        "success": True,
                        "goal_id": goal_id,
                        "status": msg_data.get("status", "unknown"),
                        "result": msg_data.get("values", {}),
                    }

                if msg_data.get("op") == "action_feedback":
                    feedback_count += 1
                    last_feedback = msg_data
                    if ctx:
                        try:
                            await ctx.report_progress(
                                progress=feedback_count,
                                total=None,
                                message=f"Feedback #{feedback_count}: {str(msg_data.get('values', {}))[:100]}",
                            )
                        except Exception:
                            pass

        # Timeout
        result = {
            "action": action_name,
            "action_type": action_type,
            "success": False,
            "goal_id": goal_id,
            "error": f"Action timed out after {timeout} seconds",
        }
        if last_feedback:
            result["last_feedback"] = last_feedback.get("values", {})
            result["feedback_count"] = feedback_count
        return result

def cancel_action_goal(action_name: str, goal_id: str) -> dict:
        """
        Cancel a specific action goal. Works only with ROS 2.

        Args:
            action_name (str): The name of the action (e.g., '/turtle1/rotate_absolute')
            goal_id (str): The goal ID to cancel

        Returns:
            dict: Contains cancellation status and result.
        """
        if not action_name or not action_name.strip():
            return {"error": "Action name cannot be empty"}
        if not goal_id or not goal_id.strip():
            return {"error": "Goal ID cannot be empty"}

        if not action_name.startswith("/"):
            action_name = f"/{action_name}"

        with ws_manager:
            send_error = ws_manager.send(
                {
                    "op": "cancel_action_goal",
                    "id": goal_id,
                    "action": action_name,
                }
            )
            if send_error:
                return {
                    "error": f"Failed to send cancel request: {send_error}",
                    "action": action_name,
                    "goal_id": goal_id,
                }

        # success here confirms the request was sent, not that the server
        # accepted it — the action may still be executing.
        return {
            "action": action_name,
            "goal_id": goal_id,
            "success": True,
            "note": "Cancel request sent; the action may still be executing",
        }

def get_parameter(name: str) -> dict:
        """
        Get a single ROS parameter value by name. Works only with ROS 2.

        Args:
            name (str): The parameter name (e.g., '/turtlesim:background_b')

        Returns:
            dict: Contains parameter value and metadata, or error message if parameter not found.
        """
        if not name or not name.strip():
            return {"error": "Parameter name cannot be empty"}

        # Check if parameter exists first to avoid unnecessary calls
        # (This uses get_param which is safe, unlike has_param which crashes)
        # The response is returned if parameter exists, so we can reuse it
        exists, reason, response = _safe_check_parameter_exists(name, ws_manager)
        if not exists:
            return {
                "name": name,
                "value": "",
                "successful": False,
                "reason": reason or f"Parameter {name} does not exist",
                "exists": False,
            }

        # We already have the response from the existence check, so process it
        # Handle string responses (fallback for malformed responses)
        if isinstance(response, str):
            return {
                "name": name,
                "value": "",
                "successful": False,
                "reason": f"Unexpected response format: {response}",
            }

        # Process the response - parameter exists, so extract the value
        if response and "values" in response:
            result_data = response["values"]
            if isinstance(result_data, dict):
                value = result_data.get("value", "")
                successful = result_data.get("successful", False) or bool(value)
                reason = result_data.get("reason", "")
                return {
                    "name": name,
                    "value": value,
                    "successful": successful,
                    "reason": reason,
                }
        elif response and "result" in response:
            result_data = response["result"]
            if isinstance(result_data, dict):
                value = result_data.get("value", "")
                successful = result_data.get("successful", False) or bool(value)
                reason = result_data.get("reason", "")
                return {
                    "name": name,
                    "value": value,
                    "successful": successful,
                    "reason": reason,
                }
            else:
                # Direct value in result
                return {
                    "name": name,
                    "value": str(result_data) if result_data is not None else "",
                    "successful": True,
                    "reason": "",
                }

        # Fallback for unexpected response format
        error_msg = (
            _extract_error(response) if response and isinstance(response, dict) else "No response"
        )
        return {"error": f"Failed to get parameter {name}: {error_msg}"}

def set_parameter(name: str, value: str) -> dict:
        """
        Set a single ROS parameter value. Works only with ROS 2.

        Args:
            name (str): The parameter name (e.g., '/turtlesim:background_b')
            value (str): The parameter value to set

        Returns:
            dict: Contains success status and metadata, or error message if failed.
        """
        if not name or not name.strip():
            return {"error": "Parameter name cannot be empty"}

        # Check if parameter exists first (set_param can create parameters, but checking
        # helps avoid issues and provides better error messages)
        exists, reason, _ = _safe_check_parameter_exists(name, ws_manager)
        # Note: We continue even if parameter doesn't exist, as set_param can create it

        message = {
            "op": "call_service",
            "service": rosapi_service("set_param"),
            "type": rosapi_type("SetParam"),
            "args": {"name": name, "value": value},
            "id": f"set_param_{name.replace('/', '_').replace(':', '_')}",
        }

        try:
            with ws_manager:
                response = ws_manager.request(message)
        except Exception as e:
            # Catch any exceptions to prevent crashes
            return {
                "name": name,
                "value": value,
                "successful": False,
                "reason": f"Error setting parameter: {str(e)}",
            }

        # Handle string responses (fallback for malformed responses)
        if isinstance(response, str):
            return {
                "name": name,
                "value": value,
                "successful": False,
                "reason": f"Unexpected response format: {response}",
            }

        if response and "values" in response:
            result_data = response["values"]
            if isinstance(result_data, dict):
                successful = result_data.get("successful", True)  # Default to True if not specified
                return {
                    "name": name,
                    "value": value,
                    "successful": successful,
                    "reason": result_data.get("reason", ""),
                }
        elif response and "result" in response:
            result_data = response["result"]
            if isinstance(result_data, dict):
                successful = result_data.get("successful", True)  # Default to True if not specified
                return {
                    "name": name,
                    "value": value,
                    "successful": successful,
                    "reason": result_data.get("reason", ""),
                }
            else:
                # Direct result (boolean or other)
                return {
                    "name": name,
                    "value": value,
                    "successful": bool(result_data) if result_data is not None else True,
                    "reason": "",
                }

        # Fallback for unexpected response format
        error_msg = (
            _extract_error(response) if response and isinstance(response, dict) else "No response"
        )
        return {"error": f"Failed to set parameter {name}: {error_msg}"}

def delete_parameter(name: str) -> dict:
        """
        Delete a ROS parameter. Works only with ROS 2.

        Args:
            name (str): The parameter name (e.g., '/turtlesim:background_b')

        Returns:
            dict: Contains success status and metadata, or error message if failed.
        """
        if not name or not name.strip():
            return {"error": "Parameter name cannot be empty"}

        # Check if parameter exists first to avoid unnecessary calls
        exists, reason, _ = _safe_check_parameter_exists(name, ws_manager)
        if not exists:
            return {
                "name": name,
                "successful": False,
                "reason": reason or f"Parameter {name} does not exist",
                "exists": False,
            }

        message = {
            "op": "call_service",
            "service": rosapi_service("delete_param"),
            "type": rosapi_type("DeleteParam"),
            "args": {"name": name},
            "id": f"delete_param_{name.replace('/', '_').replace(':', '_')}",
        }

        try:
            with ws_manager:
                response = ws_manager.request(message)
        except Exception as e:
            # Catch any exceptions to prevent crashes
            return {
                "name": name,
                "successful": False,
                "reason": f"Error deleting parameter: {str(e)}",
            }

        # Handle string responses (fallback for malformed responses)
        if isinstance(response, str):
            return {
                "name": name,
                "successful": False,
                "reason": f"Unexpected response format: {response}",
            }

        if response and "values" in response:
            result_data = response["values"]
            if isinstance(result_data, dict):
                # ROS 1 rosapi delete_param returns {"values": {}, "result": true} on
                # success, so when "successful" is absent inside values, fall back to
                # the top-level "result" field.
                if "successful" in result_data:
                    successful = bool(result_data["successful"])
                else:
                    successful = bool(response.get("result"))
                reason = result_data.get("reason", "")
                return {
                    "name": name,
                    "successful": successful,
                    "reason": reason,
                }
        elif response and "result" in response:
            result_data = response["result"]
            if isinstance(result_data, dict):
                successful = result_data.get("successful", False)
                reason = result_data.get("reason", "")
                return {
                    "name": name,
                    "successful": successful,
                    "reason": reason,
                }
            elif result_data:
                # Direct boolean result
                return {
                    "name": name,
                    "successful": bool(result_data),
                    "reason": "",
                }

        # Fallback for unexpected response format
        error_msg = (
            _extract_error(response) if response and isinstance(response, dict) else "No response"
        )
        return {"error": f"Failed to delete parameter {name}: {error_msg}"}

def get_parameters(node_name: str) -> dict:
        """
        Get list of all ROS parameter names for a specific node. Works only with ROS 2.

        Args:
            node_name (str): The node name (e.g., '/turtlesim')

        Returns:
            dict: Contains list of all parameter names for the node, or error message if failed.
        """
        if not node_name or not node_name.strip():
            return {"error": "Node name cannot be empty"}

        # Normalize node name (ensure it starts with /)
        normalized_node = node_name.strip()
        if not normalized_node.startswith("/"):
            normalized_node = f"/{normalized_node}"

        # Remove trailing slash if present
        if normalized_node.endswith("/") and len(normalized_node) > 1:
            normalized_node = normalized_node[:-1]

        service_name = f"{normalized_node}/list_parameters"

        message = {
            "op": "call_service",
            "service": service_name,
            "type": "rcl_interfaces/srv/ListParameters",
            "args": {},
            "id": f"get_parameters_{normalized_node.replace('/', '_')}",
        }

        try:
            with ws_manager:
                response = ws_manager.request(message)
        except Exception as e:
            # Catch any exceptions to prevent crashes
            return {"error": f"Failed to get parameters for node {normalized_node}: {str(e)}"}

        # Handle string responses (fallback for malformed responses)
        if isinstance(response, str):
            return {
                "error": f"Failed to get parameters for node {normalized_node}: Unexpected response format: {response}"
            }

        # Check for timeout or connection errors
        if not response:
            return {
                "error": f"Failed to get parameters for node {normalized_node}: No response or timeout from rosbridge"
            }

        # Check for explicit error in response
        if isinstance(response, dict) and "error" in response:
            error_msg = response.get("error", "Service call failed")
            return {"error": f"Failed to get parameters for node {normalized_node}: {error_msg}"}

        # Check for service response errors first
        if response and "result" in response and not response["result"]:
            # Service call failed - return error with details from values
            error_msg = _extract_error(response)
            return {"error": f"Failed to get parameters for node {normalized_node}: {error_msg}"}

        # Extract parameter names from response
        names = []
        if response and "values" in response:
            result_data = response["values"]
            if isinstance(result_data, dict):
                # Check for result.names structure
                result_obj = result_data.get("result", {})
                if isinstance(result_obj, dict):
                    names = result_obj.get("names", [])
                else:
                    # Try direct names field
                    names = result_data.get("names", [])
        elif response and "result" in response:
            result_data = response["result"]
            if isinstance(result_data, dict):
                # Check for result.names structure
                result_obj = result_data.get("result", {})
                if isinstance(result_obj, dict):
                    names = result_obj.get("names", [])
                else:
                    names = result_data.get("names", [])

        # Format parameter names with node prefix
        formatted_names = [f"{normalized_node}:{name}" for name in names]

        return {
            "node": normalized_node,
            "parameters": formatted_names,
            "parameter_count": len(formatted_names),
        }

def get_parameter_details(name: str) -> dict:
        """
        Get comprehensive details about a specific ROS parameter including value, type, and metadata. Works only with ROS 2.

        Args:
            name (str): The parameter name (e.g., '/turtlesim:background_r')

        Returns:
            dict: Contains detailed parameter information or error details.
        """
        # Validate input
        if not name or not name.strip():
            return {"error": "Parameter name cannot be empty"}

        # Helper to create error response
        def _error_response(reason: str) -> dict:
            return {
                "name": name,
                "value": "",
                "type": "unknown",
                "exists": False,
                "description": "",
                "node": name.split(":")[0] if ":" in name else "",
                "parameter": name.split(":")[1] if ":" in name else name,
                "reason": reason,
            }

        # Check if parameter exists first
        exists, reason, value_response = _safe_check_parameter_exists(name, ws_manager)
        if not exists:
            return _error_response(reason or f"Parameter {name} does not exist")

        # If we got a response from the existence check, use it directly
        # Otherwise, make a new call (shouldn't happen, but safety check)
        if value_response is None:
            value_message = {
                "op": "call_service",
                "service": rosapi_service("get_param"),
                "type": rosapi_type("GetParam"),
                "args": {"name": name},
                "id": f"get_param_details_{name.replace('/', '_').replace(':', '_')}",
            }

            try:
                with ws_manager:
                    value_response = ws_manager.request(value_message)
            except Exception as e:
                return _error_response(f"Error getting parameter details: {str(e)}")

        # Handle string responses (fallback for malformed responses)
        if isinstance(value_response, str):
            return _error_response(f"Unexpected response format: {value_response}")

        if not value_response:
            return _error_response("No response from service")

        # Handle different response formats
        value_data = None
        param_value = ""
        param_successful = False
        reason = ""

        if "values" in value_response:
            value_data = value_response["values"]
            if isinstance(value_data, dict):
                param_value = value_data.get("value", "")
                param_successful = value_data.get("successful", False) or bool(param_value)
                reason = value_data.get("reason", "")
        elif "result" in value_response:
            result_data = value_response["result"]
            if isinstance(result_data, dict):
                value_data = result_data
                param_value = result_data.get("value", "")
                param_successful = result_data.get("successful", False) or bool(param_value)
                reason = result_data.get("reason", "")
            else:
                # Direct value
                param_value = str(result_data) if result_data is not None else ""
                param_successful = bool(param_value)

        # Parameter should exist at this point (we checked earlier), but handle edge cases
        if not param_successful and not param_value:
            return _error_response(reason or f"Parameter {name} does not exist")

        # Get parameter type
        type_message = {
            "op": "call_service",
            "service": rosapi_service("describe_parameters"),
            "type": "rcl_interfaces/DescribeParameters",
            "args": {"names": [name]},
            "id": f"describe_param_details_{name.replace('/', '_').replace(':', '_')}",
        }

        try:
            with ws_manager:
                type_response = ws_manager.request(type_message)
        except Exception:
            # If describe_parameters fails, continue with type inference from value
            type_response = None

        param_type = "unknown"
        param_description = ""

        # Handle string responses (fallback for malformed responses)
        if isinstance(type_response, str):
            # Continue with type inference from value
            pass
        elif type_response is None:
            # Service call failed, continue with type inference from value
            pass
        elif type_response and isinstance(type_response, dict):
            if "values" in type_response:
                result_data = type_response["values"]
                if isinstance(result_data, dict):
                    descriptors = result_data.get("descriptors", [])
                    if descriptors and len(descriptors) > 0:
                        descriptor = descriptors[0]
                        param_type = descriptor.get("type", "unknown")
                        param_description = descriptor.get("description", "")
            elif "result" in type_response and type_response["result"]:
                result_data = type_response["result"]
                if isinstance(result_data, dict):
                    descriptors = result_data.get("descriptors", [])
                    if descriptors and len(descriptors) > 0:
                        descriptor = descriptors[0]
                        param_type = descriptor.get("type", "unknown")
                        param_description = descriptor.get("description", "")

        # Fallback: Try to infer type from value
        if param_type == "unknown" and param_value:
            try:
                clean_value = param_value.strip('"')
                if clean_value.lower() in ["true", "false"]:
                    param_type = "bool"
                elif clean_value.isdigit() or (
                    clean_value.startswith("-") and clean_value[1:].isdigit()
                ):
                    param_type = "int"
                elif "." in clean_value and clean_value.replace(".", "").replace("-", "").isdigit():
                    param_type = "float"
                elif param_value.startswith('"') and param_value.endswith('"'):
                    param_type = "string"
                elif clean_value == "":
                    param_type = "string"
                else:
                    param_type = "string"
            except Exception:
                param_type = "string"

        return {
            "name": name,
            "value": param_value,
            "type": param_type,
            "exists": param_successful,
            "description": param_description,
            "node": name.split(":")[0] if ":" in name else "",
            "parameter": name.split(":")[1] if ":" in name else name,
        }

def get_verified_robot_spec(name: str) -> dict:
        """
        Load pre-defined specifications and additional context for a verified robot model.

        This is OPTIONAL - only for a small set of pre-verified robot models stored in the repository.
        Use get_verified_robots_list() first to check if a spec exists.
        If no spec exists for your robot, simply use connect_to_robot() directly.

        Args:
            name (str): The exact robot model name from the verified list.

        Returns:
            dict: The robot specification with type, prompts, and additional context.
        """
        robot_config = get_verified_robot_spec_util(name)

        if len(robot_config) > 1:
            return {
                "error": f"Multiple configurations found for robot '{name}'. Please specify a more precise name."
            }
        elif not robot_config:
            return {
                "error": f"No configuration found for robot '{name}'. Please check the name and try again. Or you can set the IP/port manually using the 'connect_to_robot' tool."
            }
        return {"robot_config": robot_config}

def detect_ros_version() -> dict:
        """
        Detects the ROS version and distro via rosbridge WebSocket.

        Returns:
            dict: {'version': '1' or '2', 'distro': '<distro name>'} or error info.
        """
        try:
            version = get_ros_version()
            distro = get_distro()
            return {
                "version": "1" if version == RosVersion.ROS1 else "2",
                "distro": distro,
            }
        except DetectionError as e:
            return {"error": f"Could not detect ROS version: {e}"}

def get_service_type(service: str) -> dict:
        """
        Get the service type for a specific service.

        Args:
            service (str): The service name (e.g., '/rosapi/topics')

        Returns:
            dict: Contains the service type,
                or an error message if service doesn't exist.
        """
        if not service or not service.strip():
            return {"error": "Service name cannot be empty"}

        message = {
            "op": "call_service",
            "service": rosapi_service("service_type"),
            "type": rosapi_type("ServiceType"),
            "args": {"service": service},
            "id": f"get_service_type_request_{service.replace('/', '_')}",
        }

        with ws_manager:
            response = ws_manager.request(message)

        error = _check_response(response)
        if error:
            return error

        values = _safe_get_values(response)
        if values is not None:
            service_type = values.get("type", "")
            if service_type:
                return {"service": service, "type": service_type}
            return {"error": f"Service {service} does not exist or has no type"}
        return {"error": f"Failed to get type for service {service}"}

def get_service_details(service: str) -> dict:
        """
        Get complete service details including request/response structures and provider nodes.

        Args:
            service (str): The service name (e.g., '/rosapi/topics')

        Returns:
            dict: Contains complete service definition with request and response structures,
                provider nodes, and provider count.
        """
        # Validate input
        if not service or not service.strip():
            return {"error": "Service name cannot be empty"}

        result = {
            "service": service,
            "type": "",
            "request": {},
            "response": {},
            "providers": [],
            "provider_count": 0,
        }

        with ws_manager:
            # First get the service type
            type_message = {
                "op": "call_service",
                "service": rosapi_service("service_type"),
                "type": rosapi_type("ServiceType"),
                "args": {"service": service},
                "id": f"get_service_type_{service.replace('/', '_')}",
            }

            type_response = ws_manager.request(type_message)
            error = _check_response(type_response)
            if error:
                return error
            type_values = _safe_get_values(type_response)
            if type_values is not None:
                service_type = type_values.get("type", "")
                if service_type:
                    result["type"] = service_type
                else:
                    return {"error": f"Service {service} does not exist or has no type"}
            else:
                return {"error": f"Failed to get type for service {service}"}

            # Get request details
            request_message = {
                "op": "call_service",
                "service": rosapi_service("service_request_details"),
                "type": rosapi_type("ServiceRequestDetails"),
                "args": {"type": result["type"]},
                "id": f"get_service_details_request_{result['type'].replace('/', '_')}",
            }

            request_response = ws_manager.request(request_message)
            request_values = _safe_get_values(request_response)
            if request_values is not None:
                typedefs = request_values.get("typedefs", [])
                if typedefs:
                    for typedef in typedefs:
                        field_names = typedef.get("fieldnames", [])
                        field_types = typedef.get("fieldtypes", [])
                        fields = {}
                        for name, ftype in zip(field_names, field_types):
                            fields[name] = ftype
                        result["request"] = {"fields": fields, "field_count": len(fields)}

            # Get response details
            response_message = {
                "op": "call_service",
                "service": rosapi_service("service_response_details"),
                "type": rosapi_type("ServiceResponseDetails"),
                "args": {"type": result["type"]},
                "id": f"get_service_details_response_{result['type'].replace('/', '_')}",
            }

            response_response = ws_manager.request(response_message)
            response_values = _safe_get_values(response_response)
            if response_values is not None:
                typedefs = response_values.get("typedefs", [])
                if typedefs:
                    for typedef in typedefs:
                        field_names = typedef.get("fieldnames", [])
                        field_types = typedef.get("fieldtypes", [])
                        fields = {}
                        for name, ftype in zip(field_names, field_types):
                            fields[name] = ftype
                        result["response"] = {"fields": fields, "field_count": len(fields)}

            # Get service providers
            provider_message = {
                "op": "call_service",
                "service": rosapi_service("service_node"),
                "type": rosapi_type("ServiceNode"),
                "args": {"service": service},
                "id": f"get_service_providers_request_{service.replace('/', '_')}",
            }

            provider_response = ws_manager.request(provider_message)
            providers = []

            # Handle different response formats safely
            provider_values = _safe_get_values(provider_response)
            if provider_values is not None:
                node = provider_values.get("node", "")
                if node:
                    providers = [node]
            elif (
                provider_response
                and isinstance(provider_response, dict)
                and isinstance(provider_response.get("result"), dict)
            ):
                node = provider_response["result"].get("node", "")
                if node:
                    providers = [node]

            result["providers"] = providers
            result["provider_count"] = len(providers)

        # Check if we got any data
        if not result["request"] and not result["response"]:
            return {"error": f"Service {service} not found or has no definition"}

        # Add note about field name format
        result["note"] = (
            "Field names shown above are formatted for rosbridge (leading underscores removed). "
            "Use these exact field names when calling call_service()."
        )

        return result

def get_topic_type(topic: str) -> dict:
        """
        Get the message type for a specific topic.

        Args:
            topic (str): The topic name (e.g., '/cmd_vel')

        Returns:
            dict: Contains the 'type' field with the message type,
                or an error message if topic doesn't exist.
        """
        # Validate input
        if not topic or not topic.strip():
            return {"error": "Topic name cannot be empty"}

        # rosbridge service call to get topic type
        message = {
            "op": "call_service",
            "service": rosapi_service("topic_type"),
            "type": rosapi_type("TopicType"),
            "args": {"topic": topic},
            "id": f"get_topic_type_request_{topic.replace('/', '_')}",
        }

        # Request topic type from rosbridge
        with ws_manager:
            response = ws_manager.request(message)

        error = _check_response(response)
        if error:
            return error

        # Return topic type if present
        values = _safe_get_values(response)
        if values is not None:
            topic_type = values.get("type", "")
            if topic_type:
                return {"topic": topic, "type": topic_type}
            return {"error": f"Topic {topic} does not exist or has no type"}
        return {"error": f"Failed to get type for topic {topic}"}

def get_message_details(message_type: str) -> dict:
        """
        Get the complete structure/definition of a message type.

        Args:
            message_type (str): The message type (e.g., 'geometry_msgs/Twist')

        Returns:
            dict: Contains the message structure with field names and types,
                or an error message if the message type doesn't exist.
        """
        # Validate input
        if not message_type or not message_type.strip():
            return {"error": "Message type cannot be empty"}

        # rosbridge service call to get message details
        message = {
            "op": "call_service",
            "service": rosapi_service("message_details"),
            "type": rosapi_type("MessageDetails"),
            "args": {"type": message_type},
            "id": f"get_message_details_request_{message_type.replace('/', '_')}",
        }

        # Request message details from rosbridge
        with ws_manager:
            response = ws_manager.request(message)

        error = _check_response(response)
        if error:
            return error

        # Return message structure if present
        values = _safe_get_values(response)
        if values is not None:
            typedefs = values.get("typedefs", [])
            if typedefs:
                # Parse the structure into a more readable format
                structure = {}
                for typedef in typedefs:
                    type_name = typedef.get("type", message_type)
                    field_names = typedef.get("fieldnames", [])
                    field_types = typedef.get("fieldtypes", [])

                    fields = {}
                    for name, ftype in zip(field_names, field_types):
                        fields[name] = ftype

                    structure[type_name] = {"fields": fields, "field_count": len(fields)}

                return {"message_type": message_type, "structure": structure}
            else:
                return {"error": f"Message type {message_type} not found or has no definition"}
        else:
            return {"error": f"Failed to get details for message type {message_type}"}

def subscribe_once(
        topic: str = "",
        msg_type: str = "",
        expects_image: str = "auto",
        timeout: float = None,  # type: ignore[assignment]  # See issue #140
        queue_length: int = None,  # type: ignore[assignment]  # See issue #140
        throttle_rate_ms: int = None,  # type: ignore[assignment]  # See issue #140
    ):
        """
        Subscribe to a given ROS topic via rosbridge and return the first message received.

        Args:
            topic (str): The ROS topic name (e.g., "/cmd_vel", "/joint_states").
            msg_type (str): The ROS message type (e.g., "geometry_msgs/Twist").
            timeout (float): Timeout in seconds. If None, uses ws_manager.default_timeout.
            queue_length (int): How many messages to buffer before dropping old ones. Must be ≥ 1. Default is 1.
            throttle_rate_ms (int): Minimum interval between messages in milliseconds. Must be ≥ 0. Default is 0 (no throttling).
            expects_image (str): Hint about whether to expect image data.
                - "true": prioritize image parsing (use for sensor_msgs/Image topics)
                - "false": skip image detection for faster processing (use for non-image topics)
                - "auto": auto-detect based on message fields (default)

        Returns:
            dict:
                - {"msg": <parsed ROS message>} if successful
                - {"error": "<error message>"} if subscription or timeout fails
        """
        # Validate critical args before attempting subscription
        if not topic or not msg_type:
            return {"error": "Missing required arguments: topic and msg_type must be provided."}

        # Set defaults for optional parameters
        if timeout is None:
            timeout = ws_manager.default_timeout
        if queue_length is None:
            queue_length = 1  # Default queue length
        if throttle_rate_ms is None:
            throttle_rate_ms = 0  # Default: no throttling

        # Validate and convert parameters (handle string inputs from MCP)
        try:
            timeout = float(timeout)
            if timeout < 0:
                return {"error": "timeout must be >= 0"}
        except (ValueError, TypeError):
            return {"error": "timeout must be a number"}

        try:
            queue_length = int(queue_length)
            if queue_length < 1:
                return {"error": "queue_length must be an integer ≥ 1"}
        except (ValueError, TypeError):
            return {"error": "queue_length must be an integer"}

        try:
            throttle_rate_ms = int(throttle_rate_ms)
            if throttle_rate_ms < 0:
                return {"error": "throttle_rate_ms must be an integer ≥ 0"}
        except (ValueError, TypeError):
            return {"error": "throttle_rate_ms must be an integer"}

        # Construct the rosbridge subscribe message
        subscribe_msg: dict = {
            "op": "subscribe",
            "topic": topic,
            "type": msg_type,
            "queue_length": queue_length,
            "throttle_rate": throttle_rate_ms,
        }

        actual_timeout = timeout

        # Subscribe and wait for the first message
        with ws_manager:
            # Send subscription request
            send_error = ws_manager.send(subscribe_msg)
            if send_error:
                return {"error": f"Failed to subscribe: {send_error}"}

            # Loop until we receive the first message or timeout
            end_time = time.time() + actual_timeout
            while time.time() < end_time:
                response = ws_manager.receive(timeout=0.5)  # non-blocking small timeout
                if response is None:
                    continue  # idle timeout: no frame this tick

                # Convert string hint to boolean for parse_input
                expects_image_bool = convert_expects_image_hint(expects_image)

                # Parse input with expects_image hint
                msg_data, was_parsed_as_image = parse_input(response, expects_image_bool)

                if not msg_data:
                    continue  # parsing failed or empty

                # Check for status errors from rosbridge
                if msg_data.get("op") == "status" and msg_data.get("level") == "error":
                    return {"error": f"Rosbridge error: {msg_data.get('msg', 'Unknown error')}"}

                # Check for the first published message
                if msg_data.get("op") == "publish" and msg_data.get("topic") == topic:
                    # Unsubscribe before returning the message
                    unsubscribe_msg = {"op": "unsubscribe", "topic": topic}
                    ws_manager.send(unsubscribe_msg)
                    # Return appropriate message based on whether image was actually parsed
                    if was_parsed_as_image:
                        image_path = "./camera/received_image.jpeg"
                        if os.path.exists(image_path):
                            img = PILImage.open(image_path)
                            image_content = _encode_image_to_imagecontent(img)
                            return ToolResult(
                                content=[
                                    image_content,
                                    TextContent(
                                        type="text",
                                        text=f"Image saved to {image_path}. Use view_saved_image() to re-view it.",
                                    ),
                                ]
                            )
                        return {"error": "Image received but file not found on disk"}
                    else:
                        return {"msg": msg_data.get("msg", {})}

            # Timeout - unsubscribe and return error
            unsubscribe_msg = {"op": "unsubscribe", "topic": topic}
            ws_manager.send(unsubscribe_msg)
            return {"error": "Timeout waiting for message from topic"}

def subscribe_for_duration(
        topic: str = "",
        msg_type: str = "",
        duration: float = 5.0,
        max_messages: int = 100,
        queue_length: int = None,  # type: ignore[assignment]  # See issue #140
        throttle_rate_ms: int = None,  # type: ignore[assignment]  # See issue #140
        expects_image: str = "auto",
    ):
        """
        Subscribe to a ROS topic via rosbridge for a fixed duration and collect messages.

        Args:
            topic (str): ROS topic name (e.g. "/cmd_vel", "/joint_states")
            msg_type (str): ROS message type (e.g. "geometry_msgs/Twist")
            duration (float): How long (seconds) to listen for messages
            max_messages (int): Maximum number of messages to collect before stopping
            queue_length (int): How many messages to buffer before dropping old ones. Must be ≥ 1. Default is 1.
            throttle_rate_ms (int): Minimum interval between messages in milliseconds. Must be ≥ 0. Default is 0 (no throttling).
            expects_image (str): Hint about whether to expect image data.
                - "true": prioritize image parsing (use for sensor_msgs/Image topics)
                - "false": skip image detection for faster processing (use for non-image topics)
                - "auto": auto-detect based on message fields (default)

        Returns:
            dict:
                {
                    "topic": topic_name,
                    "collected_count": N,
                    "messages": [msg1, msg2, ...]
                }
        """
        # Validate critical args before subscribing
        if not topic or not msg_type:
            return {"error": "Missing required arguments: topic and msg_type must be provided."}

        # Set defaults for optional parameters
        if queue_length is None:
            queue_length = 1  # Default queue length
        if throttle_rate_ms is None:
            throttle_rate_ms = 0  # Default: no throttling

        # Validate and convert parameters
        try:
            duration = float(duration)
            if duration < 0:
                return {"error": "duration must be >= 0"}
        except (ValueError, TypeError):
            return {"error": "duration must be a number"}

        try:
            max_messages = int(max_messages)
            if max_messages < 1:
                return {"error": "max_messages must be an integer ≥ 1"}
        except (ValueError, TypeError):
            return {"error": "max_messages must be an integer"}

        # Validate and convert parameters (handle string inputs from MCP)
        try:
            queue_length = int(queue_length)
            if queue_length < 1:
                return {"error": "queue_length must be an integer ≥ 1"}
        except (ValueError, TypeError):
            return {"error": "queue_length must be an integer"}

        try:
            throttle_rate_ms = int(throttle_rate_ms)
            if throttle_rate_ms < 0:
                return {"error": "throttle_rate_ms must be an integer ≥ 0"}
        except (ValueError, TypeError):
            return {"error": "throttle_rate_ms must be an integer"}

        # Send subscription request
        subscribe_msg: dict = {
            "op": "subscribe",
            "topic": topic,
            "type": msg_type,
            "queue_length": queue_length,
            "throttle_rate": throttle_rate_ms,
        }

        with ws_manager:
            send_error = ws_manager.send(subscribe_msg)
            if send_error:
                return {"error": f"Failed to subscribe: {send_error}"}

            collected_messages = []
            status_errors = []
            end_time = time.time() + duration

            # Loop until duration expires or we hit max_messages
            while time.time() < end_time and len(collected_messages) < max_messages:
                response = ws_manager.receive(timeout=0.5)  # non-blocking small timeout
                if response is None:
                    continue  # idle timeout: no frame this tick

                # Convert string hint to boolean for parse_input
                expects_image_bool = convert_expects_image_hint(expects_image)

                # Parse input with expects_image hint
                msg_data, was_parsed_as_image = parse_input(response, expects_image_bool)

                if not msg_data:
                    continue  # parsing failed or empty

                # Check for status errors from rosbridge
                if msg_data.get("op") == "status" and msg_data.get("level") == "error":
                    status_errors.append(msg_data.get("msg", "Unknown error"))
                    continue

                # Check for published messages matching our topic
                if msg_data.get("op") == "publish" and msg_data.get("topic") == topic:
                    msg_index = len(collected_messages)
                    # Add message based on whether it was actually parsed as image
                    if was_parsed_as_image:
                        image_path = "./camera/received_image.jpeg"
                        if os.path.exists(image_path):
                            img = PILImage.open(image_path)
                            collected_messages.append(_encode_image_to_imagecontent(img))
                        else:
                            collected_messages.append(
                                TextContent(
                                    type="text",
                                    text=f"[Message {msg_index}] Image received but file not found on disk",
                                )
                            )
                    else:
                        collected_messages.append(
                            TextContent(
                                type="text",
                                text=json.dumps(msg_data.get("msg", {})),
                            )
                        )

            # Unsubscribe when done
            unsubscribe_msg = {"op": "unsubscribe", "topic": topic}
            ws_manager.send(unsubscribe_msg)

        # Build summary as TextContent, then append all collected content blocks
        summary = TextContent(
            type="text",
            text=json.dumps(
                {
                    "topic": topic,
                    "collected_count": len(collected_messages),
                    "status_errors": status_errors,
                }
            ),
        )
        return ToolResult(content=[summary] + collected_messages)

def publish_for_durations(
        topic: str = "",
        msg_type: str = "",
        messages: list[dict] = [],
        durations: list[float] = [],
        rate_hz: float = 0,
    ) -> dict:
        """
        Publish a sequence of messages to a given ROS topic for specified durations.

        Args:
            topic (str): ROS topic name (e.g., "/cmd_vel")
            msg_type (str): ROS message type (e.g., "geometry_msgs/msg/Twist")
            messages (list[dict]): A list of message dictionaries (ROS-compatible payloads)
            durations (list[float]): A list of durations (seconds) to hold each message
            rate_hz (float): Publishing rate in Hz. 0 = publish once then wait (default).
                             >0 = publish repeatedly at this rate for the duration.

        Returns:
            dict:
                {
                    "success": True,
                    "published_count": <number of publishes>,
                    "topic": topic,
                    "msg_type": msg_type,
                    "rate_hz": rate_hz
                }
                OR {"error": "<error message>"} if something failed
        """
        # Neutralize the mutable default arguments
        messages = list(messages)
        durations = list(durations)

        # topic and msg_type really are required
        if not topic or not msg_type:
            return {"error": "Missing required arguments: topic and msg_type must be provided."}

        # Validate rate_hz
        if rate_hz < 0:
            return {"error": "rate_hz must be >= 0"}
        if rate_hz > 100:
            return {"error": "rate_hz must be <= 100"}

        # Empty is allowed: nothing to publish
        if not messages and not durations:
            return {
                "success": True,
                "published_count": 0,
                "total_messages": 0,
                "topic": topic,
                "msg_type": msg_type,
                "rate_hz": rate_hz,
                "errors": [],
            }

        # But one empty and the other not is an error
        if len(messages) != len(durations):
            return {"error": "messages and durations must have the same length"}

        # Optional: validate durations
        if any(d < 0 for d in durations):
            return {"error": "durations must be >= 0"}

        published_count = 0
        errors = []

        with ws_manager:
            advertise_msg = {"op": "advertise", "topic": topic, "type": msg_type}
            send_error = ws_manager.send(advertise_msg)
            if send_error:
                return {"error": f"Failed to advertise topic: {send_error}"}

            try:
                # publish loop
                for i, (msg, duration) in enumerate(zip(messages, durations)):
                    publish_msg = {"op": "publish", "topic": topic, "msg": msg}

                    if rate_hz > 0 and duration > 0:
                        # Streaming mode: publish repeatedly at rate_hz for duration
                        interval = 1.0 / rate_hz
                        end_time = time.time() + duration
                        next_time = time.time() + interval
                        while time.time() < end_time:
                            send_error = ws_manager.send(publish_msg)
                            if send_error:
                                errors.append(f"Message {i + 1}: {send_error}")
                                break
                            published_count += 1
                            # Sleep until next target time to compensate for send overhead
                            sleep_time = next_time - time.time()
                            if sleep_time > 0:
                                time.sleep(sleep_time)
                            next_time += interval
                    else:
                        # Original mode: publish once, then wait
                        send_error = ws_manager.send(publish_msg)
                        if send_error:
                            errors.append(f"Message {i + 1}: {send_error}")
                            continue

                        response = ws_manager.receive(timeout=1.0)
                        if response:
                            try:
                                msg_data = json.loads(response)
                                if (
                                    msg_data.get("op") == "status"
                                    and msg_data.get("level") == "error"
                                ):
                                    errors.append(
                                        f"Message {i + 1}: {msg_data.get('msg', 'Unknown error')}"
                                    )
                                    continue
                            except json.JSONDecodeError:
                                pass

                        published_count += 1
                        if duration:
                            time.sleep(duration)

            finally:
                # always unadvertise
                ws_manager.send({"op": "unadvertise", "topic": topic})

        return {
            "success": True,
            "published_count": published_count,
            "total_messages": len(messages),
            "topic": topic,
            "msg_type": msg_type,
            "rate_hz": rate_hz,
            "errors": errors,
        }

def publish_once(topic: str = "", msg_type: str = "", msg: dict = {}) -> dict:
        """
        Publish a single message to a ROS topic via rosbridge.

        Args:
            topic (str): ROS topic name (e.g., "/cmd_vel")
            msg_type (str): ROS message type (e.g., "geometry_msgs/msg/Twist")
            msg (dict): Message payload as a dictionary

        Returns:
            dict:
                - {"success": True} if sent without errors
                - {"error": "<error message>"} if connection/send failed
        """
        # Neutralize the mutable default arguments
        msg = dict(msg)

        # Validate ws_manager is available
        if ws_manager is None:
            return {"error": "WebSocket manager is not initialized"}

        # Validate required arguments
        if not topic or not topic.strip():
            return {"error": "topic is required and cannot be empty"}
        if not msg_type or not msg_type.strip():
            return {"error": "msg_type is required and cannot be empty"}

        # Validate msg is a dict
        if not isinstance(msg, dict):
            return {"error": f"Message must be a dict, got: {type(msg).__name__}"}
        if msg == {}:
            return {"error": "msg cannot be empty"}

        # Use proper advertise → publish → unadvertise pattern
        with ws_manager:
            # 1. Advertise the topic
            advertise_msg = {"op": "advertise", "topic": topic, "type": msg_type}
            send_error = ws_manager.send(advertise_msg)
            if send_error:
                return {"error": f"Failed to advertise topic: {send_error}"}

            # Check for advertise response/errors
            response = ws_manager.receive(timeout=1.0)
            if response:
                try:
                    msg_data = json.loads(response)
                    if msg_data.get("op") == "status" and msg_data.get("level") == "error":
                        return {
                            "error": f"Advertise failed: {msg_data.get('msg', 'Unknown error')}"
                        }
                except json.JSONDecodeError:
                    pass  # Non-JSON response is usually fine for advertise

            # 2. Publish the message
            publish_msg = {"op": "publish", "topic": topic, "msg": msg}
            send_error = ws_manager.send(publish_msg)
            if send_error:
                # Try to unadvertise even if publish failed
                ws_manager.send({"op": "unadvertise", "topic": topic})
                return {"error": f"Failed to publish message: {send_error}"}

            # Check for publish response/errors
            response = ws_manager.receive(timeout=1.0)
            if response:
                try:
                    msg_data = json.loads(response)
                    if msg_data.get("op") == "status" and msg_data.get("level") == "error":
                        # Unadvertise before returning error
                        ws_manager.send({"op": "unadvertise", "topic": topic})
                        return {"error": f"Publish failed: {msg_data.get('msg', 'Unknown error')}"}
                except json.JSONDecodeError:
                    pass  # Non-JSON response is usually fine for publish

            # 3. Unadvertise the topic
            unadvertise_msg = {"op": "unadvertise", "topic": topic}
            ws_manager.send(unadvertise_msg)

        return {
            "success": True,
            "note": "Message published using advertise → publish → unadvertise pattern",
        }

def check_config() -> str:
    """このサーバの設定・認証・接続状態を診断する。

    他のツールがエラーを返したとき、または利用者が「つながってる?」と
    尋ねたときに呼ぶ。
    """
    lines = [f"設定ファイル: {BASE_DIR / '.env'}"]
    lines.append("  存在: " + ("あり" if (BASE_DIR / ".env").exists() else "なし ← 要作成"))
    lines.append(f"書き込み: {'無効 (OUTLOOK_READONLY=true)' if readonly_mode() else '有効'}")

    who = signed_in_account()
    if not who:
        return "\n".join(lines) + (
            "\nNG: 未ログインです。ターミナルで `python login.py` を一度実行してください。"
        )
    lines.append(f"ログイン中: {who}")

    # ここから先はネットワークに出る。診断ツールなので、失敗しても
    # それまでに分かったこと(設定ファイル・書き込み可否・アカウント)は捨てない。
    try:
        data = graph(
            "GET", "/me/mailFolders/inbox?$select=displayName,totalItemCount,unreadItemCount"
        )
        lines.append(
            f"OK: 受信トレイ {data.get('totalItemCount', 0):,}件"
            f"(未読 {data.get('unreadItemCount', 0):,}件)にアクセスできました。"
        )
    except (AuthError, GraphError) as e:
        return "\n".join(lines) + f"\nNG: メールボックスに届きません: {e}"

    # 振分ルールは別権限(MailboxSettings.ReadWrite)。
    # この権限は後から追加したので、それ以前のトークンだとここだけ落ちる。
    try:
        rules = graph("GET", "/me/mailFolders/inbox/messageRules").get("value", [])
        lines.append(f"振分ルール: 読み書き可({len(rules)}件設定済み)")
    except (AuthError, GraphError):
        lines.append(
            "振分ルール: 使えません ← MailboxSettings.ReadWrite が未許可です。"
            "`python login.py --logout` のあと `python login.py` で同意し直してください。"
        )
    return "\n".join(lines)

def get_message(message_id: str) -> str:
    """1通のメールの本文と宛先を読む。

    Args:
        message_id: search_messages が返した短縮ID(例 "#3")、または生のID。
    """
    mid = resolve_message_id(message_id)
    m = graph(
        "GET",
        f"/me/messages/{mid}",
        params={"$select": "subject,from,toRecipients,ccRecipients,receivedDateTime,isRead,body,webLink,parentFolderId,hasAttachments"},
    )

    def addrs(key: str) -> str:
        got = [
            (r.get("emailAddress") or {}).get("address", "")
            for r in (m.get(key) or [])
        ]
        return ", ".join(a for a in got if a) or "(なし)"

    ea = (m.get("from") or {}).get("emailAddress") or {}
    body = m.get("body") or {}
    content = body.get("content") or ""
    if (body.get("contentType") or "").lower() == "html":
        content = html_to_text(content)

    header = [
        f"件名: {m.get('subject') or '(件名なし)'}",
        f"差出人: {ea.get('name', '')} <{ea.get('address', '')}>",
        f"宛先: {addrs('toRecipients')}",
    ]
    if (m.get("ccRecipients") or []):
        header.append(f"Cc: {addrs('ccRecipients')}")
    header += [
        f"受信: {format_received(m)}",
        f"フォルダ: {folder_name_map().get(m.get('parentFolderId', ''), '不明')}",
        f"状態: {'未読' if not m.get('isRead') else '既読'}"
        + ("・添付あり" if m.get("hasAttachments") else ""),
    ]
    return "\n".join(header) + "\n\n---\n" + truncate(content.strip() or "(本文なし)")

def list_rules() -> str:
    """受信トレイに設定されている自動振分ルールを一覧する。

    ルールを作る前に必ず呼んで、既存と衝突しないか・番号(sequence)が
    何番まで使われているかを確認すること。
    """
    rules = graph("GET", "/me/mailFolders/inbox/messageRules").get("value", [])
    if not rules:
        return "振分ルールは1つも設定されていません。"
    names = folder_name_map()
    rules.sort(key=lambda r: r.get("sequence", 0))
    return f"全{len(rules)}ルール(番号順に上から適用)\n" + "\n".join(
        _rule_line(r, names) for r in rules
    )

def run_sql(query: str, output_path: str = "") -> dict[str, Any]:
    """Run spatial SQL (DuckDB dialect, ST_* functions, read_parquet/ST_Read for files).

    Without output_path: returns up to 50 preview rows. With output_path (.parquet):
    materializes the full result as GeoParquet with a provenance manifest.
    """
    out = output_path or None
    if out:
        _guard(output_path=out)
    return _run("run_sql", {"query": query, "output": out}, duckdb_engine.run_sql, query, out)

