async def enable_advance_automation(
    device_id: str,
    automation_id: str,
    dry_run: bool = True,
) -> str:
    """Enable a previously disabled Advance Automation.

    Reads current state before toggling — no-ops if already enabled.
    Defaults to dry_run=True — set dry_run=False to execute.

    IMPORTANT: The AC Infinity API uses a toggle endpoint (updateGroupsIsOn).
    This tool reads the current enabled state first and only calls the API if
    the automation is currently disabled, ensuring the toggle results in enabled.

    Args:
        device_id: The AC Infinity device code (from discover_devices).
        automation_id: The automation_id from list_advance_automations.
        dry_run: If True (default), returns the action plan without executing.

    Returns:
        JSON with action, automation_name, automation_id, dry_run, sent.
        On failure returns ``{"error": "..."}``.
    """
    try:
        adv_id_int = _validate_automation_id(automation_id)
        if adv_id_int is None:
            return json.dumps({"error": "Invalid automation_id format"})

        device, err = await _get_device(device_id, for_write=True)
        if err:
            return err
        assert device is not None

        dev_id = device.get("devId")
        if not dev_id:
            return json.dumps({"error": f"Device {device_id} is missing devId"})

        raw = await asyncio.to_thread(_client().get_advance_automations, str(dev_id))
        grouped = _group_automations(raw, controller_type=_ctype(device))

        found = next((g for g in grouped if g["automation_id"] == adv_id_int), None)
        if found is None:
            return json.dumps({"error": f"Automation {automation_id} not found"})

        name = found["name"]

        if found["enabled"]:
            return json.dumps({
                "info": f"Automation '{name}' is already enabled. No action taken.",
                "dry_run": dry_run,
            })

        if dry_run:
            return json.dumps({
                "action": "enable",
                "automation_name": name,
                "automation_id": found["automation_id"],
                "dry_run": True,
                "sent": False,
            })

        # Live: call once with adv_ids[0]. The API's updateGroupsIsOn endpoint
        # toggles ALL entries sharing the same advName when called with ANY one
        # of their advId values — calling it N times causes N toggles (a no-op
        # for even N). One call is the correct behaviour (Fix 1).
        await asyncio.to_thread(
            _client().enable_advance_automation, str(dev_id), found["adv_ids"][0]
        )

        return json.dumps({
            "action": "enable",
            "automation_name": name,
            "automation_id": found["automation_id"],
            "dry_run": False,
            "sent": True,
        })

    except ACInfinityAuthError as e:
        logger.warning("Auth error in enable_advance_automation: %s", e)
        return json.dumps({
            "error": _AUTH_ERROR_MSG,
            "detail": "see server logs",
        })
    except ACInfinityAPIError as e:
        logger.error("API error in enable_advance_automation: %s", e)
        return json.dumps({"error": "API error", "detail": "see server logs"})
    except ACInfinityDeviceError as e:
        logger.warning("Device error in enable_advance_automation (%s): %s", device_id, e)
        return json.dumps({"error": str(e)})
    except Exception as e:
        logger.error("Unexpected error in enable_advance_automation: %s", e, exc_info=True)
        return json.dumps({"error": "Unexpected error", "detail": "see server logs"})

async def disable_advance_automation(
    device_id: str,
    automation_id: str,
    dry_run: bool = True,
) -> str:
    """Disable a currently enabled Advance Automation.

    Reads current state before toggling — no-ops if already disabled.
    Defaults to dry_run=True — set dry_run=False to execute.

    Live-tested (2026-05-22): disabling sets governed ports to OFF; re-enabling
    immediately restores ADVANCE mode at automation-defined speeds — no next-trigger
    wait. Use break_out_of_automation for a controlled handoff that also locks
    co-governed ports to safe manual speeds.

    Args:
        device_id: The AC Infinity device code (from discover_devices).
        automation_id: The automation_id from list_advance_automations.
        dry_run: If True (default), returns the action plan without executing.

    Returns:
        JSON with action, automation_name, automation_id, governed_ports (list of
        ``{port, port_name}`` dicts decoded from the automation's grouptDevType bitmasks),
        human_summary, dry_run, sent, and to_restore (natural-language hint
        for re-enabling). On failure returns ``{"error": "..."}``.
    """
    try:
        adv_id_int = _validate_automation_id(automation_id)
        if adv_id_int is None:
            return json.dumps({"error": "Invalid automation_id format"})

        device, err = await _get_device(device_id, for_write=True)
        if err:
            return err
        assert device is not None

        dev_id = device.get("devId")
        if not dev_id:
            return json.dumps({"error": f"Device {device_id} is missing devId"})

        raw = await asyncio.to_thread(_client().get_advance_automations, str(dev_id))
        grouped = _group_automations(raw, controller_type=_ctype(device))

        found = next((g for g in grouped if g["automation_id"] == adv_id_int), None)
        if found is None:
            return json.dumps({"error": f"Automation {automation_id} not found"})

        name = found["name"]
        to_restore = f"Ask me to re-enable '{name}'."

        if not found["enabled"]:
            return json.dumps({
                "info": f"Automation '{name}' is already disabled. No action taken.",
                "dry_run": dry_run,
            })

        # Decode which ports this automation governs from port_group bitmasks.
        # grouptDevType is a port bitmask: Port N → 2^(N-1) (bit N-1 set).
        # Using the bitmask rather than isOpenAutomation flags avoids false positives
        # when multiple automations are simultaneously active.
        _device_ports = device.get("deviceInfo", {}).get("ports", [])
        _port_map = {p["port"]: p for p in _device_ports if p.get("port") is not None}
        _seen: set[int] = set()
        governed_ports: list[dict] = []
        for _pg in found["port_groups"]:
            _bitmask = int(_pg.get("grp_dev_type") or 0)
            for _bit in range(8):
                if _bitmask & (1 << _bit):
                    _pnum = _bit + 1
                    if _pnum not in _seen:
                        _seen.add(_pnum)
                        _p = _port_map.get(_pnum)
                        _raw_nm = _p.get("portName") if _p else None
                        _label = _sanitize_api_string(_raw_nm, 64) if _raw_nm else f"Port {_pnum}"
                        if _label != f"Port {_pnum}":
                            _label = f"{_label} (Port {_pnum})"
                        governed_ports.append({"port": _pnum, "port_name": _label})
        governed_ports.sort(key=lambda x: x["port"])

        _governed_labels = [p["port_name"] for p in governed_ports]
        _governed_str = (
            ", ".join(_governed_labels) if _governed_labels else "its governed ports"
        )
        if dry_run:
            return json.dumps({
                "action": "disable",
                "automation_name": name,
                "automation_id": found["automation_id"],
                "governed_ports": governed_ports,
                "human_summary": (
                    f"Disabling '{name}' will take {_governed_str} off automation control. "
                    "You can re-enable it at any time and all ports will return to automated "
                    "control right away."
                ),
                "dry_run": True,
                "sent": False,
                "to_restore": to_restore,
            })

        # Live: call once with adv_ids[0]. The API's updateGroupsIsOn endpoint
        # toggles ALL entries sharing the same advName on a single call —
        # calling it N times causes N toggles (a no-op for even N). (Fix 1)
        await asyncio.to_thread(
            _client().disable_advance_automation, str(dev_id), found["adv_ids"][0]
        )

        return json.dumps({
            "action": "disable",
            "automation_name": name,
            "automation_id": found["automation_id"],
            "governed_ports": governed_ports,
            "human_summary": (
                f"'{name}' has been disabled. "
                "Re-enabling it will restore automation control immediately."
            ),
            "dry_run": False,
            "sent": True,
            "to_restore": to_restore,
        })

    except ACInfinityAuthError as e:
        logger.warning("Auth error in disable_advance_automation: %s", e)
        return json.dumps({
            "error": _AUTH_ERROR_MSG,
            "detail": "see server logs",
        })
    except ACInfinityAPIError as e:
        logger.error("API error in disable_advance_automation: %s", e)
        return json.dumps({"error": "API error", "detail": "see server logs"})
    except ACInfinityDeviceError as e:
        logger.warning("Device error in disable_advance_automation (%s): %s", device_id, e)
        return json.dumps({"error": str(e)})
    except Exception as e:
        logger.error("Unexpected error in disable_advance_automation: %s", e, exc_info=True)
        return json.dumps({"error": "Unexpected error", "detail": "see server logs"})

async def delete_advance_automation(
    device_id: str,
    automation_id: str,
    dry_run: bool = True,
) -> str:
    """Delete an Advance Automation from a device.

    If the automation is currently enabled, it is disabled first before deletion.
    Defaults to dry_run=True — set dry_run=False to delete.

    Args:
        device_id: The AC Infinity device code (from discover_devices).
        automation_id: The automation_id from list_advance_automations.
        dry_run: If True (default), returns the action plan without executing.

    Returns:
        JSON with action, automation_name, automation_id, was_enabled, dry_run, sent.
        On failure returns ``{"error": "..."}``.
    """
    try:
        adv_id_int = _validate_automation_id(automation_id)
        if adv_id_int is None:
            return json.dumps({"error": "Invalid automation_id format"})

        device, err = await _get_device(device_id, for_write=True)
        if err:
            return err
        assert device is not None

        dev_id = device.get("devId")
        if not dev_id:
            return json.dumps({"error": f"Device {device_id} is missing devId"})

        raw = await asyncio.to_thread(_client().get_advance_automations, str(dev_id))
        grouped = _group_automations(raw, controller_type=_ctype(device))

        found = next((g for g in grouped if g["automation_id"] == adv_id_int), None)
        if found is None:
            return json.dumps({"error": f"Automation {automation_id} not found"})

        name = found["name"]
        was_enabled = found["enabled"]

        if dry_run:
            return json.dumps({
                "action": "delete",
                "automation_name": name,
                "automation_id": found["automation_id"],
                "was_enabled": was_enabled,
                "dry_run": True,
                "sent": False,
            })

        # If enabled, disable first with a single toggle call (Fix 1: the API
        # toggles all same-name entries on one call — N calls cause N toggles).
        if was_enabled:
            await asyncio.to_thread(
                _client().disable_advance_automation, str(dev_id), found["adv_ids"][0]
            )

        # #302: one whole-program delete removes the entire slot (all rules) in a single
        # isflag=1 call. Do NOT loop over adv_ids — after the first call the program is gone,
        # so a second delByid returns a non-200 code and surfaces a false "API error" even
        # though the delete succeeded. Pass whole_program=True explicitly to make the isflag=1
        # intent self-documenting at the call site.
        await asyncio.to_thread(
            _client().delete_advance_automation,
            str(dev_id),
            found["adv_ids"][0],
            whole_program=True,
        )

        return json.dumps({
            "action": "delete",
            "automation_name": name,
            "automation_id": found["automation_id"],
            "was_enabled": was_enabled,
            "dry_run": False,
            "sent": True,
        })

    except ACInfinityAuthError as e:
        logger.warning("Auth error in delete_advance_automation: %s", e)
        return json.dumps({
            "error": _AUTH_ERROR_MSG,
            "detail": "see server logs",
        })
    except ACInfinityAPIError as e:
        logger.error("API error in delete_advance_automation: %s", e)
        return json.dumps({"error": "API error", "detail": "see server logs"})
    except ACInfinityDeviceError as e:
        logger.warning("Device error in delete_advance_automation (%s): %s", device_id, e)
        return json.dumps({"error": str(e)})
    except Exception as e:
        logger.error("Unexpected error in delete_advance_automation: %s", e, exc_info=True)
        return json.dumps({"error": "Unexpected error", "detail": "see server logs"})

async def delete_automation_rule(
    device_id: str,
    program_name: str,
    ports: list[int],
    begin_time: int | None = None,
    end_time: int | None = None,
    dry_run: bool = True,
) -> str:
    """Remove one rule from an Advance Automation program.

    The rule is identified by ``program_name`` plus the ``ports`` it controls, and
    optionally the window (``begin_time``/``end_time``) when more than one rule on those
    ports exists. This removes only that single rule — the rest of the program is left
    in place. I'll preview which rule will be removed before deleting it.

    Args:
        device_id: The AC Infinity device code (from discover_devices).
        program_name: The program the rule belongs to.
        ports: The port number(s) the target rule controls (used to find the rule).
        begin_time: Window-start selector to disambiguate when more than one rule matches.
        end_time: Window-end selector to disambiguate.
        dry_run: If True (default), previews the deletion without performing it.

    Returns:
        JSON with action, program_name, the removed rule, and sent/preview status.
        When more than one rule matches, returns a disambiguation list (by window).
        On failure returns ``{"error": "..."}``.
    """
    try:
        device, derr = await _get_device(device_id, for_write=True)
        if derr:
            return derr
        assert device is not None

        dev_id = device.get("devId")
        if not dev_id:
            return json.dumps({"error": f"Device {device_id} is missing devId"})

        perr = _validate_rule_ports(ports, device, device_id)
        if perr:
            return perr

        port_name_map = _build_port_name_map(device)
        tz_label = device.get("zoneId") or "device-local time"

        raw = await asyncio.to_thread(_client().get_advance_automations, str(dev_id))
        match, disambig, program_rules, ambiguous_program = _resolve_rule(
            raw, program_name, ports, begin_time, end_time, port_name_map, tz_label,
            controller_type=_ctype(device),
        )
        clean_program = _sanitize_api_string(program_name, 64)

        if not program_rules:
            names = sorted({
                _sanitize_api_string(e.get("advName") or "", 64) for e in raw
            })
            return json.dumps({
                "error": f"No program named '{clean_program}' on device {device_id}",
                "existing_programs": names,
            })
        if ambiguous_program is not None:
            return ambiguous_program
        if len(disambig) > 0:
            return json.dumps({
                "error": "More than one rule matches — pick which window to remove.",
                "program_name": clean_program,
                "matching_rules": disambig,
                "suggested_reply": (
                    "There's more than one rule on those ports."
                    " Which window should I remove?"
                ),
            })
        if match is None:
            return json.dumps({
                "error": f"No matching rule in '{clean_program}' for those ports.",
                "program_name": clean_program,
                "existing_rules": program_rules,
            })

        decoded = _decode_rule(match, controller_type=_ctype(device))
        rule_view = {
            "ports": _ports_label(port_name_map, ports),
            "control": decoded["control"],
            "window": _rule_window_str(
                match.get("beginTime"), match.get("endTime"), tz_label, match.get("switchTime")
            ),
            "_mode": decoded["mode"],
        }

        if dry_run:
            return json.dumps({
                "action": f"remove rule from '{clean_program}'",
                "program_name": clean_program,
                "rule": rule_view,
                "dry_run": True,
                "sent": False,
                "note": "Preview only — nothing removed yet. Confirm to remove this rule.",
            })

        # Stale-advId guard: re-resolve from a fresh getGroups at write time.
        raw_now = await asyncio.to_thread(_client().get_advance_automations, str(dev_id))
        match_now, _d, _r, _e = _resolve_rule(
            raw_now, program_name, ports, begin_time, end_time, port_name_map, tz_label,
            controller_type=_ctype(device),
        )
        if match_now is None:
            return json.dumps({
                "error": (
                    f"The rule in '{clean_program}' changed or was removed before I could"
                    " remove it. Ask me to list the program's rules and try again."
                ),
            })
        try:
            # whole_program=False → delByid isflag=0 removes ONLY this rule, not the
            # whole program slot (isflag=1 would nuke every rule in the program).
            await asyncio.to_thread(
                _client().delete_advance_automation, str(dev_id),
                int(match_now["advId"]), whole_program=False,
            )
        except ACInfinityAPIError as e:
            friendly = _map_write_failure(e)
            if friendly is not None:
                logger.error("delete_automation_rule write failed (%s): %s", device_id, e)
                return json.dumps({"error": friendly})
            raise
        return json.dumps({
            "action": f"remove rule from '{clean_program}'",
            "program_name": clean_program,
            "rule": rule_view,
            "dry_run": False,
            "sent": True,
            "human_summary": (
                f"Removed the rule on {_ports_label(port_name_map, ports)} from"
                f" '{clean_program}'."
            ),
        })

    except ACInfinityAuthError as e:
        logger.warning("Auth error in delete_automation_rule: %s", e)
        return json.dumps({"error": _AUTH_ERROR_MSG, "detail": "see server logs"})
    except ACInfinityAPIError as e:
        logger.error("API error in delete_automation_rule: %s", e)
        return json.dumps({"error": "API error", "detail": "see server logs"})
    except ACInfinityDeviceError as e:
        logger.warning("Device error in delete_automation_rule (%s): %s", device_id, e)
        return json.dumps({"error": str(e)})
    except Exception as e:
        logger.error("Unexpected error in delete_automation_rule: %s", e, exc_info=True)
        return json.dumps({"error": "Unexpected error", "detail": "see server logs"})

async def break_out_of_automation(
    device_id: str,
    port: int,
    dry_run: bool = True,
    confirm_automation_name: str | None = None,
) -> str:
    """Break a port out of Advance Automation control and lock co-governed ports.

    This is the safe way to manually override a port that is currently under
    Advance Automation. It:

    1. Checks that the port is actually under automation (idempotent: no-ops if not).
    2. Finds the governing automation.
    3. Identifies all other ports in the same automation as the target port (co-ports).
       Only those ports are locked — ports in other automations or empty ports are unaffected.
    4. On dry_run=False:
       a. Disables the automation.
       b. Locks each co-port to its current manual speed (prevents unexpected speed changes).
       c. Leaves the target port free for your manual change.

    Defaults to dry_run=True. For live execution (dry_run=False), you must supply
    ``confirm_automation_name`` matching the automation name (case-insensitive) as a
    safety confirmation.

    Args:
        device_id: The AC Infinity device code (from discover_devices).
        port: The port number you want to break free (1-based).
        dry_run: If True (default), returns the execution plan without making changes.
        confirm_automation_name: Required when dry_run=False — the name of the
            automation to disable, for safety confirmation.

    Returns:
        Dry-run: JSON plan with sequence of steps, co_ports_to_lock, estimated_duration.
        Live: JSON with co_ports_locked and target_port_freed.
        Idempotent: ``{"info": "Port is not currently under automation control."}``
        On failure returns ``{"error": "..."}``.
    """
    try:
        if port < 1 or port > 8:
            return json.dumps({"error": f"port must be between 1 and 8 (got {port})"})

        device, err = await _get_device(device_id, for_write=True)
        if err:
            return err
        assert device is not None

        dev_id = device.get("devId")
        if not dev_id:
            return json.dumps({"error": f"Device {device_id} is missing devId"})

        # Held on AI+ (#316). This tool issues one live write per co-governed port
        # plus the target, and its rollback path re-enables the automation without
        # unwinding co-ports it already switched to manual — leaving those ports
        # pinned manually AND claimed by a re-enabled automation. Those call sites
        # were never among the AI+ refusal branches, so pre-#308 they returned
        # sent=False silently; enabling AI+ writes makes them real. Multi-port
        # partial-failure handling needs its own fix and its own tests.
        try:
            breakout_held = not dry_run and _ai_plus_write_held(device)
        except ACInfinityDeviceError as e:
            return _unclassifiable_device_error(device_id, port, e)
        if breakout_held:
            return _ai_plus_held_error(
                "break_out_of_automation", device, device_id, port,
                "taking one port out of a shared automation means switching every "
                "port that automation governs. If one of those switches fails "
                "partway through, I can't reliably put the rest back, and you'd be "
                "left with ports pinned by hand and still claimed by the automation.",
                "Turning the whole automation off, or setting this port's mode "
                "yourself, both work here today.",
            )

        # Step 0: Idempotency check — is this port actually under automation?
        port_settings = await asyncio.to_thread(
            _client().get_mode_settings, dev_id, port
        )
        mode_type = port_settings.get("modeType")

        # Get port info from device data for display names.
        ports_data = device.get("deviceInfo", {}).get("ports", [])
        port_info = next((p for p in ports_data if p.get("port") == port), None)
        raw_port_name = port_info.get("portName") if port_info else None
        port_name = _sanitize_api_string(raw_port_name, 64) if raw_port_name else f"Port {port}"

        if mode_type != _ADVANCE_MODE_TYPE:
            _port_display = (
                f"{port_name} (Port {port})" if port_name != f"Port {port}" else port_name
            )
            return json.dumps({
                "info": (
                    f"{_port_display} is not currently under automation control. "
                    "No action taken."
                ),
            })

        # Step 1: Find governing automation.
        raw_automations = await asyncio.to_thread(
            _client().get_advance_automations, str(dev_id)
        )
        grouped = _group_automations(raw_automations, controller_type=_ctype(device))

        # Find the automation whose bitmask covers the target port.
        automation = _find_governing_automation(grouped, port)

        if automation is None:
            # Ghost state: no active automation covers this port — modeType=15 flag is stale
            # from a deleted or fully-disabled automation. Either way the port is not under
            # active automation control, so the correct response is a no-op info message.
            _port_display = (
                f"{port_name} (Port {port})" if port_name != f"Port {port}" else port_name
            )
            return json.dumps({
                "info": (
                    f"{_port_display} is not currently under active automation control. "
                    "No action taken."
                ),
            })

        auto_name = automation["name"]
        auto_id = automation["automation_id"]
        adv_ids = automation["adv_ids"]

        # Step 2: Identify co-governed ports from the governing automation's bitmasks.
        # Only ports in the same automation are locked — ports in other automations or
        # empty/disconnected ports (via _is_port_empty) are excluded.
        automation_port_nums: set[int] = set()
        for pg in automation.get("port_groups", []):
            bitmask = int(pg.get("grp_dev_type") or 0)
            for bit in range(8):
                if bitmask & (1 << bit):
                    automation_port_nums.add(bit + 1)
        automation_port_nums.discard(port)  # exclude the target port

        co_ports: list[dict] = []
        for p_data in ports_data:
            p_num = p_data.get("port")
            if p_num not in automation_port_nums:
                continue
            if _is_port_empty(p_data, p_num, device):  # empty/disconnected — skip
                continue
            raw_p_name = p_data.get("portName")
            p_name = _sanitize_api_string(raw_p_name, 64) if raw_p_name else f"Port {p_num}"
            current_speed = p_data.get("speak", 0)
            co_ports.append({
                "port": p_num,
                "port_name": p_name,
                "current_speed": current_speed,
            })

        # Estimate: 1.5s rate limit per write; 1 disable + len(co_ports) locks.
        n_writes = 1 + len(co_ports)
        estimated_duration = round(n_writes * 1.5, 1)

        sequence = [
            {"step": 1, "action": f"disable automation '{auto_name}'"},
        ]
        for i, cp in enumerate(co_ports, start=2):
            lock_mode = "ON" if cp["current_speed"] > 0 else "OFF"
            _cp_display = (
                f"{cp['port_name']} (Port {cp['port']})"
                if cp['port_name'] != f"Port {cp['port']}"
                else cp['port_name']
            )
            sequence.append({
                "step": i,
                "action": (
                    f"lock {_cp_display} to "
                    f"current speed {cp['current_speed']} (manual {lock_mode})"
                ),
            })
        sequence.append({
            "step": len(sequence) + 1,
            "action": "target port freed from automation — apply your change manually",
        })

        _target_label = (
            f"{port_name} (Port {port})" if port_name != f"Port {port}" else f"Port {port}"
        )
        _co_label_parts = [
            f"{cp['port_name']} (Port {cp['port']})"
            if cp["port_name"] != f"Port {cp['port']}"
            else f"Port {cp['port']}"
            for cp in co_ports
        ]
        _co_str = ", ".join(_co_label_parts) if _co_label_parts else ""
        if _co_str:
            _human_co = (
                f" The other ports in this automation — {_co_str} — "
                "will be locked to their current speeds."
            )
        else:
            _human_co = ""
        _bo_human_summary = (
            f"This will disable the '{auto_name}' automation.{_human_co} "
            f"{_target_label} will be freed for manual control. "
            "You can re-enable the automation at any time — "
            "all ports will return to automated control right away."
        )

        if dry_run:
            return json.dumps({
                "action": f"release {_target_label} from '{auto_name}' automation",
                "dry_run": True,
                "automation_name": auto_name,
                "automation_id": auto_id,
                "target_port": port,
                "target_port_name": port_name,
                "estimated_duration_seconds": estimated_duration,
                "human_summary": _bo_human_summary,
                "sequence": sequence,
                "co_ports_to_lock": [
                    {
                        "port_name": cp["port_name"],
                        "port": cp["port"],
                        "current_speed": cp["current_speed"],
                        "lock_mode": "ON" if cp["current_speed"] > 0 else "OFF",
                    }
                    for cp in co_ports
                ],
            }, indent=2)

        # Live execution.
        if confirm_automation_name is None:
            return json.dumps({
                "error": (
                    f"Please confirm which automation to disable. "
                    f"Tell me '{auto_name}' to proceed."
                ),
            })

        if len(confirm_automation_name) > 256:
            return json.dumps(
                {"error": "The automation name you provided is too long (max 256 characters)."}
            )

        if confirm_automation_name.casefold() != auto_name.casefold():
            safe_confirm = _sanitize_api_string(confirm_automation_name or "", 64)
            return json.dumps({
                "error": (
                    f"'{safe_confirm}' doesn't match the governing automation '{auto_name}'. "
                    "Please use the exact automation name."
                ),
            })

        device_lock = _get_device_lock(device_id)
        if device_lock.locked():
            return json.dumps({
                "conflict": "SEQUENCE_IN_PROGRESS",
                "device_id": device_id,
                "message": (
                    "Another break_out_of_automation is already in progress for this device."
                ),
            })

        async with device_lock:
            # Step A: Disable the automation with a single toggle call (Fix 1: the
            # API toggles all same-name entries on one call — N calls cause N toggles).
            try:
                await asyncio.to_thread(
                    _client().disable_advance_automation, str(dev_id), adv_ids[0]
                )
            except Exception as disable_exc:
                logger.error(
                    "break_out_of_automation failed at disable step "
                    "(device=%s): %s", device_id, disable_exc,
                )
                return json.dumps({
                    "error": "Failed to disable automation",
                    "failed_step": "disable_automation",
                    "detail": "see server logs",
                })

            # Step B: Wait briefly for the AC Infinity cloud to propagate the disable, then
            # re-fetch device data. Two guards in _set_port_mode_inner check ADVANCE state:
            # Guard 1 reads isOpenAutomation from devInfoListAll (the device dict we pass);
            # Guard 2 reads modeType/isOpenAutomation from getdevModeSettingList (a fresh API
            # call inside the write layer). Both return stale state immediately after the
            # disable — the sleep allows both to settle before the co-port lock writes.
            await asyncio.sleep(2.0)
            _invalidate_device_cache()
            device, err = await _get_device(device_id, for_write=True)
            if err:
                logger.error(
                    "break_out_of_automation could not re-fetch device after disable "
                    "(device=%s) — rollback: re-enabling automation", device_id,
                )
                try:
                    await asyncio.to_thread(
                        _client().enable_advance_automation, str(dev_id), adv_ids[0]
                    )
                except Exception:
                    pass
                return json.dumps({
                    "error": "Automation disabled but re-fetch failed — automation re-enabled",
                    "detail": "see server logs",
                })
            assert device is not None

            # Step C: Lock co-governed ports to their current speeds.
            co_ports_locked: list[dict] = []
            failed_port = None
            for cp in co_ports:
                cp_num = cp["port"]
                cp_speed = cp["current_speed"]
                try:
                    if cp_speed > 0:
                        lock_updates = {"atType": 2, "onSpead": cp_speed}  # ON at current speed
                        lock_mode_str = "ON"
                    else:
                        lock_updates = {"atType": 1, "onSpead": 0}  # OFF
                        lock_mode_str = "OFF"
                    await asyncio.to_thread(
                        _client().set_port_mode, device, cp_num, lock_updates, False
                    )
                    co_ports_locked.append({
                        "port_name": cp["port_name"],
                        "port": cp_num,
                        "locked_to_speed": cp_speed,
                        "locked_to_mode": lock_mode_str,
                    })
                except Exception as lock_exc:
                    logger.error(
                        "break_out_of_automation failed locking port %s "
                        "(device=%s): %s", cp_num, device_id, lock_exc,
                    )
                    failed_port = cp_num
                    break

            if failed_port is not None:
                # Attempt rollback: re-enable the automation with a single toggle call
                # (Fix 1: same API behaviour as disable — one call toggles all entries).
                rollback_succeeded = False
                try:
                    await asyncio.to_thread(
                        _client().enable_advance_automation, str(dev_id), adv_ids[0]
                    )
                    rollback_succeeded = True
                except Exception as rb_exc:
                    logger.error(
                        "break_out_of_automation rollback failed (device=%s): %s",
                        device_id, rb_exc,
                    )
                return json.dumps({
                    "error": f"Failed to lock co-port {failed_port}",
                    "failed_step": f"lock_port_{failed_port}",
                    "rollback_attempted": True,
                    "rollback_succeeded": rollback_succeeded,
                    "recovery_steps": [
                        f"Manually re-enable automation '{auto_name}' via the AC Infinity app.",
                        "To restore automation control, ask me to re-enable the automation.",
                    ],
                })

            # Step D: Lock the target port to its automation-controlled speed so the grower
            # sees no unexpected state change. The port is now under manual control; they
            # can adjust from this baseline.
            # Use the governing automation's on_speed (not ports_data["speak"]) because
            # speak stores the last manually-set speed, not the automation-controlled speed.
            governing_pg = _find_governing_port_group(automation, port)
            target_speed = governing_pg.get("on_speed", 0) if governing_pg else 0
            if target_speed > 0:
                target_lock_updates: dict = {"atType": 2, "onSpead": target_speed}
            else:
                target_lock_updates = {"atType": 1, "onSpead": 0}
            try:
                await asyncio.to_thread(
                    _client().set_port_mode, device, port, target_lock_updates, False
                )
            except Exception as tgt_exc:
                logger.warning(
                    "break_out_of_automation: could not lock target port %s to speed %s "
                    "(device=%s): %s", port, target_speed, device_id, tgt_exc,
                )
                # Non-fatal: automation is disabled and port is free from automation control
                # even if the baseline speed lock failed.

        _target_speed_note = (
            f" at speed {target_speed}" if target_speed > 0 else " (currently off)"
        )
        return json.dumps({
            "action": f"release {_target_label} from '{auto_name}' automation",
            "dry_run": False,
            "automation_name": auto_name,
            "automation_id": auto_id,
            "co_ports_locked": co_ports_locked,
            "target_port": port,
            "target_port_freed": True,
            "target_port_locked_to_speed": target_speed,
            "human_summary": (
                f"Released {_target_label} from the '{auto_name}' automation"
                f"{_target_speed_note}. You can now control it manually."
            ),
            "sent": True,
        }, indent=2)

    except ACInfinityAuthError as e:
        logger.warning("Auth error in break_out_of_automation: %s", e)
        return json.dumps({
            "error": _AUTH_ERROR_MSG,
            "detail": "see server logs",
        })
    except ACInfinityAPIError as e:
        logger.error("API error in break_out_of_automation: %s", e)
        return json.dumps({"error": "API error", "detail": "see server logs"})
    except ACInfinityDeviceError as e:
        logger.warning("Device error in break_out_of_automation (%s): %s", device_id, e)
        return json.dumps({"error": str(e)})
    except Exception as e:
        logger.error("Unexpected error in break_out_of_automation: %s", e, exc_info=True)
        return json.dumps({"error": "Unexpected error", "detail": "see server logs"})

def list_lib_footprints(pretty_dir: str = FP_LIB_PATH) -> str:
    """List all footprints in a .pretty library directory.

    Args:
        pretty_dir: Path to .pretty directory containing .kicad_mod files
    """
    p = Path(pretty_dir)
    if not p.is_dir():
        raise ToolError(f"'{pretty_dir}' is not a directory.")
    mods = sorted(p.glob("*.kicad_mod"))
    if not mods:
        return "No footprints found."
    lines = [f.stem for f in mods]
    return "\n".join(lines)

def set_net_class(
    name: str,
    nets: list[str],
    track_width: float | None = None,
    clearance: float | None = None,
    via_size: float | None = None,
    via_drill: float | None = None,
    pcb_path: str = PCB_PATH,
) -> NetClassResult:
    """Create or update a net class with design rules and assign nets.

    Edits the KiCad project file (.kicad_pro) alongside the board to
    define the net class and assign nets.  Does NOT require pcbnew.

    Args:
        name: Net class name (e.g. "Power", "HighSpeed")
        nets: List of net names to assign to this class
        track_width: Track width in mm (None = use default)
        clearance: Clearance in mm (None = use default)
        via_size: Via diameter in mm (None = use default)
        via_drill: Via drill in mm (None = use default)
        pcb_path: Path to .kicad_pcb file. Optional; omit to use the configured default.
    """
    pcb_file = Path(pcb_path).resolve()
    pro_file = pcb_file.with_suffix(".kicad_pro")

    if not pro_file.exists():
        raise ToolError(
            f"Project file not found: {pro_file}. "
            "A .kicad_pro file must exist alongside the .kicad_pcb file."
        )

    # Read existing project JSON. UnicodeDecodeError is listed because it is a
    # ValueError, not an OSError, so it used to escape as a raw traceback; it
    # can still be raised by a file that is genuinely not UTF-8.
    try:
        pro_data = json.loads(pro_file.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, UnicodeDecodeError, OSError) as exc:
        raise ToolError(f"Failed to read project file: {exc}") from exc

    # Ensure net_settings structure exists
    if "net_settings" not in pro_data:
        pro_data["net_settings"] = {}
    ns = pro_data["net_settings"]
    if "classes" not in ns:
        ns["classes"] = []
    if "meta" not in ns:
        ns["meta"] = {"version": 4}
    if "netclass_assignments" not in ns or ns["netclass_assignments"] is None:
        ns["netclass_assignments"] = {}

    # Build the net class entry
    nc_entry: dict[str, object] = {"name": name}
    if track_width is not None:
        nc_entry["track_width"] = track_width
    if clearance is not None:
        nc_entry["clearance"] = clearance
    if via_size is not None:
        nc_entry["via_diameter"] = via_size
    if via_drill is not None:
        nc_entry["via_drill"] = via_drill

    # Update or add the net class in the classes list
    found = False
    for i, cls in enumerate(ns["classes"]):
        if cls.get("name") == name:
            ns["classes"][i].update(nc_entry)
            found = True
            break
    if not found:
        ns["classes"].append(nc_entry)

    # Assign nets to this class
    for net_name in nets:
        ns["netclass_assignments"][net_name] = name

    # Write back. ensure_ascii=False keeps a net class or path the user wrote in
    # their own alphabet readable in their own file; the default escapes every
    # non-ASCII character to \uXXXX, which is valid JSON KiCad reads back fine
    # but is not what they had. UTF-8 to match the read above and KiCad's own
    # encoding.
    try:
        _atomic_write(
            pro_file,
            (json.dumps(pro_data, indent=2, ensure_ascii=False) + "\n").encode("utf-8"),
        )
    except OSError as exc:
        raise ToolError(f"Failed to write project file: {exc}") from exc

    return NetClassResult(
        net_class=name,
        nets_assigned=len(nets),
        track_width_mm=track_width,
        clearance_mm=clearance,
    )

def remove_hierarchical_sheet(
    parent_schematic_path: str,
    name: str | None = None,
    uuid: str | None = None,
    delete_child_file: bool = False,
) -> str:
    """Remove a hierarchical sheet block from a parent schematic.

    Identify the sheet by name, uuid, or both. If name matches multiple sheets,
    returns an error with UUIDs for disambiguation.

    Args:
        parent_schematic_path: Path to parent .kicad_sch
        name: Sheet name to match
        uuid: Sheet UUID for unambiguous identification
        delete_child_file: If True, delete the child .kicad_sch file
              (unless still referenced by another sheet)
    """
    if not name and not uuid:
        raise ToolError("Provide at least one of 'name' or 'uuid'.")

    tree, root, *_ = _open_sch_cst(parent_schematic_path)
    sheets = root.find_all("sheet")

    def _normalize_uuid(u: str) -> str:
        return u.replace("-", "").lower()

    def _sheet_name(s) -> str:
        return _sym_property_cst(s, "Sheetname") or ""

    # Find matching sheets
    matches: list[int] = []
    for i, sheet in enumerate(sheets):
        s_uuid = _node_uuid(sheet)
        if uuid:
            if s_uuid and _normalize_uuid(s_uuid) == _normalize_uuid(uuid):
                if name and _sheet_name(sheet) != name:
                    raise ToolError(
                        f"Sheet with uuid={uuid} found but its name is "
                        f"'{_sheet_name(sheet)}', not '{name}'."
                    )
                matches.append(i)
                break
        else:
            if _sheet_name(sheet) == name:
                matches.append(i)

    if not matches:
        criteria = f"uuid={uuid}" if uuid else f"name='{name}'"
        raise ToolError(f"No hierarchical sheet found matching {criteria}.")

    if len(matches) > 1:

        def _xy(s):
            s_at = s.find("at")
            return float(s_at.atoms[1].text), float(s_at.atoms[2].text)

        info = ", ".join(
            f"uuid={_node_uuid(sheets[i])} at ({_xy(sheets[i])[0]}, {_xy(sheets[i])[1]})"
            for i in matches
        )
        raise ToolError(
            f"Multiple sheets named '{name}' found: [{info}]. Provide uuid to disambiguate."
        )

    target = sheets[matches[0]]
    sheet_name = _sheet_name(target)
    sheet_uuid = _node_uuid(target)
    child_filename = _sheet_file_cst(target) or ""
    msg = f"Removed hierarchical sheet '{sheet_name}' (uuid={sheet_uuid})."

    # Handle child file deletion
    if delete_child_file:
        parent_dir = Path(parent_schematic_path).parent.resolve()
        child_path = parent_dir / child_filename
        # child_filename is the Sheetfile property, so it is file content and can
        # name ../../../anything. This is the only delete in the package, and it
        # runs before the parent is written, so refusing leaves both files intact.
        if not child_path.resolve().is_relative_to(parent_dir):
            raise ToolError(
                f"Sheet file '{child_filename}' resolves outside {parent_dir}, so it was "
                "not deleted and the sheet block was not removed. Re-run with "
                "delete_child_file=False to remove the block on its own."
            )
        # Inside the directory it can still name something that is no sheet of this parent:
        # the board or the project file, the project's root schematic, or the parent itself,
        # which was unlinked and then rewritten at the umask's mode on a fresh inode.
        not_a_child = ""
        if child_path.suffix.lower() != ".kicad_sch":
            not_a_child = "is not a .kicad_sch file"
        elif child_path.exists() and child_path.samefile(parent_schematic_path):
            not_a_child = "is the parent schematic itself"
        elif child_path.with_suffix(".kicad_pro").exists():
            not_a_child = "is the root schematic of a project"
        if not_a_child:
            raise ToolError(
                f"Sheet file '{child_filename}' {not_a_child}, so it was not deleted and the "
                "sheet block was not removed. Re-run with delete_child_file=False to remove "
                "the block on its own."
            )

        # Check if any OTHER sheet still references this child file. A different spelling
        # of the same file ('./child.kicad_sch', an absolute path, a symlink) counts too.
        def _names_child(s) -> bool:
            sf = _sheet_file_cst(s) or ""
            if not sf:
                return False
            if sf == child_filename:
                return True
            # KiCad squeezes '.' and '..' out of a sheet path lexically before opening it
            # (wxFileName::MakeAbsolute normalizes with wxPATH_NORM_DOTS), while the kernel
            # walks each component, so 'zz/../child.kicad_sch' with no zz, or
            # 'child.kicad_sch/../child.kicad_sch', is the child to KiCad and missing to
            # samefile. Compare the lexical path too, both as text and as a file.
            lexical = Path(os.path.normpath(parent_dir / sf))
            if lexical == Path(os.path.normpath(child_path)):
                return True
            if not child_path.exists():
                return False
            for cand in (parent_dir / sf, lexical):
                try:
                    if cand.samefile(child_path):
                        return True
                except (FileNotFoundError, NotADirectoryError):
                    pass
                except (OSError, ValueError):
                    # This guards the package's only delete, so a block whose file cannot
                    # be compared for any reason but its absence keeps the child.
                    return True
            return False

        other_refs = any(_names_child(s) for j, s in enumerate(sheets) if j != matches[0])
        if other_refs:
            msg += f" Kept child file '{child_filename}' — still referenced by another sheet block."
        elif child_path.is_file():
            child_path.unlink()
            msg += f" Deleted child file '{child_filename}'."

    root.remove_child(target)
    _atomic_write(parent_schematic_path, _cst.serialize(tree))
    return msg

def validate_hierarchy(schematic_path: str = SCH_PATH) -> HierarchyValidationResult:
    """Validate hierarchical schematic for common issues.

    Checks for orphaned labels/pins, direction mismatches, duplicate
    reference designators, unannotated components, and missing files.

    Args:
        schematic_path: Path to root .kicad_sch file. Optional; omit to use the configured default.
    """
    _, root, *_ = _open_sch_cst(schematic_path)
    sch_dir = Path(schematic_path).parent
    issues: list[dict] = []
    all_refs: dict[str, list[str]] = {}  # ref -> [sheet_names]

    def _scan_refs(node_root, sheet_label: str) -> None:
        for sym in node_root.find_all("symbol"):
            ref = _sym_property_cst(sym, "Reference")
            if ref is None:
                continue
            if "?" in ref:
                issues.append({"type": "unannotated_ref", "sheet": sheet_label, "reference": ref})
            else:
                all_refs.setdefault(ref, []).append(sheet_label)

    # Check root schematic refs
    _scan_refs(root, Path(schematic_path).name)

    for sheet in root.find_all("sheet"):
        sheet_name = _sheet_name_cst(sheet) or ""
        file_name = _sheet_file_cst(sheet) or ""
        child_path = sch_dir / file_name
        # Not exists(), here and at every other read of a Sheetfile: it is document
        # content, and a directory, a device such as /dev/zero or a procfs pseudo-file,
        # which read_bytes() never finishes, counts as a missing sheet.
        if not _sheet_file_nonempty(child_path):
            issues.append(
                {
                    "type": "missing_file",
                    "sheet_name": sheet_name,
                    "file_name": file_name,
                }
            )
            continue

        child_root = _cst.parse(child_path.read_bytes()).lists[0]
        pin_names = {p.atoms[1].text: p.atoms[2].text for p in sheet.find_all("pin")}
        label_names: dict[str, str] = {}
        for hl in child_root.find_all("hierarchical_label"):
            shape = hl.find("shape")
            # kiutils defaulted a shapeless label to "input"; KiCad always writes one.
            label_names[_node_text(hl)] = shape.atoms[1].text if shape is not None else "input"

        # Orphaned labels (in child, no matching pin)
        for label_name, label_shape in label_names.items():
            if label_name not in pin_names:
                issues.append(
                    {
                        "type": "orphaned_label",
                        "sheet_name": sheet_name,
                        "label": label_name,
                    }
                )
            elif pin_names[label_name] != label_shape:
                issues.append(
                    {
                        "type": "direction_mismatch",
                        "sheet_name": sheet_name,
                        "pin": label_name,
                        "pin_direction": pin_names[label_name],
                        "label_direction": label_shape,
                    }
                )

        # Orphaned pins (in parent, no matching label)
        for pin_name in pin_names:
            if pin_name not in label_names:
                issues.append(
                    {
                        "type": "orphaned_pin",
                        "sheet_name": sheet_name,
                        "pin": pin_name,
                    }
                )

        # Check child refs
        _scan_refs(child_root, file_name)

    # Check for duplicate refs across sheets
    for ref, sheets_list in all_refs.items():
        if ref.startswith("#"):  # Skip power symbols
            continue
        if len(sheets_list) > 1:
            issues.append(
                {
                    "type": "duplicate_ref",
                    "reference": ref,
                    "sheets": sheets_list,
                }
            )

    status = "ok" if not issues else "issues_found"
    return HierarchyValidationResult(
        status=status,
        issue_count=len(issues),
        issues=issues,
    )

def trace_hierarchical_net(net_name: str, schematic_path: str = SCH_PATH) -> NetTraceResult:
    """Trace a net across the hierarchy, following hierarchical pins and labels.

    Args:
        net_name: Net/label name to trace
        schematic_path: Path to root .kicad_sch file. Optional; omit to use the configured default.
    """
    _, root, *_ = _open_sch_cst(schematic_path)
    sch_dir = Path(schematic_path).parent
    root_name = Path(schematic_path).name

    sheets_touched: list[str] = []
    connections: list[dict] = []

    def _count(node_root, token: str) -> int:
        return sum(1 for n in node_root.find_all(token) if _node_text(n) == net_name)

    # Check root schematic for labels matching net_name
    if _count(root, "label") or _count(root, "global_label"):
        sheets_touched.append(root_name)

    # Check sheet pins for matching name
    for sheet in root.find_all("sheet"):
        pin_match = any(p.atoms[1].text == net_name for p in sheet.find_all("pin"))
        if pin_match:
            sheet_name = _sheet_name_cst(sheet) or ""
            file_name = _sheet_file_cst(sheet) or ""
            if root_name not in sheets_touched:
                sheets_touched.append(root_name)
            connections.append(
                {
                    "type": "sheet_pin",
                    "sheet_name": sheet_name,
                    "file_name": file_name,
                }
            )
            # Look inside child
            child_path = sch_dir / file_name
            if _sheet_file_nonempty(child_path):
                child_root = _cst.parse(child_path.read_bytes()).lists[0]
                hlabel_count = _count(child_root, "hierarchical_label")
                if hlabel_count:
                    sheets_touched.append(file_name)
                    connections.append(
                        {
                            "type": "hierarchical_label",
                            "sheet_name": sheet_name,
                            "file_name": file_name,
                            "label_count": hlabel_count,
                        }
                    )
                # Check for component connections in child
                label_count = _count(child_root, "label")
                if label_count:
                    connections.append(
                        {
                            "type": "local_label",
                            "file_name": file_name,
                            "count": label_count,
                        }
                    )

    # Also check global labels in all sheets
    for sheet in root.find_all("sheet"):
        file_name = _sheet_file_cst(sheet) or ""
        child_path = sch_dir / file_name
        if _sheet_file_nonempty(child_path):
            child_root = _cst.parse(child_path.read_bytes()).lists[0]
            glabel_count = _count(child_root, "global_label")
            if glabel_count:
                if file_name not in sheets_touched:
                    sheets_touched.append(file_name)
                connections.append(
                    {
                        "type": "global_label",
                        "file_name": file_name,
                        "count": glabel_count,
                    }
                )

    return NetTraceResult(
        net_name=net_name,
        sheets_touched=sheets_touched,
        connection_count=len(connections),
        connections=connections,
    )

def list_cross_sheet_nets(schematic_path: str = SCH_PATH) -> CrossSheetNetsResult:
    """List all nets that cross sheet boundaries (hierarchical pins and global labels).

    Args:
        schematic_path: Path to root .kicad_sch file. Optional; omit to use the configured default.
    """
    _, root, *_ = _open_sch_cst(schematic_path)
    sch_dir = Path(schematic_path).parent

    hierarchical_nets: list[dict] = []
    global_nets: dict[str, list[str]] = {}  # name -> [sheet files]

    for sheet in root.find_all("sheet"):
        sheet_name = _sheet_name_cst(sheet) or ""
        file_name = _sheet_file_cst(sheet) or ""
        child_path = sch_dir / file_name
        child_root = (
            _cst.parse(child_path.read_bytes()).lists[0]
            if _sheet_file_nonempty(child_path)
            else None
        )
        hlabels = (
            {_node_text(hl) for hl in child_root.find_all("hierarchical_label")}
            if child_root is not None
            else set()
        )

        for pin in sheet.find_all("pin"):
            hierarchical_nets.append(
                {
                    "name": pin.atoms[1].text,
                    "direction": pin.atoms[2].text,
                    "sheet_name": sheet_name,
                    "file_name": file_name,
                    "label_matched": pin.atoms[1].text in hlabels,
                }
            )

        # Collect global labels
        if child_root is not None:
            for gl in child_root.find_all("global_label"):
                global_nets.setdefault(_node_text(gl), []).append(file_name)

    # Also check root for global labels
    for gl in root.find_all("global_label"):
        global_nets.setdefault(_node_text(gl), []).append(Path(schematic_path).name)

    global_net_list = [
        {"name": name, "sheets": sheets} for name, sheets in sorted(global_nets.items())
    ]

    return CrossSheetNetsResult(
        hierarchical_nets=hierarchical_nets,
        global_nets=global_net_list,
    )

def get_symbol_instances(schematic_path: str = SCH_PATH) -> SymbolInstancesResult:
    """List all symbol instances from a root schematic's symbolInstances table.

    Args:
        schematic_path: Path to root .kicad_sch file. Optional; omit to use the configured default.
    """
    _, root, *_ = _open_sch_cst(schematic_path)
    instances = []
    # KiCad 8+ carries instances per placed symbol instead, so the whole
    # section is often absent: that is an empty list, not an error.
    si = root.find("symbol_instances")
    for entry in si.find_all("path") if si is not None else []:
        fields = {c.head: c.atoms[1].text for c in entry.lists if len(c.atoms) > 1}
        instances.append(
            {
                "path": entry.atoms[1].text,
                "reference": fields.get("reference", ""),
                "unit": int(fields.get("unit", 1)),
                "value": fields.get("value", ""),
                "footprint": fields.get("footprint", ""),
            }
        )
    return SymbolInstancesResult(instances=instances, count=len(instances))

def flatten_hierarchy(
    schematic_path: str = SCH_PATH,
    output_path: str = "",
) -> str:
    """Flatten a hierarchical schematic into a single sheet.

    Merges all child sheet content into one schematic with offset positions.
    Creates a new file — does NOT modify the original hierarchy.

    Args:
        schematic_path: Path to root .kicad_sch file. Optional; omit to use the configured default.
        output_path: Path for flattened output (defaults to *_flat.kicad_sch)
    """
    import uuid as _uuid_mod

    flat_tree, flat_root, *_ = _open_sch_cst(schematic_path)
    sch_dir = Path(schematic_path).parent

    if not output_path:
        stem = Path(schematic_path).stem
        output_path = str(sch_dir / f"{stem}_flat.kicad_sch")

    # The output starts as a byte-copy of the root with a fresh uuid
    root_uuid_node = flat_root.find("uuid")
    if root_uuid_node is not None:
        root_uuid_node.atoms[1].set_text(str(_uuid_mod.uuid4()))

    # Remember the child files, then drop hierarchy constructs from the output
    child_files = [_sheet_file_cst(s) or "" for s in flat_root.find_all("sheet")]

    # The docstring above promises the original hierarchy is not modified, and
    # output_path was unchecked, so pointing it at an input silently consumed
    # the file being flattened. Narrow on purpose: a bare exists() check would
    # break re-flattening to the same output, which is the normal loop, and the
    # ADR records that refuse-to-clobber in general needs an overwrite
    # parameter first.
    out = Path(output_path).resolve()
    if not out.exists():
        inputs = {Path(schematic_path).resolve()} | {
            (sch_dir / f).resolve() for f in child_files if f
        }
        clash = out in inputs
    else:
        # Only an existing file can be lost, and the root and its own children are not the
        # whole hierarchy: output_path naming a grandchild overwrote it. So walk every
        # sheet. A sheet file resolves against its parent's directory, then the root's, and
        # both are protected. One that cannot be read or parsed stays protected, though
        # what lies below it is unknown.
        def _real(p: Path) -> Path:
            # Before Python 3.13 resolving a symlink loop raises RuntimeError; later
            # versions return the path unresolved.
            try:
                return p.resolve()
            except (OSError, RuntimeError):
                return p.absolute()

        inputs: set[Path] = set()
        todo = [Path(schematic_path)]
        while todo:
            f = todo.pop()
            rf = _real(f)
            if rf in inputs:
                continue
            if len(inputs) >= _MAX_HIERARCHY_FILES:
                raise ToolError(
                    f"The hierarchy under {Path(schematic_path).name} names more than"
                    f" {_MAX_HIERARCHY_FILES} sheet files, so output_path {out.name} could"
                    " not be checked against them and nothing was written."
                )
            inputs.add(rf)
            if not _sheet_file_nonempty(f):
                continue
            try:
                sheet_root = _cst.parse(f.read_bytes()).lists[0]
            except Exception:
                continue
            for s in sheet_root.find_all("sheet"):
                name = _sheet_file_cst(s) or ""
                if name:
                    # KiCad squeezes '..' lexically, so 'zz/../grand.kicad_sch' with no zz
                    # is a sheet to KiCad and missing to the kernel; protect both readings.
                    cands = [f.parent / name, sch_dir / name]
                    cands += [Path(os.path.normpath(c)) for c in cands]
                    todo += [c for c in cands if c.exists()]
        # samefile also catches a case-only alias on a case-insensitive filesystem.
        clash = out in inputs or any(p.exists() and out.samefile(p) for p in inputs)
    if clash:
        raise ToolError(
            f"output_path {out.name} is part of the hierarchy being flattened."
            " Choose a different output file."
        )
    for token in ("sheet", "hierarchical_label", "symbol_instances", "sheet_instances"):
        for node in flat_root.find_all(token):
            flat_root.remove_child(node)

    def _offset_at(node, ox: float, oy: float) -> None:
        n_at = node.find("at")
        if n_at is None:
            return
        n_at.atoms[1].set_text(_num(float(n_at.atoms[1].text) + ox))
        n_at.atoms[2].set_text(_num(float(n_at.atoms[2].text) + oy))

    # Find the max Y extent of root content for offset
    max_y = 0.0
    for sym in flat_root.find_all("symbol"):
        s_at = sym.find("at")
        if s_at is not None:
            max_y = max(max_y, float(s_at.atoms[2].text))
    for token in ("wire", "bus", "polyline"):
        for gi in flat_root.find_all(token):
            pts = gi.find("pts")
            if pts is not None:
                for xy in pts.find_all("xy"):
                    max_y = max(max_y, float(xy.atoms[2].text))

    y_offset = max_y + 50  # Start child content 50mm below root content

    lib_symbols = flat_root.find("lib_symbols")
    existing_lib_names = set()
    if lib_symbols is not None:
        for ls in lib_symbols.find_all("symbol"):
            raw = ls.atoms[1].text
            existing_lib_names.add(raw.split(":")[-1] if ":" in raw else raw)

    sheet_index = 0
    for child_file in child_files:
        child_path = sch_dir / child_file
        if not _sheet_file_nonempty(child_path):
            continue

        child_root = _cst.parse(child_path.read_bytes()).lists[0]
        x_offset = sheet_index * 200  # Space sheets horizontally

        # Merge lib symbols (avoid duplicates, entryName semantics)
        child_libs = child_root.find("lib_symbols")
        if child_libs is not None and lib_symbols is not None:
            for ls in child_libs.find_all("symbol"):
                raw = ls.atoms[1].text
                bare = raw.split(":")[-1] if ":" in raw else raw
                if bare not in existing_lib_names:
                    entries = lib_symbols.find_all("symbol")
                    node = ls.copy()
                    if entries:
                        lib_symbols.insert_after(entries[-1], node)
                    else:
                        lib_symbols.append_child(node, b"\n\t\t")
                    existing_lib_names.add(bare)

        # Merge components with offset
        for sym in child_root.find_all("symbol"):
            new_sym = sym.copy()
            su = new_sym.find("uuid")
            if su is not None:
                su.atoms[1].set_text(str(_uuid_mod.uuid4()))
            _offset_at(new_sym, x_offset, y_offset)
            for prop in new_sym.find_all("property"):
                _offset_at(prop, x_offset, y_offset)
            _splice_sch_node(flat_root, "symbol", new_sym)

        # Merge wires/graphical items with offset
        for token in ("wire", "bus", "polyline", "bus_entry"):
            for gi in child_root.find_all(token):
                new_gi = gi.copy()
                gu = new_gi.find("uuid")
                if gu is not None:
                    gu.atoms[1].set_text(str(_uuid_mod.uuid4()))
                pts = new_gi.find("pts")
                if pts is not None:
                    for xy in pts.find_all("xy"):
                        xy.atoms[1].set_text(_num(float(xy.atoms[1].text) + x_offset))
                        xy.atoms[2].set_text(_num(float(xy.atoms[2].text) + y_offset))
                _splice_sch_node(flat_root, token, new_gi)

        # Merge labels, junctions, and no-connects with offset
        for token in ("label", "global_label", "junction", "no_connect"):
            for item in child_root.find_all(token):
                new_item = item.copy()
                iu = new_item.find("uuid")
                if iu is not None:
                    iu.atoms[1].set_text(str(_uuid_mod.uuid4()))
                _offset_at(new_item, x_offset, y_offset)
                _splice_sch_node(flat_root, token, new_item)

        sheet_index += 1

    _atomic_write(output_path, _cst.serialize(flat_tree))

    total_components = len(flat_root.find_all("symbol"))
    return f"Flattened hierarchy to {Path(output_path).name}: {total_components} components"

def get_version() -> VersionResult:
    """Get KiCad version information including build details and library versions."""
    try:
        result = _run_cli(["version", "--format", "about"], check=False)
    except (RuntimeError, FileNotFoundError) as e:
        raise ToolError(str(e)) from e
    if result.returncode != 0:
        raise ToolError(result.stderr.strip() or f"kicad-cli exited {result.returncode}")
    return VersionResult(version_info=result.stdout.strip())

def get_net_connections(
    label_text: str,
    schematic_path: str = SCH_PATH,
) -> NetConnectionsResult:
    """Find all component pins connected to a net label.

    Scans labels matching the text, traces wires from label positions,
    and identifies component pins at wire endpoints. Each placed symbol
    contributes only its own unit's pins, so a multi-unit part does not
    report a sibling gate's input as sitting on this net.

    Args:
        label_text: Net name to search for (e.g. "VCC", "GND")
        schematic_path: Path to .kicad_sch file. Optional; omit to use the configured default.
    """
    _, root, *_ = _open_sch_cst(schematic_path)
    tol = 0.1

    # Collect all label positions for this net
    label_positions: set[tuple[float, float]] = set()
    for token in ("label", "global_label"):
        for lbl in root.find_all(token):
            if _node_text(lbl) == label_text:
                label_positions.add(_node_xy(lbl))

    # BFS: expand from label positions through connected wire endpoints
    wire_ends = []
    for wire in root.find_all("wire"):
        pts = _wire_xys(wire)
        if len(pts) >= 2:
            wire_ends.append((pts[0], pts[1]))
    reachable: set[tuple[float, float]] = set(label_positions)
    frontier = set(label_positions)
    while frontier:
        next_frontier: set[tuple[float, float]] = set()
        for fx, fy in frontier:
            for (p0x, p0y), (p1x, p1y) in wire_ends:
                if abs(p0x - fx) < tol and abs(p0y - fy) < tol:
                    pt = (p1x, p1y)
                    if pt not in reachable:
                        reachable.add(pt)
                        next_frontier.add(pt)
                elif abs(p1x - fx) < tol and abs(p1y - fy) < tol:
                    pt = (p0x, p0y)
                    if pt not in reachable:
                        reachable.add(pt)
                        next_frontier.add(pt)
        frontier = next_frontier

    # Find component pins at reachable positions
    connections = []
    libs = _connectivity.lib_index(root)
    for sym in root.find_all("symbol"):
        ref = _sym_property_cst(sym, "Reference")
        if ref is None:
            continue
        lib_sym = libs.get(_connectivity.lib_key(sym))
        if lib_sym is None:
            continue
        for unit in _instance_units(lib_sym, _sym_unit_cst(sym), _sym_body_style_cst(sym)):
            for pin in unit.find_all("pin"):
                try:
                    px, py, _ = _connectivity.pin_point_mm(sym, pin, ref)
                except _connectivity.Refusal as e:
                    raise ToolError(e.text) from None
                number = pin.find("number")
                name = pin.find("name")
                for rx, ry in reachable:
                    if abs(px - rx) < tol and abs(py - ry) < tol:
                        connections.append(
                            {
                                "reference": ref,
                                "pin": number.atoms[1].text if number is not None else "",
                                "pin_name": name.atoms[1].text if name is not None else "~",
                                "x": px,
                                "y": py,
                            }
                        )
    return NetConnectionsResult(
        net=label_text,
        label_count=len(label_positions),
        connections=connections,
    )

def get_symbol_info(symbol_name: str, symbol_lib_path: str = SYM_LIB_PATH) -> str:
    """Get detailed pin and property info for a symbol in a library.

    Args:
        symbol_name: Symbol name (e.g. "LM7805")
        symbol_lib_path: Path to .kicad_sym file. Optional; omit to use the configured default.
    """
    _, root = _open_sym_lib(symbol_lib_path)
    for entry in root.find_all("symbol"):
        if entry.atoms[1].text != symbol_name:
            continue
        lines = [f"Symbol: {symbol_name}"]
        for prop in entry.find_all("property"):
            lines.append(f"  {prop.atoms[1].text}: {prop.atoms[2].text}")
        for unit in entry.find_all("symbol"):
            for pin in unit.find_all("pin"):
                at = pin.find("at")
                angle = _numish(at.atoms[3].text) if len(at.atoms) > 3 else 0
                lines.append(
                    f"  Pin {_child_text(pin, 'number')}: {_child_text(pin, 'name')} "
                    f"({pin.atoms[1].text}) "
                    f"@ ({_numish(at.atoms[1].text)}, {_numish(at.atoms[2].text)}) rot={angle}"
                )
        return "\n".join(lines)
    raise ToolError(
        f"'{symbol_name}' not found in {symbol_lib_path}."
        " Use list_lib_symbols to see what the library contains."
    )

def x402_browse(category: Optional[str] = None) -> str:
    """Browse the complete catalog of registered x402 services.

    Args:
        category: Optional category filter: research, data, compute, monitoring,
                  verification, routing, storage, translation, classification,
                  generation, extraction, summarization, enrichment, validation, other.

    Returns:
        Full service catalog with quality tiers, pricing, and health status.
    """
    params: dict = {}
    if category:
        params["category"] = category

    try:
        with httpx.Client(timeout=15.0) as client:
            resp = client.get(f"{DISCOVERY_API}/catalog", params=params)
            resp.raise_for_status()
            data = resp.json()
    except Exception as e:
        return f"Error fetching catalog: {e}"

    services = data.get("services", [])
    total = data.get("total", len(services))

    if not services:
        return f"No services found" + (f" in category '{category}'" if category else "") + "."

    quality_order = {"gold": 0, "silver": 1, "bronze": 2, "unverified": 3}
    services.sort(key=lambda s: quality_order.get(s.get("quality_tier", "unverified"), 3))

    lines = [
        f"x402 Service Catalog — {total} services registered",
        f"Source: {DISCOVERY_API}/catalog\n",
    ]
    for s in services[:20]:
        endpoint = s.get('endpoint_url', s.get('url', '?'))
        if endpoint.startswith('http://'):
            endpoint = endpoint.replace('http://', 'https://', 1)
        lines.append(
            f"• {s.get('name', '?')} [{s.get('quality_tier', 'unverified').upper()}] "
            f"${s.get('price_per_call', '?')}/call\n"
            f"  {s.get('description', '')}\n"
            f"  {endpoint}"
        )

    if total > 20:
        lines.append(f"\n... and {total - 20} more. Full catalog: {DISCOVERY_API}/catalog")

    lines.append(f"\ndiscovery_powered_by: x402-discovery-layer")
    return "\n".join(lines)

def inspect_memory(memory_id: str) -> dict:
    """Inspect one stored memory by id without search, mutation, or embedding exposure."""
    record = _mem.store.get(memory_id)
    if record is None:
        return {"found": False, "id": memory_id}
    return {"found": True, **_serialize_record(record)}

def open_loops(project: str = "", namespace: str = "", limit: int = 20) -> dict:
    """Unresolved commitments — work someone said WOULD be done and never closed — oldest (most
    overdue) first. Continuity is not only facts: check this when resuming so promised work isn't
    silently dropped. Record one with `remember_commitment`; close it with `close_loop`.
    """
    scope = _ns_filter(namespace) or {}
    if project:
        scope["project"] = project
    records = _open_loops_view(_mem, scope=scope or None, limit=int(limit))
    return {"count": len(records), "open_loops": [_serialize_record(r) for r in records]}

def close_loop(loop_id: str, resolution: str) -> str:
    """Close an open commitment: records the resolution and supersedes the open loop with it, so
    `open_loops` stops returning it while the promise -> resolution history stays auditable. Get
    `loop_id` from `open_loops` (the record id).
    """
    try:
        rec = _close_loop_impl(_mem, loop_id, resolution, actor=_ACTOR)
    except ValueError as exc:
        return str(exc)
    return f"loop closed ({loop_id} -> {rec.id})"

