    }

def stats(namespace: str = "") -> dict:
    """Memory stats: total count, breakdown by kind, namespace, and the temporal-tier distribution.

    tiers: short (<= 1 day) / medium (<= 1 week) / long (older) — the short/medium/multi-day horizons.
    Pass namespace to scope the counts to one project/agent scope.
    """
    ns = _ns(namespace)
    by_kind: dict[str, int] = {}
    by_provenance: dict[str, int] = {p: 0 for p in MEMORY_PROVENANCE}
    by_tier: dict[str, int] = {"short": 0, "medium": 0, "long": 0}
    by_namespace: dict[str, int] = {}
    for record in _mem.store.all():
        rec_ns = record.metadata.get("namespace") or "(none)"
        by_namespace[rec_ns] = by_namespace.get(rec_ns, 0) + 1
        if ns and record.metadata.get("namespace") != ns:
            continue
        by_kind[record.kind] = by_kind.get(record.kind, 0) + 1
        by_provenance[record.provenance] = by_provenance.get(record.provenance, 0) + 1
        by_tier[_mem.tier(record)] += 1
    return {
        "total": sum(by_kind.values()),
        "namespace": ns or None,
        "by_kind": by_kind,
        "by_provenance": by_provenance,
        "by_tier": by_tier,
        "by_namespace": by_namespace,
        "guard_uses": list(MEMORY_USES),
    }

def get_case_study(repo: str, pr_number: int) -> dict:
        """Get a specific PR case study with full details and rounds.

        Returns the complete case study including frontmatter, body text,
        and round-by-round interaction history. Useful for learning from
        past PR experiences.

        Args:
            repo: Repository in org/name format
            pr_number: PR number (integer)

        Returns:
            dict with frontmatter, body, path, or error if not found
        """
        for c in iter_case_studies(rr):
            fm = c["frontmatter"]
            if (
                fm.get("repo", "").strip("/").lower() == repo.strip("/").lower()
                and str(fm.get("pr_number")) == str(pr_number)
            ):
                return {"frontmatter": fm, "body": c["body"], "path": c["path"]}
        return {"error": f"case study not found: {repo}#{pr_number}"}

